      previewExposure = '',
      previewRevision = -1,
      previewBitmap = -1;
    let previousRenderer: typeof previewRenderer = undefined;
    const movieClock = createMovieTreeClock();
    const authoringClock = createMovieTreeClock();
    let authoringClockRevision = -1;
    let authoringClockSource: Project | undefined;
    let authoringClockInput: { frame: number; seconds: number; position: number } | undefined;
    let upButtons: ReturnType<typeof createUpButtonPlayback> | undefined;
    const buttonMovies = createRootButtonMoviePlayback();
    const buttonExposures = createButtonExposureRuntime<string>();
    const buttonStateEpochs = new SvelteMap<string, number>();
    let playbackPosition = frame,
      playPosition = frame;
    let movieSignature = '';
    let buttonView: ReturnType<typeof createInteractiveButtonView> | null = null;
    let buttonSnapshot: ReturnType<
      ReturnType<typeof createInteractiveButtonView>['sample']
    > | null = null;
    let buttonProject: Project | null = null;
    let buttonRevision = -1;
    let previousButtonPosition: number | undefined;
    let buttonContext = '',
      buttonSignature = '';
    const tick = (time: number) => {
      if(preview&&previewRemembered&&previewValidate){
        try{previewValidate();}catch(cause){failRememberedMovie(cause);raf=requestAnimationFrame(tick);return;}
      }
      const runtime=previewCapture??project;
      const opacityAt=previewCapture?previewOpacity:stageOpacity.at;
      if (previousRenderer !== previewRenderer) {
        playbackPosition = frame;
        wasPlaying = false;
        previousRenderer = previewRenderer;
        previewProject = null;
        movieClock.reset();
        buttonMovies.reset();
        buttonExposures.reset();
        buttonStateEpochs.clear();
        buttonView = null;
        buttonSnapshot = null;
        buttonProject = null;
        buttonContext = '';
      }
      timelineAutoscroll(time);
      const audioOwner=timelineAudio;
      if(audioOwner&&!ownsTimelineAudio(audioOwner)){
        stopTimelineAudio();
        if(audioOwner.loop)playing=false;
      }
      let audioPosition:ReturnType<NonNullable<TimelineAudioJob['loop']>['position']>|undefined;
      try{audioPosition=timelineAudio?.loop?.position();}
      catch(cause){stopTimelineAudio();playing=false;error=String(cause);}
      if (playing) {
        if (!wasPlaying) {
          started = time;
          startFrame = frame;
          playPosition = timelineAudio?.first ?? (previewRenderer ? playbackPosition : frame);
        }
        frame = audioPosition?.frame ??
          (startFrame + frameAtTime((time - started) / 1000, runtime.fps, runtime.duration)) %
          runtime.duration;
        playbackPosition = audioPosition?.absoluteFrame ??
          playPosition + Math.floor(Math.max(0, (time - started) / 1000) * runtime.fps);
      }
      wasPlaying = playing;
      if (playing && !previewRenderer && project.symbols?.length) {
        try {
          if (authoringClockRevision !== historyTick || authoringClockSource !== project) {
            authoringClock.reset();
            authoringClockSource = project;
            authoringClockInput = undefined;
            authoringButtonPose = undefined;
            upButtons = project.symbols.some(d => d.buttonStates) ? createUpButtonPlayback(project) : undefined;
          }
          authoringClockRevision = historyTick;
          const seconds = (playbackPosition - playPosition) / project.fps;
          // Several display callbacks can share one authored frame and clock position.
          if (!authoringMovieFrames || authoringClockInput?.frame !== frame ||
              authoringClockInput.seconds !== seconds || authoringClockInput.position !== playbackPosition) {
            const sampled = authoringClock.sample(project, frame, seconds, playbackPosition);
            if (JSON.stringify(sampled) !== JSON.stringify(authoringMovieFrames)) authoringMovieFrames = sampled;
            if (upButtons && authoringButtonPose?.position !== playbackPosition) {
              const pose = upButtons(frame, playbackPosition, seconds, sampled, authoringClock.origins(), stageOpacity.at);
              if (hasMaskChain(pose.project.layerMasks) || graphicBlurPresent || pose.project.symbols?.some(d => d.timeline?.layerMasks?.length)) {
                const masked = maskedButtonPose(pose.project, frame, sampled, pose.snapshot.buttons, pose.stateFrames, null, null);
                authoringButtonPose = { position: playbackPosition, project: pose.project, masked };
              } else authoringButtonPose = { position: playbackPosition, project: pose.snapshot.render(null, null, pose.artwork, pose.stateFrames) };
            }
            authoringClockInput = { frame, seconds, position: playbackPosition };
          }
        } catch (cause) { playing = false; error = String(cause); }
      } else if (authoringClockRevision !== -1) {
        authoringClock.reset(); authoringClockRevision = -1; authoringMovieFrames = undefined;
        authoringClockSource = undefined; authoringClockInput = undefined; upButtons = undefined; authoringButtonPose = undefined;
      }
      if (
        !previewRenderer ||
        previousRenderer !== previewRenderer ||
        previewRevision !== historyTick
      )
        movieClock.reset();
      let movieFrames: Record<string, number> = {};
      if (previewRenderer) {
        try {
          movieFrames = movieClock.sample(runtime, frame, time / 1000, playbackPosition);
        } catch (e) {
          if(previewRemembered)failRememberedMovie(e);else{closePreview();status=String(e);}
          raf = requestAnimationFrame(tick);
          return;
        }
      }
      const renewedButtons = new SvelteSet<string>();
      if (previewRevision !== historyTick) {
        buttonMovies.reset();
        buttonExposures.reset();
        buttonStateEpochs.clear();
      }
      if (previewRenderer) {
        try {
          if (buttonProject !== runtime || buttonRevision !== historyTick) {
            previousButtonPosition = undefined;
            buttonView = runtime.symbols?.some((d) => d.buttonStates)
              ? createInteractiveButtonView(runtime)
              : null;
            buttonProject = runtime;
            buttonRevision = historyTick;
            buttonContext = '';
          }
          const origins = movieClock.origins();
          const requestedDown = testKey || testPressed === testOver ? testPressed : null;
          const context = JSON.stringify([
            historyTick,
            frame,
            movieFrames,
            origins,
            testOver,
            requestedDown,
            time,
          ]);
          if (context !== buttonContext) {
            const previousPoses = new Map(
              testButtons.map((b) => [b.token, JSON.stringify(b.shape)]),
            );
            buttonSnapshot =
              buttonView?.sample(frame, movieFrames, origins, testOver, requestedDown, (button, rootExposure, movieEntry) => {
                const epoch =
                  button.start === 0 && button.end === runtime.duration
                    ? 0
                    : Math.floor((playbackPosition - button.start) / runtime.duration);
                if (
                  buttonStateEpochs.has(button.token) &&
                  buttonStateEpochs.get(button.token) !== epoch
                ) {
                  buttonMovies.invalidate(new Set([button.token]));
                  renewedButtons.add(button.token);
                }
                buttonStateEpochs.set(button.token, epoch);
                const state = buttonMovies.sample(
                  runtime,
                  [button],
                  testOver,
                  requestedDown,
                  time / 1000,
                  false,
                  playing && rootExposure ? crossedButtonEntry(button.start, button.end, runtime.duration,
                    previousButtonPosition, playbackPosition, started / 1000 + (playbackPosition - playPosition) / runtime.fps, runtime.fps) : movieEntry,
                );
                return {
                  entrySeconds: buttonMovies.entrySeconds(button.token),
                  frames: state.stateFrames.get(button.token)!,
                  origins: state.stateOrigins.get(button.token)!,
                };
              }) ?? null;
            testButtons = buttonSnapshot?.buttons ?? [];
            const activeTokens = new Set(testButtons.map((b) => b.token));
            for (const token of buttonStateEpochs.keys())
              if (!activeTokens.has(token)) buttonStateEpochs.delete(token);
            // A moved target cancels input without expiring its independent movie session.
            const unchangedPose = (token: string) =>
              testButtons.some(
                (b) => b.token === token && previousPoses.get(token) === JSON.stringify(b.shape),
              );
            if (testPressed && !unchangedPose(testPressed)) resetTestButtonPress();
            if (!testButtons.some((b) => b.token === testFocused))
              testFocused = testButtons[0]?.token ?? null;
            if (testOver && !unchangedPose(testOver)) testOver = null;
            buttonContext = context;
            previousButtonPosition = playbackPosition;
          }
        } catch (e) {
          if(previewRemembered)failRememberedMovie(e);else{closePreview();status=String(e);}
          raf = requestAnimationFrame(tick);
          return;
        }
      }
      const expiredButtons = buttonExposures.sample(
        previewRenderer
          ? testButtons.map((b) => ({ id: b.token, start: b.start, end: b.end }))
          : [],
        runtime.duration,
        playbackPosition,
      );
      if (testPressed && expiredButtons.has(testPressed)) resetTestButtonPress();
      if (testOver && expiredButtons.has(testOver)) testOver = null;
      // Currently visible epochs were renewed while discovering their children.
      buttonMovies.invalidate(new Set([...expiredButtons].filter(token => !renewedButtons.has(token))));
      const buttonDown = testKey || testPressed === testOver ? testPressed : null;
      let animatedButtons: ReturnType<typeof buttonMovies.sample>;
      try {
        animatedButtons = buttonMovies.sample(
          runtime,
          previewRenderer ? testButtons : [],
          testOver,
          buttonDown,
          time / 1000,
        );
      } catch (e) {
        if(previewRemembered)failRememberedMovie(e);else{closePreview();status=String(e);}
        raf = requestAnimationFrame(tick);
        return;
      }
      const nextButtonSignature = JSON.stringify([
        testOver,
        testPressed,
        testKey,
        animatedButtons.signature,
        buttonSnapshot?.signature,
      ]);
      const nextMovieSignature = JSON.stringify(movieFrames);
      const exposure = previewRenderer
        ? runtime.layers.map((l) => `${l.id}:${l.visible}:${keyAt(l, frame).frame}`).join('|')
        : '';
      const frameSensitive = opacityAt || runtime.symbols?.some((s) => s.timeline);
      const nextExposure = frameSensitive ? exposure + ':' + frame : exposure;
      if (
        previewRenderer &&
        (previousRenderer !== previewRenderer ||
          previewProject !== runtime ||
          previewExposure !== nextExposure ||
          movieSignature !== nextMovieSignature ||
          buttonSignature !== nextButtonSignature ||
          previewRevision !== historyTick ||
          previewBitmap !== bitmapRevision)
      ) {
        try {
          const view = opacityAt?.(frame)??runtime;
          // Interaction uses runtime Hit geometry. Paint reuses the same clock samples.
          let paintSnapshot = buttonSnapshot;
          if (view !== runtime && buttonSnapshot) {
            paintSnapshot = createInteractiveButtonView(view).sample(
              frame, movieFrames, movieClock.origins(), testOver, buttonDown,
              (button) => ({
                frames: animatedButtons.stateFrames.get(button.token) ?? {},
                origins: animatedButtons.stateOrigins.get(button.token) ?? {},
              }),
            );
          }
          testMaskedPose = paintSnapshot && (hasMaskChain(view.layerMasks) || graphicBlurPresent || view.symbols?.some(d => d.timeline?.layerMasks?.length))
            ? maskedButtonPose(view, frame, movieFrames, paintSnapshot.buttons, animatedButtons.stateFrames, testOver, buttonDown)
            : undefined;
          const presented = testMaskedPose ? view : paintSnapshot?.render(
            testOver, buttonDown, view === runtime ? animatedButtons.artwork : undefined,
            animatedButtons.stateFrames,
          ) ?? view;
          previewRenderer.render(presented, frame, movieFrames, testMaskedPose?.tracks);
        } catch (cause) {
          if(previewRemembered)failRememberedMovie(cause);else{closePreview();status=String(cause);}
          raf = requestAnimationFrame(tick);
          return;
        }
        buttonSignature = nextButtonSignature;
        movieSignature = nextMovieSignature;
        previousRenderer = previewRenderer;
        previewProject = runtime;
        previewExposure = nextExposure;
        previewRevision = historyTick;
        previewBitmap = bitmapRevision;
      }
      raf = requestAnimationFrame(tick);
    };
    raf = requestAnimationFrame(tick);
    const timer = setInterval(() => void autosave(), 15000);
    const unload = (e: BeforeUnloadEvent) => {
      if (dirty || scopedSymbol?.source.dirty || openDocuments.some(entry => entry.state?.dirty)) {
        refreshDocumentRecovery();
        e.preventDefault();
        e.returnValue = '';
      }
    };
    window.addEventListener('beforeunload', unload);
    canvas.addEventListener('wheel', wheelZoom, { passive: false });
    return () => {
      cancelSampledStageDrag();
      cancelHierarchyDrag();
      observer.disconnect();
      cancelAnimationFrame(raf);
      stopTimelineAudio();
      clearInterval(timer);
      window.removeEventListener('beforeunload', unload);
      canvas.removeEventListener('wheel', wheelZoom);
      htmlAudioExport?.abort();pngExport?.abort();pngExport=null;gifExport?.abort();gifExport=null;
      closePreview(false);
    };
  });
  const symbolConversionBlocked = $derived(busy || !!gesture || !!penDraft || !!pendingDrawingJobs || !!groupScope.length || activeLayer.locked || !activeLayer.visible || liveInputBlocked() || sampledStageMode || !!liveCurveConfig || multiFrame || (!selected.length && !paintRegion.length));
</script>

{#if crossGroupDraft}<CrossLayerGroup project={crossGroupDraft.project} frame={crossGroupDraft.frame} preferred={crossGroupDraft.preferred} selection={crossGroupDraft.selection} maskedLayer={crossGroupDraft.maskedLayer} apply={async(request,admit)=>{await publishCrossLayerChange(request,undefined,admit);}} cancel={dismissCrossLayerGroup}/>{/if}
{#if scopedTimeline}
  {@const owner = scopedTimeline}
  {#await import('./SymbolTimeline.svelte')}
    <SymbolLoading cancel={() => void closeScopedTimeline(owner)} />
  {:then { default: SymbolTimeline }}
    {#key owner}
      <SymbolTimeline
        definition={owner.definition}
        assets={owner.source.assets}
        symbols={owner.source.symbols ?? []}
        fps={owner.source.fps}
        context={owner.current.scope.session.context}
        location={{ layerId: owner.current.state.layerId, frame: owner.current.state.frame }}
        hierarchyOwner={String(owner.current.state.historyTick)}
        readSourceProject={() => {
          if (scopedTimeline !== owner) throw Error('The original Advanced Timeline closed.');
          owner.verify();
          return { project: owner.source, revision: owner.current.state.historyTick };
        }}
        validate={definition => { prepareScopedTimeline(owner, definition); }}
        apply={(definition, admit) => applyScopedTimeline(owner, definition, admit)}
        cancel={() => void closeScopedTimeline(owner)}
      />
    {/key}
  {:catch}
    <SymbolLoading failed cancel={() => void closeScopedTimeline(owner)} />
  {/await}
{/if}
<svelte:window ondragover={preventFileDropNavigation} ondrop={preventFileDropNavigation} onscroll={()=>{if(sampledStageDrag?.groupCurve||sampledStageDrag?.rootCurve||sampledStageDrag?.rootWaypoint||sampledStageDrag?.group||sampledStageDrag?.node||sampledStageDrag?.tangent||sampledStageDrag?.compound||sampledStageDrag?.compoundNode||sampledStageDrag?.pivot)cancelSampledStageDrag();}} onblur={()=>{endRegrab();timelineEdit.cancel();spaceHand=false;temporarySelectionHeld=false;hoverShift=false;canvasTouch.end();endCanvasPan();stageDispatch.blurAuthored();cancelSampledStageDrag();cancelHierarchyDrag();}} onkeydown={keyboard} onpaste={pasteCanvasArtwork} onkeyup={(e) => {hoverAlt=e.altKey;hoverShift=e.shiftKey;if(e.key===' ')spaceHand=false;if(!e.ctrlKey&&!e.metaKey)temporarySelectionHeld=false;}} />
{#if symbolEditing&&!symbolEditing.workspace}
  {#if symbolEditing.timeline}
    {#await import('./SymbolTimeline.svelte')}
      <SymbolLoading cancel={() => (symbolEditing = null)} />
    {:then { default: SymbolTimeline }}
      {#key symbolEditing.id}
        <SymbolTimeline
          readSourceProject={()=>({project,revision:historyTick})}
          stageSimplify={symbolEditing.context&&symbolEditing.stagePath?admitStageSymbolSession:undefined}
          navigate={symbolEditing.context ? navigateNestedSymbol : undefined}
          location={symbolEditing.location}
          returnTo={symbolEditing.parent ? returnSymbolContext : undefined}
          returnName={symbolEditing.parent?.definition.name}
          definition={symbolEditing.definition}
          hierarchyOwner={JSON.stringify([projectRenderSignature,historyTick,frame,symbolEditing.id])}
          context={symbolEditing.context}
          symbols={project.symbols ?? []}
          assets={project.assets}
          fps={project.fps}
          validate={(definition) =>
            updateSymbolTimeline(clone(project), symbolEditing!.id, definition)}
          apply={applySymbolTimelineDraft}
          cancel={() => {
            symbolEditing = null;
          }}
        />
      {/key}
    {:catch}
      <SymbolLoading failed cancel={() => (symbolEditing = null)} />
    {/await}
  {:else}
    {#await import('./SymbolEditor.svelte')}
      <SymbolLoading cancel={() => (symbolEditing = null)} />
    {:then { default: SymbolEditor }}
      {#key symbolEditing.id}
        <SymbolEditor
          returnTo={symbolEditing.parent ? returnSymbolContext : undefined}
          returnName={symbolEditing.parent?.definition.name}
          navigate={symbolEditing.context ? navigateNestedSymbol : undefined}
          definition={symbolEditing.definition}
          hierarchyOwner={JSON.stringify([projectRenderSignature,historyTick,frame,symbolEditing.id])}
          context={symbolEditing.context}
          symbols={project.symbols ?? []}
          assets={project.assets}
          apply={applySymbolContents}
          frameSimplify={newFrameSymbolSimplifyAvailable()||stageStaticSymbolSimplifyAvailable()&&!!symbolEditing.definition.buttonStates}
          simplify={newSymbolSimplifyAvailable()?newSymbolSimplifyContext:staticSymbolSimplifyAvailable()?staticSymbolSimplifyContext:stageStaticSymbolSimplifyAvailable()?stageStaticSymbolSimplifyContext:undefined}
          validate={(artwork) => { if (symbolEditing?.newDefinition) prepareLibrarySymbolArtwork(artwork); else updateSymbolArtwork(clone(project), symbolEditing!.id, artwork); }}
          cancel={() => {
            symbolEditing = null;
          }}
        />
      {/key}
    {:catch}
      <SymbolLoading failed cancel={() => (symbolEditing = null)} />
    {/await}
  {/if}
{/if}
{#if contextMenu}{#key contextMenu}<ContextMenu {...contextMenu} close={closeContext} />{/key}{/if}
{#if helpDialog === 'about'}
