{#if modal === 'preferences'}
  <PreferencesWindow close={closePreferences} {desktop}>
    {#snippet plugins()}<PluginPreferences />{/snippet}
    {#snippet themes()}<ThemePreferences />{/snippet}
    {#snippet general()}
      <div class="preference-fields">
        <label>Zoom with the mouse wheel <input type="checkbox" bind:checked={wheelZoomByDefault} /></label>
        <p class="hint">When off, hold Ctrl or Command while scrolling to zoom.</p>
        <label>Minimum canvas zoom (%) <input type="number" step="0.1"
          min={canvasZoomPercent(CANVAS_ZOOM_FLOOR)} max={canvasZoomPercent(maxCanvasZoom)} value={canvasZoomPercent(minCanvasZoom)}
          onchange={e => minCanvasZoom = zoomPreference(e.currentTarget, minCanvasZoom, CANVAS_ZOOM_FLOOR, maxCanvasZoom)} /></label>
        <label>Maximum canvas zoom (%) <input type="number" step="0.1"
          min={canvasZoomPercent(minCanvasZoom)} max={canvasZoomPercent(CANVAS_ZOOM_CEILING)} value={canvasZoomPercent(maxCanvasZoom)}
          onchange={e => maxCanvasZoom = zoomPreference(e.currentTarget, maxCanvasZoom, minCanvasZoom, CANVAS_ZOOM_CEILING)} /></label>
        <label>Show rulers <input type="checkbox" bind:checked={rulersVisible} /></label>
        <label>Show guides <input type="checkbox" bind:checked={guidesVisible} /></label>
        <label>Snap to guides <input type="checkbox" bind:checked={snapGuides} /></label>
        <label>Snap to objects <input type="checkbox" bind:checked={snapObjects} /></label>
        <label>Snap to grid <input type="checkbox" bind:checked={snapGrid} /></label>
      </div>
    {/snippet}
    {#snippet touch()}
      <div class="preference-fields">
        <label>Pinch to zoom canvas <input type="checkbox" bind:checked={pinchZoom} /></label>
        <label>One finger on canvas
          <select bind:value={singleTouch}>
            <option value="pan">Pan canvas</option><option value="tool">Use selected tool</option><option value="ignore">Ignore</option>
          </select>
        </label>
        <p class="hint">Pinch around the midpoint of two fingers. A pen can draw while one-finger touch is set to pan.</p>
      </div>
    {/snippet}
    {#snippet pen()}
      <div class="preference-fields">
        <label>Pressure controls size <input type="checkbox" bind:checked={pressureSize} /></label>
        <label>Minimum brush size
          <select bind:value={minimumSize}><option value={0.05}>5%</option><option value={0.1}>10%</option>
            <option value={0.25}>25%</option><option value={0.5}>50%</option></select>
        </label>
        <label>Pressure response <input type="number" min="0.25" max="4" step="0.25" value={brushResponse}
          onchange={e => brushResponse = preferenceNumber(e.currentTarget, brushResponse, 0.25, 4)} /></label>
        <label>Tilt controls nib <input type="checkbox" bind:checked={tiltNib} /></label>
        <label>Twist rotates nib <input type="checkbox" bind:checked={twistNib} /></label>
        <label>Pressure controls opacity
          <select bind:value={pressureOpacity}>
            <option value="off">Off</option><option value="initial">At stroke start</option><option value="continuous">Throughout stroke</option>
          </select>
        </label>
        {#if pressureOpacity !== 'off'}
          <label>Minimum opacity (%) <input type="number" min="0" max="100" value={contactOpacityMinimum}
            onchange={e => contactOpacityMinimum = preferenceNumber(e.currentTarget, contactOpacityMinimum, 0, 100)} /></label>
          <label>Opacity response <input type="number" min="0.25" max="4" step="0.25" value={contactOpacityResponse}
            onchange={e => contactOpacityResponse = preferenceNumber(e.currentTarget, contactOpacityResponse, 0.25, 4)} /></label>
          <p class="hint">Use separate Brush objects in Normal or Behind mode. Continuous opacity also requires a fixed nib.</p>
        {/if}
        <label>Keep brush size on screen <input type="checkbox" bind:checked={brushScreenSize} /></label>
        <label>Brush size <input type="number" min="1" max="200" value={brushSize}
          onchange={e => brushSize = preferenceNumber(e.currentTarget, brushSize, 1, 200)} /></label>
        <label>Brush stabilization <input type="number" min="0" max="100" value={stabilization}
          onchange={e => stabilization = preferenceNumber(e.currentTarget, stabilization, 0, 100)} /></label>
        <label>Brush simplify (%) <input type="number" min="0" max="200" value={brushSmoothing}
          onchange={e => brushSmoothing = preferenceNumber(e.currentTarget, brushSmoothing, 0, 200)} /></label>
        <label>Optimize brush strokes <input type="checkbox" bind:checked={brushOptimize} /></label>
        <label>Remove covered strokes in Merge Drawing <input type="checkbox" bind:checked={removeCoveredStrokes} /></label>
      </div>
    {/snippet}
    {#snippet pencil()}
      <div class="preference-fields">
        <label>Pencil simplify (%) <input type="number" min="0" max="200" value={pencilSmoothing}
          onchange={e => pencilSmoothing = preferenceNumber(e.currentTarget, pencilSmoothing, 0, 200)} /></label>
        <label>Optimize pencil lines <input type="checkbox" bind:checked={pencilOptimize} /></label>
      </div>
    {/snippet}
    {#snippet workspace()}
      <WorkspaceManager embedded layout={panelLayout} change={next => panelLayout = next} />
    {/snippet}
    {#snippet codeEditor()}
      <CodeEditorPreferences />
    {/snippet}
    {#snippet shortcuts()}
      <ShortcutEditor embedded bindings={shortcutOverrides} mac={macShortcuts} change={updateShortcuts} />
    {/snippet}
  </PreferencesWindow>
{/if}
<div class="app-shell">
  <nav class="menubar" class:desktop-menubar={desktop} aria-label="Application menu" inert={!desktop && !!symbolEditing?.workspace}>
    <div class="brand" role="img" aria-label="Splash Animator">
      <img class="brand-mark" src={splashMark} alt="" /><span>SPLASH</span>
    </div>
    {#each applicationMenuNames as name}<div class="menu-host" inert={desktop && !!symbolEditing?.workspace}
        onfocusout={(event) => {
          if(menu===name&&event.relatedTarget instanceof Node&&!event.currentTarget.contains(event.relatedTarget))menu='';
        }}>
        <button class:active={menu === name} data-application-menu={name} data-help-menu={name === 'Help' ? '' : undefined} data-workspace-menu={name === 'Window' ? '' : undefined}
          aria-expanded={menu===name} aria-controls={menu===name?`application-menu-${name}`:undefined}
          onclick={(event) => toggleApplicationMenu(name,event)}
          >{name}</button
        >
        {#if menu === name}<div class="dropdown" class:window-menu={name==='Window'} id={`application-menu-${name}`}>
            {#if name === 'File'}<button disabled={documentActionBlocked()} onclick={newDocument}>New project</button><button
                disabled={!!scopedSymbol} onclick={openDialog}>Open .spl folder…{#if shortcutLabel('open')} <kbd>{shortcutLabel('open')}</kbd>{/if}</button
              ><button disabled={busy || (!scopedSymbol && !license.savingAllowed)} onclick={() => save()}>{scopedSymbol ? 'Save symbol' : 'Save'}{#if shortcutLabel('save')} <kbd>{shortcutLabel('save')}</kbd>{/if}</button><button
                disabled={busy || !!scopedSymbol || !license.savingAllowed}
                onclick={() => saveAs()}>Save As / duplicate…</button
              >
              <hr />
              <button disabled={exportSettingsBlocked} onclick={()=>openExport()}>Export…</button>
              <button disabled={libraryImportBlocked()} onclick={openFontImport}>Embed project font…</button>
              <button disabled={exportSettingsBlocked} onclick={()=>openExport('html')}>Export HTML animation…</button>
              <button disabled={license.savingAllowed ? busy || desktop || !!scopedSymbol : exportSettingsBlocked}
                onclick={()=>license.savingAllowed ? downloadPNG() : openExport('still', 'png')}>Export current frame PNG…</button>
              <button disabled={exportSettingsBlocked} onclick={()=>openExport('still')}>Export single frame…</button>
              <hr />
              <button disabled={busy || !!modal || preview || playing || !!canvasResize || !!stageText || !!penDraft} onclick={openPreferences}>Preferences…</button>
            {:else if name === 'Edit'}<button disabled={activeLayer.locked||(!selected.length&&!paintRegion.length)} onclick={()=>chooseSelectionTransformMode('free')}>Free transform selection{#if shortcutLabel('free')} <kbd>{shortcutLabel('free')}</kbd>{/if}</button><button disabled={activeLayer.locked||(!selected.length&&!paintRegion.length)} onclick={()=>chooseSelectionTransformMode('rotate-skew')}>Rotate and skew selection</button><hr /><button disabled={symbolConversionBlocked} onclick={()=>openSymbolConversion('graphic')}>Convert to symbol…{#if shortcutLabel('symbol')} <kbd aria-hidden="true">{shortcutLabel('symbol')}</kbd>{/if}</button><button disabled={symbolConversionBlocked} onclick={()=>openSymbolConversion('movie')}>Convert to movie clip…</button><hr /><button
                disabled={!undoLabel}
                onclick={() => {
                  undo();
                  menu = '';
                }}>Undo {undoLabel ?? ''}{#if shortcutLabel('undo')} <kbd>{shortcutLabel('undo')}</kbd>{/if}</button
              ><button
                disabled={!redoLabel}
                onclick={() => {
                  undo(true);
                  menu = '';
                }}>Redo {redoLabel ?? ''}{#if shortcutLabel('redo')} <kbd>{shortcutLabel('redo')}</kbd>{/if}</button
              >
              <hr />
              <button
                disabled={crossLayerMode?(multiSelection!==null&&!multiSelection.length):activeLayer.locked ||
                  activeLayer.drawingMode === 'merge' ||
                  new Set(
                    shapes
                      .filter((s) => selected.includes(s.id))
                      .map((s) => selectionUnit(s, groupScope.length)),
                  ).size < 2}
                onclick={() => groupSelection()}>Group selection{#if shortcutLabel('group')} <kbd>{shortcutLabel('group')}</kbd>{/if}</button
              >
              <button
                disabled={crossLayerMode?(multiSelection!==null&&!multiSelection.length):activeLayer.locked || !groupedSelection}
                onclick={() => groupSelection(true)}
                >Ungroup selection{#if shortcutLabel('ungroup')} <kbd>{shortcutLabel('ungroup')}</kbd>{/if}</button
              >
              <button
                disabled={!groupedSelection}
                onclick={() => {
                  enterGroup();
                  menu = '';
                }}>Edit group</button
              >
              <button
                disabled={crossLayerMode?!multiSelection?.length:activeLayer.locked || !activeLayer.visible}
                onclick={() => {
                  copySelection();
                  menu = '';
                }}>Copy <kbd>{shortcutText('Primary+c',macShortcuts)}</kbd></button
              >
              <button
                disabled={crossLayerMode?!multiSelection?.length:activeLayer.locked || !activeLayer.visible}
                onclick={() => {
                  copySelection(true);
                  menu = '';
                }}>Cut <kbd>{shortcutText('Primary+x',macShortcuts)}</kbd></button
              >
              <button
                disabled={crossLayerMode?!crossClipboard:activeLayer.locked || !activeLayer.visible}
                onclick={() => {
                  paintRegion = [];
                  duplicateSelection(true);
                  menu = '';
                }}>Paste <kbd>{shortcutText('Primary+v',macShortcuts)}</kbd></button
              >
              <button
                disabled={crossLayerMode?!crossClipboard:activeLayer.locked || !activeLayer.visible}
                onclick={() => {
                  paintRegion = [];
                  duplicateSelection(true, true);
                  menu = '';
                }}>Paste in place{#if shortcutLabel('pasteInPlace')} <kbd>{shortcutLabel('pasteInPlace')}</kbd>{/if}</button
              >
              <button disabled={!license.savingAllowed || systemCopyPending || systemPastePending || !selected.length || !!scopedSymbol} onclick={() => copySystemArtwork('png')}>Copy selection as PNG (stage size)</button>
              <button disabled={systemPastePending || systemCopyPending || !!scopedSymbol} onclick={() => pasteSystemArtwork('png')}>Paste PNG from system clipboard</button>
              {#if scopedSymbol}
                <button disabled={systemPastePending || systemCopyPending || !canUseSystemArtwork('text')} onclick={() => pasteSystemArtwork('text')}>Paste plain text from clipboard</button>
              {/if}
              <button disabled={systemPastePending || systemCopyPending || !canUseSystemArtwork('external')} onclick={() => pasteSystemArtwork('external')}>Paste image or text from clipboard</button>
              <button disabled={!license.savingAllowed || systemCopyPending || systemPastePending || !selected.length || !!scopedSymbol && !canUseSystemArtwork('artwork')} onclick={() => copySystemArtwork('artwork')}>Copy editable Splash Artwork JSON</button>
              <button disabled={systemPastePending || systemCopyPending || !!scopedSymbol && !canUseSystemArtwork('artwork')} onclick={() => pasteSystemArtwork('artwork')}>Paste editable Splash Artwork JSON</button>
              <button
                disabled={crossLayerMode?!multiSelection?.length:!selected.length}
                onclick={() => {
                  duplicateSelection();
                  menu = '';
                }}>Duplicate selection{#if shortcutLabel('duplicate')} <kbd>{shortcutLabel('duplicate')}</kbd>{/if}</button
              ><button
                disabled={crossLayerMode?!multiSelection?.length:!selected.length&&!paintRegion.length}
                onclick={() => {
                  removeSelection();
                  menu = '';
                }}>Delete selection</button
              >
              <hr />
              {#each ['fill', 'stroke'] as part}
                <button
                  disabled={activeLayer.locked ||
                    !activeLayer.visible ||
                    busy ||
                    !primary ||
                    paintKey(primary, part as PaintPart) === undefined}
                  onclick={() => matchPaint(part as PaintPart)}>Select matching {part} paint</button
                >
              {/each}
              <button
                disabled={activeLayer.locked ||
                  activeLayer.drawingMode === 'merge' ||
                  selected.length !== 2 ||
                  groupedSelection}
                onclick={joinSelectedBezier}>Join Bezier endpoints</button
              >
            {:else if name === 'Window'}
              {#if desktop}<button onclick={() => { menu = ''; helpDialog = 'plugins'; }}>Plugins…</button>{/if}
              <button disabled={documentActionBlocked()} onclick={event => openSceneManager(event.currentTarget)}>Scenes…</button>
              <button disabled={busy} onclick={()=>{if(panelOpen){menu='';panelSelected=true;scriptWindow?.focus();}else openFrameSource();}}>Script Editor{#if shortcutLabel('script')} <kbd aria-hidden="true">{shortcutLabel('script')}</kbd>{/if}</button>
              {#if !desktop}
                <button disabled={busy} onclick={()=>openBrowserScriptPanel('popup')}>Pop Out Script Editor</button>
                {#if supportsScriptPictureInPicture()}
                  <button disabled={busy} onclick={()=>openBrowserScriptPanel('picture-in-picture')}>Always-on-top Script Editor</button>
                {/if}
              {/if}
              <button disabled={documentActionBlocked()} onclick={()=>{menu='';workspaceManagerOpen=true;}}>Workspaces…</button>
              <button disabled={documentActionBlocked()} onclick={()=>{menu='';shortcutsOpen=true;}}>Keyboard Shortcuts…</button>
              <button aria-pressed={panelLayout.sidebarVisible} onclick={()=>panelLayout={...panelLayout,sidebarVisible:!panelLayout.sidebarVisible}}>Show properties sidebar</button>
              <hr />
              {#each PANEL_CATALOG as [id,label]}<button aria-pressed={!panelLayout.hidden.includes(id)} onclick={()=>{panelLayout=togglePanel(panelLayout,id,'hidden');if(!panelLayout.hidden.includes(id))panelLayout={...panelLayout,sidebarVisible:true,sidebarCollapsed:false};}}><span aria-hidden="true">{panelLayout.hidden.includes(id)?'　':'✓'} </span>{label}</button>{/each}
              <hr />
              <button onclick={()=>panelLayout={...panelLayout,sidebarVisible:true,sidebarCollapsed:false,hidden:[]}}>Show all panels</button>
              <button onclick={()=>panelLayout={...panelLayout,collapsed:[]}}>Expand all panels</button>
              <button onclick={()=>panelLayout=defaultPanelLayout()}>Reset panel layout</button>
            {:else if name === 'View'}
              <button disabled={!canRotateStageView} onclick={()=>rotateStageView(stageRotation-15)}>Rotate stage view left</button>
              <button disabled={!canRotateStageView} onclick={()=>rotateStageView(stageRotation+15)}>Rotate stage view right</button>
              <button disabled={!canRotateStageView||stageRotation===0} onclick={()=>rotateStageView(0)}>Reset stage view rotation</button>
              <button aria-pressed={rulersVisible} onclick={()=>rulersVisible=!rulersVisible}>Show rulers</button>
              <label
                >Angle increment<select aria-label="Angle increment" bind:value={angleIncrement}>
                  <option value={0}>Tool defaults (drawing 45° / rotation 15°)</option>
                  {#each [5, 10, 15, 30, 45, 90] as degrees}
                    <option value={degrees}>{degrees}°</option>
                  {/each}
                </select></label
              >

              <label
                >Grid width<input
                  aria-label="Grid width"
                  type="number"
                  min="1"
                  max="1000"
                  value={gridSpacingX}
                  onchange={(e) => {
                    gridSpacingX = Math.max(
                      1,
                      Math.min(1000, Math.round(Number(e.currentTarget.value) || 20)),
                    );
                    e.currentTarget.value = String(gridSpacingX);
                  }}
                /></label
              >
              <label
                >Grid height<input
                  aria-label="Grid height"
                  type="number"
                  min="1"
                  max="1000"
                  value={gridSpacingY}
                  onchange={(e) => {
                    gridSpacingY = Math.max(
                      1,
                      Math.min(1000, Math.round(Number(e.currentTarget.value) || 20)),
                    );
                    e.currentTarget.value = String(gridSpacingY);
                  }}
                /></label
              >
              <label
                >Snap distance (px)<input
                  aria-label="Snap distance"
                  type="number"
                  min="1"
                  max="32"
                  value={snapDistance}
                  onchange={(e) => {
                    snapDistance = Math.max(
                      1,
                      Math.min(32, Math.round(Number(e.currentTarget.value) || 6)),
                    );
                    e.currentTarget.value = String(snapDistance);
                  }}
                /></label
              >
              <button
                onclick={() => {
                  gridSpacingX = 20;
                  gridSpacingY = 20;
                  snapDistance = 6;
                }}>Reset grid settings</button
              >

              <button aria-pressed={snapGrid} onclick={() => (snapGrid = !snapGrid)}
                >Snap to grid</button
              >
              <button aria-pressed={snapObjects} onclick={() => (snapObjects = !snapObjects)}
                >Snap to objects</button
              >
              <button aria-pressed={snapGuides} onclick={() => (snapGuides = !snapGuides)}
                >Snap to guides</button
              >
              <button aria-pressed={guidesVisible} onclick={() => (guidesVisible = !guidesVisible)}
                >Show guides</button
              >
              <button aria-pressed={guidesLocked} onclick={() => (guidesLocked = !guidesLocked)}
                >Lock guides</button
              >
              <button
                disabled={guidesLocked || !project.guides?.length}
                onclick={() => {
                  edit('Clear guides', () => (project.guides = []));
                  menu = '';
                }}>Clear guides</button
              >
              <hr />
              <button
                onclick={() => {
                  fit();
                  menu = '';
                }}>Fit stage</button
              ><button
                onclick={() => {
                  grid = !grid;
                  menu = '';
                }}>{grid ? 'Hide' : 'Show'} grid</button
              ><button
                onclick={() => {
                  onion = !onion;
                  menu = '';
                }}>{onion ? 'Disable' : 'Enable'} onion skin</button
              >
            {:else if name === 'Insert'}<button
                onclick={() => {
                  insertFrame();
                  menu = '';
                }}>Frame{#if shortcutLabel('frame')} <kbd>{shortcutLabel('frame')}</kbd>{/if}</button
              ><button
                onclick={() => {
                  keyframe();
                  menu = '';
                }}>Keyframe{#if shortcutLabel('keyframe')} <kbd>{shortcutLabel('keyframe')}</kbd>{/if}</button
              ><button
                onclick={() => {
                  keyframe(true);
                  menu = '';
                }}>Blank keyframe{#if shortcutLabel('blank')} <kbd>{shortcutLabel('blank')}</kbd>{/if}</button
              ><button
                onclick={() => {
                  addLayer();
                  menu = '';
                }}>Layer</button
              >
            {:else if name === 'Control'}<button
                disabled={pendingDrawingJobs}
                onclick={() => {
                  toggleTimelinePlayback();
                  menu = '';
                }}>{playing || timelineAudio ? 'Stop' : 'Play'}{#if shortcutLabel('play')} <kbd>{shortcutLabel('play')}</kbd>{/if}</button
              ><button disabled={pendingDrawingJobs} onclick={()=>testMovie(false,applicationMenuTrigger('Control')??undefined)}>Test movie{#if shortcutLabel('testMovie')} <kbd>{shortcutLabel('testMovie')}</kbd>{/if}</button>
              <button disabled={busy||!!timelineDrag||!!penDraft||!!pendingDrawingJobs} onclick={()=>testMovie(true,applicationMenuTrigger('Control')??undefined)}>Test remembered movie…</button>
              <button onclick={openScriptScratch}>Check frame TypeScript…</button>
              <button disabled={busy} onclick={()=>openFrameSource()}>Edit current frame source…</button>
              <button disabled={busy} onclick={openProgramCheck}>Check saved frame sources…</button>
              <button disabled={busy} onclick={openScriptPreview}>Preview saved scripts…</button>
              <button disabled={busy || playing} onclick={toggleSampledStage}>{sampledStageMode ? 'Return to authored stage' : 'Show sampled motion on stage'}</button>
              <button disabled={busy} onclick={()=>openRememberedPreview(true)}>Preview remembered timeline…</button>
              <button disabled={maskPreviewBlocked()} onclick={openLiveCreate}>Create live tween…</button>
              <button disabled={maskPreviewBlocked()} onclick={()=>openTimelineTween('motion')}>Advanced motion tween settings…</button>
              <button disabled={maskPreviewBlocked()} onclick={()=>openTimelineTween('shape')}>Advanced shape tween settings…</button>
              <button disabled={maskPreviewBlocked()||!project.layers.some(l=>l.liveMotionSpans?.length)} onclick={openLiveEdit}>Edit live tween…</button>
              <button disabled={maskPreviewBlocked()||!project.layers.some(l=>l.liveMotionSpans?.length)} onclick={()=>openLiveCurve()}>Edit live curve controls…</button>
              <button disabled={maskPreviewBlocked()||!project.layers.some(l=>l.liveMotionSpans?.some(s=>s.path?.waypoints!==undefined&&!s.rotation?.rigidGroups&&s.symbolContinuity===undefined))} onclick={()=>openLiveCurve('waypoint')}>Edit live waypoint positions…</button>
              <button disabled={maskPreviewBlocked()||!project.layers.some(l=>l.liveMotionSpans?.some(s=>s.path?.waypoints!==undefined&&s.rotation?.rigidGroups===true))} onclick={()=>openLiveCurve('groupWaypoint')}>Edit live group waypoint positions…</button>
              <button disabled={maskPreviewBlocked()||!project.layers.some(l=>l.liveMotionSpans?.some(s=>s.path?.curvedWaypoints===true&&s.path.waypoints!==undefined&&s.path.waypointTangents!==undefined&&s.path.waypointIncoming!==undefined&&s.symbolContinuity===undefined&&!s.rotation?.rigidGroups))} onclick={()=>openLiveCurve('waypointTangent')}>Edit live waypoint handles…</button>
              <button disabled={maskPreviewBlocked()||!project.layers.some(l=>l.visible&&!l.locked&&l.liveMotionSpans?.some(s=>frame>=s.start&&frame<=s.end&&s.rotation?.rigidGroups===true&&s.path?.curvedWaypoints===true&&(s.path.waypoints?.length??0)>0&&s.path.waypointTangents!==undefined&&s.path.waypointIncoming!==undefined))} onclick={()=>openLiveCurve('groupWaypointTangent')}>Edit live group waypoint handles…</button>
              <button disabled={maskPreviewBlocked()||!project.layers.some(l=>l.liveMotionSpans?.some(s=>s.path?.waypoints!==undefined&&s.symbolContinuity==='movie-trees'&&!s.rotation?.rigidGroups))} onclick={()=>openLiveCurve('treeWaypoint')}>Edit live nested movie waypoint positions…</button>
              <button disabled={maskPreviewBlocked()||!project.layers.some(l=>l.liveMotionSpans?.some(s=>s.rotation?.rigidGroups))} onclick={()=>openLiveCurve('group')}>Edit live group curve controls…</button>
              <button disabled={maskPreviewBlocked()||!project.layers.some(l=>l.visible&&!l.locked&&l.liveMotionSpans?.some(s=>frame>=s.start&&frame<=s.end&&s.groupPaths?.some(p=>p.path.waypoints===undefined)))} onclick={()=>openLiveCurve('independentGroup')}>Edit independent group curve controls…</button>
              <button disabled={maskPreviewBlocked()||!project.layers.some(l=>l.liveMotionSpans?.some(s=>s.symbolContinuity==='movie-trees'&&s.path&&s.path.waypoints===undefined))} onclick={()=>openLiveCurve('tree')}>Edit nested movie curve controls…</button>
              <button disabled={maskPreviewBlocked()||!project.layers.some(l=>l.liveMotionSpans?.length)} onclick={openLiveRemove}>Remove live tween…</button>
              <button disabled={maskPreviewBlocked()||!project.layers.some(layer=>layer.liveMotionSpans?.length)} onclick={openLivePreview}>Preview live timeline…</button>
              <button disabled={maskPreviewBlocked()||!project.layers.some(layer=>layer.liveMotionSpans?.length)} onclick={openLiveSplit}>Insert live tween key…</button>
              <button disabled={maskPreviewBlocked()||!project.layers.some(l=>l.liveMotionSpans?.some(s=>s.rotation?.rigidGroups))} onclick={openLiveGroupSplit}>Insert live group tween key…</button>
              <button disabled={maskPreviewBlocked()||!project.layers.some(l=>l.liveMotionSpans?.some(s=>s.symbolContinuity==='graphics'))} onclick={openLiveGraphicSplit}>Insert live graphic tween key…</button>
              <button disabled={maskPreviewBlocked()||!project.layers.some(l=>l.liveMotionSpans?.some(s=>s.symbolContinuity==='movies'))} onclick={openLiveMovieSplit}>Insert live movie tween key…</button>
              <button disabled={maskPreviewBlocked()||!project.layers.some(l=>l.liveMotionSpans?.some(s=>s.symbolContinuity==='movie-trees'))} onclick={openLiveMovieTreeSplit}>Insert live nested movie tween key…</button>
              <button disabled={busy||playing||!!pendingDrawingJobs||!!penDraft||!!timelineDrag||sampledStageMode||!!symbolEditing||multiFrame} onclick={openMaskPreview}>Preview layer mask…</button>
              <button disabled={busy} title="Evaluate visible root and reachable symbol recipes, then remove their recipe ownership in one undoable edit. Locked recipe tracks must be unlocked." onclick={bakeRemembered}>Bake remembered timeline to editable keys</button>
              <button disabled={busy} onclick={()=>openAudioPreview(false)}>Preview audio...</button>
              <button disabled={busy||!audioImportAvailable||!projectFolder||!license.savingAllowed} title="Audio import requires a saved project in the desktop editor or local development browser." onclick={()=>openAudioImport(undefined,applicationMenuTrigger('Control')??undefined)}>Import audio...</button>
              <button disabled={busy} onclick={openAudioClips}>Edit audio clips...</button>
              <button disabled={busy||!project.audioClips?.length} onclick={()=>openAudioPreview(true)}>Preview saved audio...</button>
            {:else}
              <button onclick={() => { menu = ''; helpDialog = 'about'; }}>About</button>
              <button onclick={() => { menu = ''; helpDialog = 'register'; }}>Register…</button>
              {#if desktop}
                <button onclick={() => openUpdate()}>Update…</button>
              {/if}
              <button onclick={() => {
                menu = '';
                void openDocumentation().catch((cause) => { error = String(cause); });
              }}>Documentation</button>
              <button onclick={() => { menu = ''; window.dispatchEvent(new Event(showSplashScreenEvent)); }}>Show Splash Screen</button>
              <button
                onclick={() => {
                  modal = 'help';
                  menu = '';
                }}>Build status & shortcuts</button
              >{/if}
          </div>{/if}
      </div>{/each}
    {#if desktop}<div class="menu-drag-region" data-tauri-drag-region aria-hidden="true"></div>{/if}
    {#if desktop && $desktopUpdate.release?.ticket}
      <button type="button" class="update-available" data-update-available
        inert={!!symbolEditing?.workspace} onclick={() => openUpdate(true)}>Update Available</button>
    {/if}
    {#if license.claims}
      <button class="publish" inert={desktop && !!symbolEditing?.workspace} disabled={!license.savingAllowed || foregroundBusy || preview || !!penDraft || !!scopedSymbol} aria-disabled={pendingDrawingJobs || undefined} onclick={()=>openExport('html')}><span aria-hidden="true">↗</span> Export</button>
    {:else}
      <button class="publish register-prompt" inert={desktop && !!symbolEditing?.workspace} onclick={() => { menu = ''; registerFromToolbar = true; helpDialog = 'register'; }}>Register Splash Animator</button>
    {/if}
    {#if desktop}<DesktopWindowControls reportError={(cause) => { error = String(cause); }} />{/if}
  </nav>
  <div class="document-tabs">
    <nav class="document-tab-list" aria-label="Open documents">
      {#each openDocuments as tab (tab.id)}
        {@const current = tab.id === activeDocument}
        {@const documentName = tab.state?.project.name ?? scopedSymbol?.source.project.name ?? project.name}
        <div class="document-tab-item" class:current>
          <button type="button" class="document-tab" class:current aria-current={current ? 'page' : undefined}
            aria-label={'Switch to ' + documentName} disabled={!current && documentActionBlocked()}
            onclick={() => activateDocument(tab.id)}>
            <span class="file-dot" aria-hidden="true"></span>{documentName}{(tab.state?.dirty ?? dirty) ? ' •' : ''}
            <span class="file-type" aria-hidden="true">.spl</span>
          </button>
          <button type="button" class="document-close" aria-label={'Close ' + documentName}
            title={'Close ' + documentName} disabled={documentActionBlocked()}
            onclick={event => requestDocumentClose(tab.id, event.currentTarget)}>×</button>
        </div>
      {/each}
    </nav>
    <span class="saved-state"
      >{foregroundBusy
        ? 'Writing…'
        : dirty
          ? 'Unsaved changes'
          : projectFolder
            ? 'Saved to folder'
            : 'New document'}</span
    >
  </div>
  {#if error && modal!=='export' && modal!=='save' && modal!=='open'}<div class="notice error" role="alert">
      {error}<button onclick={() => (error = '')}>Dismiss</button>
    </div>{/if}
  {#if recovery && !scopedSymbol}<div class="notice" data-project-recovery>
      <span id="project-recovery-message">Recovery available: {recovery.project.name}</span>
      <button bind:this={recoveryAction} aria-describedby="project-recovery-message" disabled={documentActionBlocked()} onclick={restore}>Recover changes</button
      ><button
        disabled={documentActionBlocked()}
        onclick={() => {
          if (documentActionBlocked()) return;
          [recovery = null, ...recoveryQueue] = recoveryQueue;
          refreshDocumentRecovery();
          void restoreFileCommandFocus(canvas);
        }}>Dismiss</button
      >
    </div>{/if}
  <main class="editor" class:inspector-left={inspectorLeft} aria-label={scopedSymbol ? 'Symbol editing workspace' : undefined} class:symbol-workspace-mode={!!symbolEditing?.workspace} bind:this={workspaceEditor} style:--tools-width={`${workspace.tools}px`} style:--inspector-width={`${workspace.inspector}px`} style:--timeline-height={`${workspace.timeline}px`} style:--timeline-content-height={`${workspace.timelineContent}px`} inert={foregroundBusy}>
    {#if symbolEditing?.workspace}
      <div class="symbol-workspace-host">
        {#await import('./SymbolWorkspace.svelte')}
          <p role="status">Loading symbol workspace…</p><button onclick={()=>symbolEditing=null}>Cancel symbol loading</button>
        {:then {default:SymbolWorkspace}}
          {#key symbolEditing.id}<SymbolWorkspace {shortcutOverrides} {macShortcuts} {sceneName} definition={symbolEditing.definition} assets={project.assets} symbols={project.symbols??[]} fps={project.fps}
            readSourceProject={()=>({project,revision:historyTick})} context={symbolEditing.context} stageCamera={symbolEditing.stageCamera}
            initialDrawing={{canvasTool:'select',newFill:fill,newStroke:stroke,newLineWidth:strokeWidth??2,brushWidth:brushSize??24,brushSimplify:brushSmoothing??50,brushLockToCanvas:!brushScreenSize,brushOptimize,brushObjects,contactOpacityEnabled,strokeOpacityEnabled,contactOpacityMinimum,contactOpacityResponse,removeCoveredStrokes,pencilMode:pencilMode==='ink'?'raw':pencilMode,pencilSimplify:pencilSmoothing??50,pencilOptimize,pencilObjects}}
            timelineHeight={workspace.timeline} timelineMax={workspace.timelineMax} previewTimeline={value=>previewWorkspace('timeline',value)} commitTimeline={value=>commitWorkspace('timeline',value)}
            stageValidate={symbolEditing.context?admitStageSymbolSession:undefined}
            simplify={staticSymbolSimplifyAvailable()?staticSymbolSimplifyContext:stageStaticSymbolSimplifyAvailable()?stageStaticSymbolSimplifyContext:undefined}
            validate={definition=>updateSymbolTimeline(clone(project),symbolEditing!.id,definition)} apply={applySymbolTimelineDraft}
            navigate={navigateNestedSymbol} returnTo={symbolEditing.parent?returnSymbolContext:undefined} returnName={symbolEditing.parent?.definition.name}
            cancel={()=>symbolEditing=null}/>{/key}
        {:catch cause}<p role="alert">Could not open symbol workspace: {String(cause)}</p><button onclick={()=>symbolEditing=null}>Close symbol workspace</button>{/await}
      </div>
    {/if}
    <aside id="drawing-tools-panel" class="tools" aria-label="Drawing tools">
      <span class="grip">•••</span>{#each tools as t}<button
          data-drawing-tool={t.id}
          class:chosen={tool === t.id}
          title={shortcutLabel(toolShortcut(t.id)) ? t.label+' ('+shortcutLabel(toolShortcut(t.id))+')' : t.label}
          aria-label={t.label}
          aria-pressed={tool === t.id}
          aria-disabled={(pendingDrawingJobs && !queuedDrawingTool(t.id)) || undefined}
          onclick={() => chooseTool(t.id)}><ToolIcon tool={t.id}/></button
        >{/each}
      <div class="tool-divider"></div>
      <label class="swatch" title="Fill"
        ><input
          type="color"
          title="Eyedropper: Alt-click samples rendered artwork into this fill"
          aria-label="Drawing fill"
          bind:value={fill}
        /></label
      ><label class="swatch stroke-swatch" class:no-shape-stroke={noShapeStroke} title={noShapeStroke ? 'Choose a stroke color to restore shape outlines' : 'Stroke'}
        ><input type="color" aria-label="Drawing stroke" bind:value={() => stroke, setDrawingStrokeColor} /></label
      ><button type="button" class="no-stroke-tool" class:chosen={noShapeStroke} aria-pressed={noShapeStroke}
        aria-label="No stroke for shapes" title="No stroke for new shapes" onclick={() => noShapeStroke = !noShapeStroke}>
        <svg aria-hidden="true" focusable="false" width="22" height="22" viewBox="0 0 24 24" fill="none">
          <rect x="4" y="4" width="16" height="16" rx="1" stroke="currentColor" stroke-width="1.5" />
          <path d="M5 19 19 5" stroke="var(--stroke-slash, #f38383)" stroke-width="2" />
        </svg>
      </button
      ><button class="smooth-artwork" aria-label="Simplify selected artwork" title="Simplify selected artwork: remove vertices and fit curves" disabled={!smoothArtworkEnabled} aria-disabled={pendingDrawingJobs || undefined} onclick={smoothSelectedArtwork}>
        <svg aria-hidden="true" width="25" height="25" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M3 17c3-13 7 10 11-3s5-7 7-7"/><path d="m16 3 1-2m3 3 2-1"/></svg>
      </button><span class="tool-mode">{(tool==='path' ? !pencilObjects : activeLayer.drawingMode==='merge') ? 'MERGE' : 'OBJ'}</span>
    </aside>
    <WorkspaceDivider label="Resize drawing tools" controls="drawing-tools-panel" value={workspace.tools} min={64} max={workspace.toolsMax} defaultValue={DEFAULT_WORKSPACE_SIZES.tools} context={workspaceContext} canStart={() => canResizeWorkspace('tools')} preview={value => previewWorkspace('tools', value)} commit={value => commitWorkspace('tools', value)} />
    {#snippet scriptTimelineDivider()}<WorkspaceDivider label="Resize timeline" controls="timeline-panel" orientation="horizontal" reverse value={workspace.timeline} min={130} max={workspace.timelineMax} defaultValue={DEFAULT_WORKSPACE_SIZES.timeline} context={workspaceContext} canStart={() => canResizeWorkspace('timeline')} preview={value => previewWorkspace('timeline', value)} commit={value => commitWorkspace('timeline', value)} />{/snippet}
    {#snippet scriptTabs(dock:ScriptDock)}
      {#if panelOpen&&!panelFloating&&scriptDock===dock}
        <div class="script-tabs" data-script-panel role="tablist" aria-label={dock+' workspace'}>
          <button role="tab" id={dock+'-workspace-tab'} aria-controls={dock+'-workspace-panel'} aria-selected={!panelSelected}
            tabindex={panelSelected?-1:0} onclick={()=>{void scriptPanel?.flush();panelSelected=false;}} onkeydown={moveScriptDockTab}>{dock==='canvas'?'Canvas':'Timeline'}</button>
          <button role="tab" id={dock+'-script-tab'} aria-controls={dock+'-script-panel'} aria-selected={panelSelected}
            tabindex={panelSelected?0:-1} onclick={()=>panelSelected=true} onkeydown={moveScriptDockTab}>Script Editor</button>
        </div>
      {/if}
    {/snippet}
    {#snippet scriptEditor(location:ScriptDock|'floating')}
          {#key scriptSessionView}{#key projectFolder}<ScriptPanel bind:this={scriptPanel} workspace={scriptSessionView.workspace} operate={fileOperations()} bind:source={frameSourceDraft} savedSource={frameSourceOriginal??''} frameNumber={panelScratch?undefined:frameSourceTarget+1}
            frameFiles={frameScriptFiles} timelineName={scopedSymbol?.session.definition.name}
            selection={frameSourceSelection} {location} move={placeScriptPanel} close={closeScriptPanel}
            popOut={desktop?undefined:()=>openDetachedScriptPanel('popup')}
            popOutAlwaysOnTop={!desktop&&supportsScriptPictureInPicture()?()=>openDetachedScriptPanel('picture-in-picture'):undefined} error={panelError}
            apply={panelScratch?undefined:source=>commitFrameSource(source)} remove={panelScratch?undefined:()=>commitFrameSource(null)}/>{/key}{/key}
    {/snippet}
    {#if panelOpen&&panelFloating&&!desktop&&!panelDetached}
      <ScriptFloatingSurface>{@render scriptEditor('floating')}</ScriptFloatingSurface>
    {/if}
    {#snippet scriptSurface(dock:ScriptDock)}
      {#if panelOpen&&!panelFloating&&scriptDock===dock}
        <div class="script-surface" role="tabpanel" id={dock+'-script-panel'} aria-labelledby={dock+'-script-tab'} hidden={!panelSelected}>
          {#if dock==='timeline'}{@render scriptTimelineDivider()}{/if}
          {@render scriptEditor(dock)}
        </div>
      {/if}
    {/snippet}
    <section class="work-area" bind:this={workspaceArea}>
      {@render scriptTabs('canvas')}
      <div class="stage-toolbar" inert={pendingDrawingJobs} onfocusin={revealToolbarFocus}>
        <span class="scene-icon">▣</span>
        {#if scopedSymbol}
          <nav aria-label="Symbol edit breadcrumbs">
            <button class="scene-breadcrumb" title="Save symbol changes and return to the scene" onclick={()=>leaveSymbolScene(true)}>{sceneName}</button>
            {#if scopedSymbol.session.parent}
              <span class="crumb">/</span><button onclick={()=>switchScopedSymbol(returnSymbolContext,'return-parent')}>{scopedSymbol.session.parent.definition.name}</button>
            {/if}
            <span class="crumb">/</span><strong>{scopedSymbol.session.definition.name}</strong>
          </nav>
          <button onclick={()=>leaveSymbolScene(true)}>Save and return to scene</button>
          <button onclick={()=>leaveSymbolScene(false)}>Cancel symbol editing</button>
          {#if scopedSymbol.suspendedParent && dirty}
            <button onclick={applyChildSymbolDraft}>Apply child edits and return to parent</button>
          {/if}
          <button data-advanced-symbol-timeline
            onclick={event => leaveSymbolScene(false, true, event.currentTarget)}>Advanced symbol timeline tools…</button>
          {#if scopedButtonStates}
            {@const mapping = scopedButtonStates}
            <div class="button-state-controls" role="group" aria-label="Button states">
              {#each buttonStateRoles as role}
                {@const at = mapping[role]}
                <button aria-pressed={frame === at} disabled={at >= project.duration}
                  title={`Frame ${at + 1}`} onclick={() => navigateFrame(at)}>{buttonStateLabels[role]}</button>
              {/each}
            </div>
          {/if}
        {:else}
          <button class="scene-breadcrumb" data-scene-manager title={`Manage scenes · ${sceneName}`} aria-haspopup="dialog" disabled={documentActionBlocked()}
            onclick={event => openSceneManager(event.currentTarget)}>{sceneName}</button><span class="crumb">/</span>
        {/if}
        {#if groupScope.length}<span aria-label="Group editing depth"
            >Group level {groupScope.length}</span
          ><button onclick={exitGroup}>Exit group</button>{/if}
        <select
          class="drawing-mode"
          aria-label="Drawing mode"
          value={tool==='path' ? (pencilObjects?'object':'merge') : activeLayer.drawingMode ?? 'object'}
          onchange={(e) => setDrawingMode(e.currentTarget.value)}
          ><option value="object">Object drawing</option><option value="merge"
            >Merge · experimental</option
          ></select
        >
        <div class="top-spacer"></div>
        <button class:active={grid} onclick={() => (grid = !grid)} title="Toggle grid">▦</button
        ><button onclick={fit}>Fit</button><select
          aria-label="Zoom"
          title="Zoom tool: click to zoom, Alt-click out. Mouse wheel zooms around the pointer."
          value={String(zoom)}
          onchange={(e) => setViewZoom(Number(e.currentTarget.value))}
          >{#each stageZoomChoices as z (z)}<option value={String(z)}>{canvasZoomPercent(z)}%</option
            >{/each}</select
        >
      </div>
      <div class="drawing-options" role="group" aria-label="Active drawing tool options">
        {#if tool === 'select'}
          <label>Selection layers<select aria-label="Selection layers" title="Select current exposures on the active layer or visible unlocked layers. Masks and tween artwork retain their existing editors." value={crossLayerMode?'visible':'active'} disabled={busy||playing||!!preview||sampledStageMode||!!liveCurveConfig} onchange={e=>{changeCrossLayerMode(e.currentTarget.value==='visible');e.currentTarget.value=crossLayerMode?'visible':'active';}}><option value="active">Active layer</option><option value="visible">Visible unlocked layers</option></select></label>
          {#if crossLayerMode}
            <label>Gesture<select aria-label="Cross-layer selection gesture" value={multiPickForm} onchange={e=>chooseCrossLayerGesture(e.currentTarget.value as typeof multiPickForm)}><option value="point">Point / move</option><option value="box">Marquee</option><option value="lasso">Lasso</option></select></label>
            <button onclick={()=>setCrossLayerSelection(crossLayerIds())}>Select all visible artwork</button><button onclick={()=>setCrossLayerSelection([])}>Clear cross-layer selection</button>
            <span role="status">{multiSelection?.length??crossLayerIds().length} cross-layer members selected</span>
          {/if}
        {:else if tool === 'subselect'}
          <strong>Subselection</strong>
          <button type="button" disabled={!canApplyNodePaint()} onclick={applyNodePaintDrop}
            title="Resolve paint overlaps and stroke intersections while keeping the artwork selected">Apply</button>
        {:else if tool === 'brush'}
          <strong>Brush</strong>
          <label
            >Simplify <input
              aria-label="Brush simplify slider" title="Simplify the new stroke on release, before merging. Higher values simplify more; earlier artwork keeps its existing shape."
              type="range"
              min="0"
              max="200"
              bind:value={brushSmoothing}
            /></label
          >
          <label
            ><input
              aria-label="Brush simplify amount" title="Simplify the new stroke on release, before merging. Higher values simplify more; earlier artwork keeps its existing shape."
              type="number"
              min="0"
              max="200"
              bind:value={brushSmoothing}
            /> %</label
          >
          <label title="Reduce unnecessary anchors and fit curves after Simplify. Optimize applies only to the new stroke."><input aria-label="Brush optimize" type="checkbox" bind:checked={brushOptimize}/>Optimize</label>
          <label title="Keep the same brush width in canvas pixels at every zoom. Zooming in makes the brush appear larger."><input aria-label="Brush lock size to canvas" type="checkbox" checked={!brushScreenSize} onchange={e=>brushScreenSize=!e.currentTarget.checked}/>Lock size to canvas</label>
        {:else if tool === 'ink'}
          <strong>Ink</strong>
          <label>Paint <select aria-label="Ink paint scope" title="Choose a whole object, contour, edge or touching network. Edge edits use existing anchors; grouped artwork stays protected." bind:value={inkScope}>
            <option value="object">Whole object</option>
            <option value="contour">One compound contour</option>
            <option value="edge">One edge</option>
            <option value="network">Connected contours</option>
          </select></label>
        {:else if tool === 'pen'}
          <strong>Pen</strong>
          <label title="Rebuild curve handles while keeping anchor positions. Turn off to preserve manual handles."
            ><input type="checkbox" bind:checked={penSmoothing} />Smooth anchors on finish</label
          >
        {:else if tool === 'path'}
          <strong>Pencil</strong>
          <label
            >Mode <select aria-label="Pencil mode" title="Choose raw ink, simplified curves or a straight line. Finishing applies to each new stroke on release." bind:value={pencilMode}
              ><option value="ink">Off (Ink)</option><option value="smooth">Simplify</option><option
                value="straight">Straight line</option
              ></select
            ></label
          >
          <label>Simplify <input aria-label="Pencil simplify slider" title="Simplify the new stroke on release, before merging. Higher values simplify more; earlier artwork keeps its existing shape." type="range" min="0" max="200" step="1" disabled={pencilMode!=='smooth'} bind:value={pencilSmoothing}/></label>
          <label><input aria-label="Pencil simplify amount" title="Simplify the new stroke on release, before merging. Higher values simplify more; earlier artwork keeps its existing shape." type="number" min="0" max="200" step="1" disabled={pencilMode!=='smooth'} bind:value={pencilSmoothing}/> %</label>
          <label title="Reduce unnecessary anchors and fit curves after Simplify. Optimize applies only to the new stroke."><input aria-label="Pencil optimize" type="checkbox" bind:checked={pencilOptimize}/>Optimize</label>
          <label title="Keep each new Pencil stroke as a separate object instead of merging it with earlier artwork."><input aria-label="Separate Pencil objects" type="checkbox" bind:checked={pencilObjects} />Object drawing</label>
        {/if}
        {#if ['brush', 'pen', 'rectangle', 'rounded', 'ellipse', 'star'].includes(tool)}
          <label title="In Merge Drawing, new solid fills and Normal Brush paint remove the portions of earlier lines they cover.">
            <input type="checkbox" bind:checked={removeCoveredStrokes} />Remove covered lines
          </label>
        {/if}
      </div>
      {#if sampledStageMode}
        <div class="panel-heading sampled-stage-controls" role="region" aria-label="Sampled motion stage">
          <span>Sampled motion · Frame {frame+1}</span>
          <label><input type="checkbox" aria-label="Remember sampled stage children" checked={sampledStageChildren} disabled={busy||playing}
            onchange={e=>{cancelSampledStageDrag();sampledSelectionRevision++;sampledStageProposal=null;sampledStagePick=null;sampledStageChildren=e.currentTarget.checked;}}/>Remember nested artwork</label>
          {#if sampledStage?.pending}<span role="status">Preparing remembered child artwork.</span>{/if}
          <label><input type="checkbox" aria-label="Select multiple sampled units" checked={sampledSelectionMode} disabled={busy||playing}
            onchange={e=>changeSampledSelectionMode(e.currentTarget.checked)}/>Select multiple units</label>
          <label><input type="checkbox" aria-label="Select complete sampled stage groups" checked={sampledStageGroups} disabled={busy||playing}
            onchange={e=>changeSampledStageGroups(e.currentTarget.checked)}/>Select complete outer groups</label>
          {#if sampledSelectionMode}
            {#if sampledSelectionContext}<SampledSelectionEditor trajectoryHandles={layout=>sampledSelectionTrajectoryHint=layout} trajectoryContext={createSelectionTrajectoryContext} publishTrajectories={publishSelectionTrajectories} surface={()=>({canvas,view:{origin:{...origin},zoom,width:viewWidth,height:viewHeight}})} context={sampledSelectionContext} preview={value=>sampledSelectionPreview=value} selection={owner=>sampledSelectionOwner=owner} rotationHandle={layout=>sampledSelectionRotationHint=layout} scaleHandles={layout=>sampledSelectionScaleHint=layout} skewHandles={layout=>sampledSelectionSkewHint=layout} publish={publishSampledSelection}/>
            {:else}<small>Wait for the original sampled artwork to be ready.</small>{/if}
          {:else}
          <select aria-label="Sampled stage artwork" disabled={!!sampledStageDrag||!!sampledStage?.pending||!!sampledStage?.error} value={sampledStageChoice ? JSON.stringify([sampledStageChoice.layerId,sampledStageChoice.shapeId]) : ''}
            onchange={e=>{if(e.currentTarget.value){const [layerId,shapeId]=JSON.parse(e.currentTarget.value);pickSampledStage(layerId,shapeId);}else sampledStagePick=null;}}>
            <option value="">Select a sampled pose to promote</option>
            {#each sampledStage?.choices ?? [] as choice}
              <option value={JSON.stringify([choice.layerId,choice.shapeId])}>{project.layers.find(l=>l.id===choice.layerId)?.name} · {choice.shapeId}</option>
            {/each}
          </select>
          <button disabled={busy || playing || !!sampledStageDrag || !sampledStageChoice} onclick={()=>promoteSampledStage()}>Promote sampled stage pose</button>
          {#if sampledStageMovable}
            {#if sampledStageGroups}
            <label><input type="checkbox" aria-label="Drag sampled group offsets" checked={sampledStageGroupDrag} disabled={busy||playing}
              onchange={e=>{cancelSampledStageDrag();sampledStageGroupPolicyRevision++;sampledStageGroupDrag=e.currentTarget.checked;if(sampledStageGroupDrag){sampledGroupPivot=null;sampledGroupTrajectory=null;sampledGroupWaypoints=null;sampledStageProposal=null;sampledStageRotate=false;sampledStageScaling=false;sampledStageShearing=false;}}}/>Drag group offsets</label>
            <label><input type="checkbox" aria-label="Rotate sampled group with handle" checked={sampledStageRotate} disabled={busy||playing}
              onchange={e=>changeSampledStageRotation(e.currentTarget.checked)}/>Rotate group with handle</label>
            <label><input type="checkbox" aria-label="Scale sampled group with handles" checked={sampledStageScaling} disabled={busy||playing}
              onchange={e=>changeSampledStageScaling(e.currentTarget.checked)}/>Scale group with handles</label>
            <label><input type="checkbox" aria-label="Skew sampled group with handles" checked={sampledStageShearing} disabled={busy||playing}
              onchange={e=>changeSampledStageShearing(e.currentTarget.checked)}/>Skew group with diamond handles</label>
            <label><input type="checkbox" aria-label="Author sampled group on drag release" checked={sampledStageGroupAuthoring} disabled={busy||playing||!sampledStageGroupDrag}
              onchange={e=>{cancelSampledStageDrag();sampledStageGroupPolicyRevision++;sampledStageGroupAuthoring=e.currentTarget.checked;}}/>Author group on release</label>
            {#if sampledGroupPivot}<small>{sampledGroupPivotCanvas?(sampledGroupPivotAuthoring?'Drag the original group pivot. Valid release authors one undo step.':'Drag the original group pivot. Release keeps an unapplied draft; commit explicitly.'):'Enter group pivot coordinates or enable pivot dragging.'}</small>
            {:else if sampledStageShearing}<small>Drag a diamond edge to skew the complete original group about its common pivot. Shift constrains the angle. Release authors one undo step; Escape restores the prior draft.</small>
            {:else if sampledStageRotate}<small>Drag the circular handle to rotate the complete original group. Shift snaps the angle. Release authors one undo step; Escape restores the prior draft.</small>
            {:else if sampledStageScaling}<small>Drag a square corner or midpoint to scale the complete original group about its common pivot. Shift keeps corner proportions; midpoints keep the other document axis unchanged. Release authors one undo step; Escape restores the prior draft.</small>
            {:else if sampledStageGroupAuthoring}<small>Drag an original group member to preview movement. Release promotes and moves the complete group in one undo step. Shift constrains the axis; Escape cancels.</small>
            {:else}<small>Drag any selected original member to set offsets. Shift constrains the document axis. Release keeps a preview; commit explicitly to edit. Escape restores prior offsets.</small>{/if}
            {/if}
            {#if !sampledStageGroups}
            <label><input type="checkbox" aria-label="Author sampled pose by dragging"
              checked={sampledStageAuthoring} disabled={busy || playing || !!sampledStageDrag}
              onchange={event=>changeSampledStageAuthoring(event.currentTarget.checked)} />Author sampled pose by dragging</label>
            <label><input type="checkbox" aria-label="Rotate sampled pose with handle" checked={sampledStageRotate}
              disabled={busy||playing||!!sampledStageDrag} onchange={e=>changeSampledStageRotation(e.currentTarget.checked)} />Rotate sampled pose with handle</label>
            <label><input type="checkbox" aria-label="Scale sampled pose with handles" checked={sampledStageScaling}
              disabled={busy||playing||!!sampledStageDrag} onchange={e=>changeSampledStageScaling(e.currentTarget.checked)} />Scale sampled pose with handles</label>
            <label><input type="checkbox" aria-label="Skew sampled pose with handles" checked={sampledStageShearing}
              disabled={busy||playing||!!sampledStageDrag} onchange={e=>changeSampledStageShearing(e.currentTarget.checked)} />Skew sampled pose with handles</label>
            {/if}
            {#if !sampledStageGroups && sampledStageShearing}
              <small>Drag a diamond edge to preview skew about the saved/default pivot. Shift constrains the angle. Release promotes and skews in one undo step; Escape cancels. Existing affine interpolation must admit the change.</small>
            {:else if !sampledStageGroups && sampledStageScaling}
              <small>Drag a square corner or midpoint to scale about the saved/default pivot. Shift keeps corner proportions; midpoints keep the other axis unchanged. Release promotes and scales in one undo step; Escape cancels. Both recipes must already allow affine interpolation.</small>
            {:else if !sampledStageGroups && sampledStageRotate}
              <small>Drag the circular handle to preview rotation about the saved/default pivot. Shift snaps the angle. Release promotes and rotates in one undo step; Escape cancels.</small>
            {:else if !sampledStageGroups && sampledStageAuthoring}
              <small>Drag selected sampled artwork to preview its regenerated pose. Release promotes and moves
                it in one undo step; a click makes no edit. Escape cancels. Picking stays tied to the original pose.</small>
            {:else}
            <label>X offset<input aria-label="Sampled stage X offset" type="number" step="any" bind:value={sampledStageOffsetX} oninput={e=>changeSampledGroupOffset('x',e.currentTarget.value)} disabled={busy || playing || !!sampledStageDrag} /></label>
            <label>Y offset<input aria-label="Sampled stage Y offset" type="number" step="any" bind:value={sampledStageOffsetY} oninput={e=>changeSampledGroupOffset('y',e.currentTarget.value)} disabled={busy || playing || !!sampledStageDrag} /></label>
            <button disabled={busy || playing || !!sampledStageDrag || !!sampledStageProposed || !Number.isFinite(sampledStageOffsetX) || !Number.isFinite(sampledStageOffsetY) || (!sampledStageOffsetX && !sampledStageOffsetY)} onclick={()=>previewSampledStageMove()}>Preview sampled stage move</button>
            <button disabled={busy || playing || !!sampledStageDrag || !Number.isFinite(sampledStageOffsetX) || !Number.isFinite(sampledStageOffsetY) || (!sampledStageOffsetX && !sampledStageOffsetY)} onclick={()=>promoteSampledStage(true)}>Promote and move sampled stage pose</button>
            <label>Rotation degrees<input aria-label="Sampled stage rotation" type="number" step="any" bind:value={sampledStageAngle} oninput={e=>changeSampledGroupAngle(e.currentTarget.value)} disabled={busy || playing || !!sampledStageDrag} /></label>
            <button disabled={busy || playing || !!sampledStageDrag || !!sampledStageProposed || !Number.isFinite(sampledStageAngle) || !sampledStageAngle || sampledStageAngle%360===0} onclick={()=>previewSampledStageMove('rotation')}>Preview sampled stage rotation</button>
            <button disabled={busy || playing || !!sampledStageDrag || !Number.isFinite(sampledStageAngle) || !sampledStageAngle || sampledStageAngle%360===0} onclick={()=>promoteSampledStage(false,true)}>Promote and rotate sampled stage pose</button>
            <label>Scale X %<input aria-label="Sampled stage X scale" type="number" step="any" bind:value={sampledStageScaleX} oninput={e=>changeSampledGroupScale('x',e.currentTarget.value)} disabled={busy||playing||!!sampledStageDrag}/></label>
            <label>Scale Y %<input aria-label="Sampled stage Y scale" type="number" step="any" bind:value={sampledStageScaleY} oninput={e=>changeSampledGroupScale('y',e.currentTarget.value)} disabled={busy||playing||!!sampledStageDrag}/></label>
            <button disabled={busy||playing||!!sampledStageDrag||!!sampledStageProposed||!sampledStageScaleValid} onclick={()=>previewSampledStageMove('scale')}>Preview sampled stage scale</button>
            <button disabled={busy||playing||!!sampledStageDrag||!sampledStageScaleValid} onclick={()=>promoteSampledStage(false,false,true)}>Promote and scale sampled stage pose</button>
            <label>Skew axis<select aria-label="Sampled stage skew axis" bind:value={sampledStageSkewAxis} onchange={e=>changeSampledGroupSkew(e.currentTarget.value as 'x'|'y','')} disabled={busy||playing||!!sampledStageDrag}><option value="x">Document X</option><option value="y">Document Y</option></select></label>
            <label>Skew degrees<input aria-label="Sampled stage skew angle" type="number" step="any" bind:value={sampledStageSkewAngle} oninput={e=>changeSampledGroupSkew(undefined,e.currentTarget.value)} disabled={busy||playing||!!sampledStageDrag}/></label>
            <button disabled={busy||playing||!!sampledStageDrag||!!sampledStageProposed||!sampledStageSkewValid} onclick={()=>previewSampledStageMove('skew')}>Preview sampled stage skew</button>
            <button disabled={busy||playing||!!sampledStageDrag||!sampledStageSkewValid} onclick={()=>promoteSampledStage(false,false,false,true)}>Promote and skew sampled stage pose</button>
            {#if !sampledStageGroups}
            <small>Skew uses the saved/default pivot and requires compatible saved affine interpolation. Each transform applies separately.</small>
            <small>Scaling uses the saved/default pivot and requires compatible saved affine interpolation. Move, rotation and scale apply separately.</small>
            <small>Rotation uses the saved pivot or authoring-box center and applies separately from the move offsets.</small>
            {:else}<small>Group transforms use the common saved pivot or full authoring-box center. Each applies separately from unapplied drafts; scaling and skew require compatible saved affine/group options.</small>{/if}
            <small>Drag the selected artwork or enter offsets in document units. Release sets offsets; Escape cancels the drag. Commit updates both spans in one undo step.</small>
            {/if}
          {/if}
          {#if sampledStageGroups&&sampledStageMovable}
            <button disabled={busy||playing||!!sampledStageDrag} onclick={chooseSampledGroupWaypoints}>Select original sampled group waypoints</button>
            {#if sampledGroupWaypoints}
            <label><input type="checkbox" aria-label="Drag sampled group waypoints" checked={sampledGroupWaypointCanvas} disabled={!sampledGroupWaypoint||busy||playing} onchange={e=>changeSampledGroupWaypointCanvas(e.currentTarget.checked)}/>Drag original saved waypoint drafts</label>
            <label><input type="checkbox" aria-label="Author sampled group waypoint on release" checked={sampledGroupWaypointAuthoring} disabled={!sampledGroupWaypointCanvas||busy||playing} onchange={e=>changeSampledGroupWaypointAuthoring(e.currentTarget.checked)}/>Author waypoint on valid release</label>
            <small>Drag the original selected waypoint marker. Shift constrains the document axis. {sampledGroupWaypointAuthoring?'Valid release authors one document edit.':'Release keeps an unapplied draft; commit explicitly.'} Other release preferences do not author waypoint edits.</small>
            <label>Saved waypoint number<input aria-label="Sampled group waypoint number" type="number" min="1" max={sampledGroupWaypoints.path.waypoints.length} step="1" value={sampledGroupWaypointNumber??''} disabled={busy||playing||!!sampledStageDrag} oninput={e=>chooseSampledGroupWaypoint(e.currentTarget.value)}/></label>
            <label>Waypoint X offset<input aria-label="Sampled group waypoint X offset" type="number" step="any" value={sampledGroupWaypointX??''} disabled={!sampledGroupWaypoint||busy||playing||!!sampledStageDrag} oninput={e=>editSampledGroupWaypoint('x',e.currentTarget.value)}/></label>
            <label>Waypoint Y offset<input aria-label="Sampled group waypoint Y offset" type="number" step="any" value={sampledGroupWaypointY??''} disabled={!sampledGroupWaypoint||busy||playing||!!sampledStageDrag} oninput={e=>editSampledGroupWaypoint('y',e.currentTarget.value)}/></label>
            <button disabled={!sampledGroupWaypointValid||busy||playing||!!sampledStageDrag||!!sampledStageProposed} onclick={previewSampledGroupWaypoint}>Preview sampled group waypoint position</button>
            <button disabled={!sampledGroupWaypointValid||busy||playing||!!sampledStageDrag} onclick={commitSampledGroupWaypoint}>Commit sampled group waypoint position</button>
            <small>Offsets use the original recipe leader's start position in document units. Saved curve handles and timing stay fixed; no waypoint is added or removed. Other drafts apply separately; canvas gestures are paused.</small>
            {/if}
            <button disabled={busy||playing||!!sampledStageDrag} onclick={chooseSampledGroupTrajectory}>Select original sampled group trajectory</button>
            {#if sampledGroupTrajectory}
            <label><input type="checkbox" aria-label="Drag sampled group cubic controls" checked={sampledGroupCurveCanvas} onchange={e=>changeSampledGroupCurveCanvas(e.currentTarget.checked)}/>Drag original shared cubic control drafts</label>
            <label>Original shared cubic control<select aria-label="Sampled group cubic control role" value={sampledGroupCurvePart} onchange={e=>changeSampledGroupCurvePart(e.currentTarget.value)}><option value="start">Start control</option><option value="end">End control</option></select></label>
            <label><input type="checkbox" aria-label="Author sampled group cubic control on release" checked={sampledGroupCurveAuthoring} disabled={!sampledGroupCurveCanvas} onchange={e=>changeSampledGroupCurveAuthoring(e.currentTarget.checked)}/>Author shared cubic control on valid release</label>
            <small>The original recipe leader owns the handle. Shift constrains the document axis. Release keeps an unapplied draft unless group cubic release authoring is enabled.</small>
            {#each ['startX','startY','endX','endY'] as field}
            <label>Group cubic {field}<input aria-label={'Sampled group trajectory '+field} type="number" step="any" value={sampledGroupTrajectoryControls[field as keyof GroupTrajectoryControls]??''} disabled={busy||playing||!!sampledStageDrag} oninput={e=>editSampledGroupTrajectoryControl(field as keyof GroupTrajectoryControls,e.currentTarget.value)}/></label>
            {/each}
            <button disabled={!sampledGroupTrajectoryValid||busy||playing||!!sampledStageDrag||!!sampledStageProposed} onclick={previewSampledGroupTrajectory}>Preview sampled group trajectory</button>
            <button disabled={!sampledGroupTrajectoryValid||busy||playing||!!sampledStageDrag} onclick={commitSampledGroupTrajectory}>Commit sampled group trajectory</button>
            <small>Cubic control offsets use the original recipe leader in document units. Edits replace the shared translation route while preserving endpoints and member geometry. Other drafts apply separately; canvas gestures are paused.</small>
            {/if}
            <button disabled={busy||playing||!!sampledStageDrag} onclick={chooseSampledGroupPivot}>Select original sampled group pivot</button>
            <label><input type="checkbox" aria-label="Drag sampled group pivots" checked={sampledGroupPivotCanvas} disabled={!sampledGroupPivot||busy||playing} onchange={e=>changeSampledGroupPivotCanvas(e.currentTarget.checked)}/>Drag original group pivot drafts</label>
            <label><input type="checkbox" aria-label="Author sampled group pivot on drag release" checked={sampledGroupPivotAuthoring} disabled={!sampledGroupPivotCanvas||busy||playing} onchange={e=>changeSampledGroupPivotAuthoring(e.currentTarget.checked)}/>Author group pivot on valid release</label>
            <label>Group pivot document X<input aria-label="Sampled group pivot document X" type="number" step="any" value={sampledGroupPivotX??''} disabled={!sampledGroupPivot||busy||playing||!!sampledStageDrag} oninput={e=>editSampledGroupPivotTarget('x',e.currentTarget.value)}/></label>
            <label>Group pivot document Y<input aria-label="Sampled group pivot document Y" type="number" step="any" value={sampledGroupPivotY??''} disabled={!sampledGroupPivot||busy||playing||!!sampledStageDrag} oninput={e=>editSampledGroupPivotTarget('y',e.currentTarget.value)}/></label>
            <button disabled={!sampledGroupPivotValid||busy||playing||!!sampledStageDrag||!!sampledStageProposed} onclick={previewSampledGroupPivot}>Preview sampled group pivot position</button>
            <button disabled={!sampledGroupPivotValid||busy||playing||!!sampledStageDrag} onclick={promoteSampledGroupPivot}>Promote and position sampled group pivot</button>
            <small>Sets one shared pivot for the complete original group while artwork stays fixed. Saved/default pivot interpolation must already be enabled; saved group orbit motion stays separate. Other drafts apply separately.</small>
          {/if}
          {#if !sampledStageGroups&&sampledStageChoice}
            <button disabled={busy||playing||!!sampledStageDrag} onclick={chooseSampledRootWaypoints}>Select original sampled root waypoints</button>
            {#if sampledRootWaypoints}
            <label><input type="checkbox" aria-label="Drag sampled root waypoints" checked={sampledRootWaypointCanvas} disabled={!sampledRootWaypoint||busy||playing} onchange={e=>changeSampledRootWaypointCanvas(e.currentTarget.checked)}/>Drag original saved root waypoint drafts</label>
            <label><input type="checkbox" aria-label="Author sampled root waypoint on release" checked={sampledRootWaypointAuthoring} disabled={!sampledRootWaypointCanvas} onchange={e=>changeSampledRootWaypointAuthoring(e.currentTarget.checked)}/>Author root waypoint on valid release</label>
            <small>Drag the original marker; Shift constrains the document axis. Release keeps an unapplied draft unless root waypoint release authoring is enabled.</small>
            <label>Saved waypoint number<input aria-label="Sampled root waypoint number" type="number" min="1" max={sampledRootWaypoints.path.waypoints.length} step="1" value={sampledRootWaypointNumber??''} disabled={busy||playing||!!sampledStageDrag} oninput={e=>chooseSampledRootWaypoint(e.currentTarget.value)}/></label>
            <label>Waypoint X offset<input aria-label="Sampled root waypoint X offset" type="number" step="any" value={sampledRootWaypointX??''} disabled={!sampledRootWaypoint||busy||playing||!!sampledStageDrag} oninput={e=>editSampledRootWaypoint('x',e.currentTarget.value)}/></label>
            <label>Waypoint Y offset<input aria-label="Sampled root waypoint Y offset" type="number" step="any" value={sampledRootWaypointY??''} disabled={!sampledRootWaypoint||busy||playing||!!sampledStageDrag} oninput={e=>editSampledRootWaypoint('y',e.currentTarget.value)}/></label>
            <button disabled={!sampledRootWaypointValid||busy||playing||!!sampledStageDrag||!!sampledStageProposed} onclick={previewSampledRootWaypoint}>Preview sampled root waypoint position</button>
            <button disabled={!sampledRootWaypointValid||busy||playing||!!sampledStageDrag} onclick={commitSampledRootWaypoint}>Commit sampled root waypoint position</button>
            <small>Offsets use the original root start position in document units. Existing handles and timing stay fixed; no waypoint is added or removed. Other drafts apply separately; commit explicitly.</small>
            {/if}
            <button disabled={busy||playing||!!sampledStageDrag} onclick={chooseSampledRootTrajectory}>Select original sampled root trajectory</button>
            {#if sampledRootTrajectory}
            <label><input type="checkbox" aria-label="Drag sampled root cubic controls" checked={sampledRootCurveCanvas} onchange={e=>changeSampledRootCurveCanvas(e.currentTarget.checked)}/>Drag original cubic control drafts</label>
            <label>Original cubic control<select aria-label="Sampled root cubic control role" value={sampledRootCurvePart} onchange={e=>changeSampledRootCurvePart(e.currentTarget.value)}><option value="start">Start control</option><option value="end">End control</option></select></label>
            <label><input type="checkbox" aria-label="Author sampled root cubic control on release" checked={sampledRootCurveAuthoring} disabled={!sampledRootCurveCanvas} onchange={e=>changeSampledRootCurveAuthoring(e.currentTarget.checked)}/>Author cubic control on valid release</label>
            <small>Only original markers own picks. Shift constrains the document axis. Release keeps an unapplied draft unless cubic release authoring is enabled.</small>
            {#each ['startX','startY','endX','endY'] as field}
            <label>Root cubic {field}<input aria-label={'Sampled root trajectory '+field} type="number" step="any" value={sampledRootTrajectoryControls[field as keyof GroupTrajectoryControls]??''} disabled={busy||playing||!!sampledStageDrag} oninput={e=>editSampledRootTrajectoryControl(field as keyof GroupTrajectoryControls,e.currentTarget.value)}/></label>
            {/each}
            <button disabled={!sampledRootTrajectoryValid||busy||playing||!!sampledStageDrag||!!sampledStageProposed} onclick={previewSampledRootTrajectory}>Preview sampled root trajectory</button>
            <button disabled={!sampledRootTrajectoryValid||busy||playing||!!sampledStageDrag} onclick={commitSampledRootTrajectory}>Commit sampled root trajectory</button>
            <small>Cubic offsets use the original root origins in document units. Other drafts apply separately; commit this route explicitly.</small>
            {/if}
          {/if}
          {#if !sampledStageGroups&&sampledStageMovable}
            <button disabled={busy||playing||!!sampledStageDrag} onclick={chooseSampledPivot}>Select original sampled pivot</button>
            <label><input type="checkbox" aria-label="Drag sampled pivots" checked={sampledPivotCanvas} disabled={!sampledPivot||busy||playing} onchange={e=>changeSampledPivotCanvas(e.currentTarget.checked)}/>Drag original pivot drafts</label>
            <label><input type="checkbox" aria-label="Author sampled pivot on drag release" checked={sampledPivotAuthoring} disabled={!sampledPivotCanvas||busy||playing} onchange={e=>changeSampledPivotAuthoring(e.currentTarget.checked)}/>Author pivot on valid release</label>
            <small>Drag the original pivot marker. Shift constrains the document axis. {sampledPivotAuthoring?'Valid release authors one undo step.':'Release sets unapplied coordinates; commit explicitly.'} Artwork stays fixed.</small>
            <label>Pivot document X<input aria-label="Sampled pivot document X" type="number" step="any" value={sampledPivotX??''} disabled={!sampledPivot||busy||playing||!!sampledStageDrag} oninput={e=>editSampledPivotTarget('x',e.currentTarget.value)}/></label>
            <label>Pivot document Y<input aria-label="Sampled pivot document Y" type="number" step="any" value={sampledPivotY??''} disabled={!sampledPivot||busy||playing||!!sampledStageDrag} oninput={e=>editSampledPivotTarget('y',e.currentTarget.value)}/></label>
            <button disabled={!sampledPivotValid||busy||playing||!!sampledStageDrag||!!sampledStageProposed} onclick={previewSampledPivot}>Preview sampled pivot position</button>
            <button disabled={!sampledPivotValid||busy||playing||!!sampledStageDrag} onclick={promoteSampledPivot}>Promote and position sampled pivot</button>
            <small>Changes the pivot while keeping artwork fixed. Both recipes must already allow pivot interpolation, with default pivots explicitly enabled for missing endpoints. Other drafts apply separately.</small>
          {/if}
          {#if sampledStageNodeShape}
            <label><input type="checkbox" aria-label="Drag sampled Bezier nodes" checked={sampledStageNodeCanvas} disabled={busy||playing} onchange={e=>changeSampledNodeCanvas(e.currentTarget.checked)}/>Pick and drag original anchors</label>
            <label><input type="checkbox" aria-label="Author sampled node on drag release" checked={sampledStageNodeAuthoring} disabled={busy||playing||!sampledStageNodeCanvas} onchange={e=>{cancelSampledStageDrag();sampledStageNodePolicy++;sampledStageNodeAuthoring=e.currentTarget.checked;}}/>Author node on release</label>
            <small>Pick an anchor, then drag the selected original anchor. Shift constrains the document axis. {sampledStageNodeAuthoring?'Release authors one undo step.':'Release keeps a preview; commit explicitly.'} Escape restores prior drafts.</small>
            <label>Bezier node (1–{sampledStageNodeShape.nodes?.length??0})<input aria-label="Sampled Bezier node number" type="number" min="1" step="1" max={sampledStageNodeShape.nodes?.length} value={sampledStageNode?sampledStageNode.index+1:''} disabled={busy||playing||!!sampledStageDrag} onchange={e=>chooseSampledStageNode(e.currentTarget.value)}/></label>
            <label>Node document X<input aria-label="Sampled node document X" type="number" step="any" bind:value={sampledStageNodeX} oninput={e=>editSampledNodeTarget('x',e.currentTarget.value)} disabled={!sampledStageNode||busy||playing||!!sampledStageDrag}/></label>
            <label>Node document Y<input aria-label="Sampled node document Y" type="number" step="any" bind:value={sampledStageNodeY} oninput={e=>editSampledNodeTarget('y',e.currentTarget.value)} disabled={!sampledStageNode||busy||playing||!!sampledStageDrag}/></label>
            <button disabled={!sampledStageNodeValid||busy||playing||!!sampledStageDrag||!!sampledStageProposed} onclick={previewSampledStageNode}>Preview sampled node position</button>
            <button disabled={!sampledStageNodeValid||busy||playing||!!sampledStageDrag} onclick={promoteSampledStageNode}>Promote and position sampled node</button>
            <small>Moves one original Bezier anchor and its existing handles. Topology stays fixed; both recipes must already allow node interpolation. Other transform drafts apply separately.</small>
            {#if sampledStageTangentParts.length}
            <label><input type="checkbox" aria-label="Drag sampled Bezier tangents" checked={sampledStageTangentCanvas} disabled={busy||playing||(sampledStageTangentCoupled&&sampledStageTangentParts.length!==2)} onchange={e=>changeSampledTangentCanvas(e.currentTarget.checked)}/> {sampledStageTangentCoupled?'Pick and drag paired tangent drafts':'Pick and drag original tangent handles'}</label>
            <label><input type="checkbox" aria-label="Author sampled tangent on drag release" checked={sampledStageTangentAuthoring} disabled={busy||playing||!sampledStageTangentCanvas||sampledStageTangentCoupled} onchange={e=>{cancelSampledStageDrag();sampledStageTangentPolicy++;sampledStageTangentAuthoring=e.currentTarget.checked;}}/>Author tangent on release</label>
            {#if sampledStageTangentCoupled}<label><input type="checkbox" aria-label="Author paired sampled tangent on drag release" checked={sampledStagePairedTangentAuthoring} disabled={busy||playing||!sampledStageTangentCanvas} onchange={e=>changePairedTangentAuthoring(e.currentTarget.checked)}/>Author paired tangent on release</label>{/if}
            <small>{sampledStageTangentCoupled?(sampledStagePairedTangentAuthoring?'Valid paired release freshly authors one undo step.':'Paired release keeps a preview; commit explicitly.'):sampledStageTangentAuthoring?'Valid release freshly authors one undo step.':'Release keeps a preview; commit explicitly.'} Escape restores prior drafts.</small>
            <label>Existing tangent<select aria-label="Sampled Bezier tangent role" value={sampledStageTangent?.part??''} disabled={busy||playing||!!sampledStageDrag} onchange={e=>chooseSampledStageTangent(e.currentTarget.value)}><option value="">Choose original handle</option>{#each sampledStageTangentParts as part}<option value={part}>{part==='in'?'Incoming':'Outgoing'}</option>{/each}</select></label>
            <label><input type="checkbox" aria-label="Couple sampled tangent handles" checked={sampledStageTangentCoupled} disabled={busy||playing||(!sampledStageTangentCoupled&&sampledStageTangentParts.length!==2)} onchange={e=>changeSampledTangentCoupling(e.currentTarget.checked)}/>Align opposite handle, preserving its document-space length</label>
            <label>Tangent document X<input aria-label="Sampled tangent document X" type="number" step="any" bind:value={sampledStageTangentX} oninput={e=>editSampledTangentTarget('x',e.currentTarget.value)} disabled={!sampledStageTangent||busy||playing||!!sampledStageDrag}/></label>
            <label>Tangent document Y<input aria-label="Sampled tangent document Y" type="number" step="any" bind:value={sampledStageTangentY} oninput={e=>editSampledTangentTarget('y',e.currentTarget.value)} disabled={!sampledStageTangent||busy||playing||!!sampledStageDrag}/></label>
            <button disabled={!sampledStageTangentValid||busy||playing||!!sampledStageDrag||!!sampledStageProposed} onclick={previewSampledStageTangent}>Preview sampled tangent position</button>
            <button disabled={!sampledStageTangentValid||busy||playing||!!sampledStageDrag} onclick={promoteSampledStageTangent}>Promote and position sampled tangent</button>
            <small>{sampledStageTangentCoupled?'Positions the chosen handle and aligns its existing opposite while preserving its document-space length. Paired drags preserve the original opposite-handle length; the paired release policy controls authoring.':'Moves only the chosen existing handle; the opposite handle stays fixed.'} The anchor stays fixed; node and transform drafts apply separately.</small>
            {/if}
          {/if}
          {#if sampledCompoundShape}
            <label><input type="checkbox" aria-label="Drag sampled compound anchors" checked={sampledCompoundNodeCanvas} disabled={busy||playing} onchange={e=>changeSampledCompoundNodeCanvas(e.currentTarget.checked)}/>Pick and drag original contour anchor drafts</label>
            <label><input type="checkbox" aria-label="Author sampled compound anchor on drag release" checked={sampledCompoundNodeAuthoring} disabled={busy||playing||!sampledCompoundNodeCanvas} onchange={e=>changeCompoundNodeAuthoring(e.currentTarget.checked)}/>Author compound anchor on valid release</label>
            <label>Anchor contour number<input aria-label="Sampled compound anchor contour number" type="number" min="1" step="1" max={sampledCompoundShape.contours?.length} value={sampledCompoundAnchorContour??''} disabled={busy||playing||!!sampledStageDrag} oninput={e=>changeSampledCompoundAnchorIndex('contour',e.currentTarget.value)}/></label>
            <label>Contour anchor number<input aria-label="Sampled compound anchor node number" type="number" min="1" step="1" max={sampledCompoundNodeRing?.length} value={sampledCompoundAnchorIndex??''} disabled={!sampledCompoundNodeRing||busy||playing||!!sampledStageDrag} oninput={e=>changeSampledCompoundAnchorIndex('node',e.currentTarget.value)}/></label>
            <label>Anchor document X<input aria-label="Sampled compound anchor document X" type="number" step="any" value={sampledCompoundNodeX??''} disabled={!sampledCompoundNodeSelection||busy||playing||!!sampledStageDrag} oninput={e=>editSampledCompoundAnchorTarget('x',e.currentTarget.value)}/></label>
            <label>Anchor document Y<input aria-label="Sampled compound anchor document Y" type="number" step="any" value={sampledCompoundNodeY??''} disabled={!sampledCompoundNodeSelection||busy||playing||!!sampledStageDrag} oninput={e=>editSampledCompoundAnchorTarget('y',e.currentTarget.value)}/></label>
            <button disabled={!sampledCompoundNodeValid||busy||playing||!!sampledStageDrag||!!sampledStageProposed} onclick={previewSampledCompoundNode}>Preview sampled compound anchor position</button>
            <button disabled={!sampledCompoundNodeValid||busy||playing||!!sampledStageDrag} onclick={promoteSampledCompoundNode}>Promote and position sampled compound anchor</button>
            <small>Moves the original anchor with its existing handle offsets. Tangent and transform drafts apply separately.</small>
            <label><input type="checkbox" aria-label="Drag sampled compound tangents" checked={sampledCompoundCanvas} disabled={busy||playing} onchange={e=>changeSampledCompoundCanvas(e.currentTarget.checked)}/>Pick and drag original contour handle drafts</label>
            <label><input type="checkbox" aria-label="Author sampled compound tangent on drag release" checked={sampledCompoundAuthoring} disabled={busy||playing||!sampledCompoundCanvas} onchange={e=>changeCompoundAuthoring(e.currentTarget.checked)}/>Author compound tangent on valid release</label>
            <label>Contour number<input aria-label="Sampled compound contour number" type="number" min="1" step="1" max={sampledCompoundShape.contours?.length} value={sampledCompoundContour??''} disabled={busy||playing||!!sampledStageDrag} oninput={e=>changeSampledCompoundIndex('contour',e.currentTarget.value)}/></label>
            <label>Contour node number<input aria-label="Sampled compound node number" type="number" min="1" step="1" max={sampledCompoundRing?.length} value={sampledCompoundNode??''} disabled={!sampledCompoundRing||busy||playing||!!sampledStageDrag} oninput={e=>changeSampledCompoundIndex('node',e.currentTarget.value)}/></label>
            <label>Existing compound tangent<select aria-label="Sampled compound tangent role" value={sampledCompound?.part??''} disabled={!sampledCompoundAnchor||busy||playing||!!sampledStageDrag} onchange={e=>chooseSampledCompoundPart(e.currentTarget.value)}><option value="">Choose original handle</option>{#each sampledCompoundParts as part}<option value={part}>{part==='in'?'Incoming':'Outgoing'}</option>{/each}</select></label>
            <label><input type="checkbox" aria-label="Couple sampled compound tangent handles" checked={sampledCompoundCoupled} disabled={busy||playing||(!sampledCompoundCoupled&&sampledCompoundParts.length!==2)} onchange={e=>changeSampledCompoundCoupling(e.currentTarget.checked)}/>Align opposite handle, preserving its document-space length</label>
            <label>Tangent document X<input aria-label="Sampled compound tangent document X" type="number" step="any" bind:value={sampledCompoundX} oninput={e=>editSampledCompoundTarget('x',e.currentTarget.value)} disabled={!sampledCompound||busy||playing||!!sampledStageDrag}/></label>
            <label>Tangent document Y<input aria-label="Sampled compound tangent document Y" type="number" step="any" bind:value={sampledCompoundY} oninput={e=>editSampledCompoundTarget('y',e.currentTarget.value)} disabled={!sampledCompound||busy||playing||!!sampledStageDrag}/></label>
            <button disabled={!sampledCompoundValid||busy||playing||!!sampledStageDrag||!!sampledStageProposed} onclick={previewSampledCompound}>Preview sampled compound tangent position</button>
            <button disabled={!sampledCompoundValid||busy||playing||!!sampledStageDrag} onclick={promoteSampledCompound}>Promote and position sampled compound tangent</button>
            <small>Edits one original contour handle. Other rings and anchors stay fixed; node interpolation must already be enabled. Transform drafts apply separately.</small>
          {/if}
          {#if sampledStageProposed}
            <span role="status">Proposed {sampledStageProposed.kind} · not applied. Discard the preview to pick or drag artwork.</span>
            <button onclick={()=>sampledStageProposal=null}>Discard sampled stage proposal</button>
          {/if}
          {/if}
          <button onclick={toggleSampledStage}>Return to authored stage</button>
          {#if sampledStage?.error}<span role="alert">{sampledStage.error}</span>{/if}
        </div>
      {/if}
      <div class="canvas-frame" class:script-covered={panelOpen&&!panelFloating&&scriptDock==='canvas'&&panelSelected}>
      {@render scriptSurface('canvas')}
      <div class="viewport" bind:this={viewport} id="canvas-workspace-panel"
        role={panelOpen&&!panelFloating&&scriptDock==='canvas'?'tabpanel':undefined}
        aria-labelledby={panelOpen&&!panelFloating&&scriptDock==='canvas'?'canvas-workspace-tab':undefined}>
        <canvas
          bind:this={canvas}
          id="drawing-stage"
          class:pan-tool={tool === 'hand' || temporaryHand || !!canvasPanButtons}
          class:canvas-panning={!!canvasPanButtons}
          class:draw-tool={tool !== 'select' && tool !== 'hand' && !temporaryHand}
          class:eyedropper-cursor={tool === 'eyedropper' && !temporaryHand && !canvasPanButtons}
          class:bucket-cursor={tool === 'bucket' && !temporaryHand && !canvasPanButtons}
          class:ink-cursor={tool === 'ink' && !temporaryHand && !canvasPanButtons}
          style:cursor={temporaryHand||canvasPanButtons?undefined:temporarySelectionCursor?'default':penAnchorCursor(penAnchorHover)??(ordinaryTransformCursor||undefined)}
          aria-label="Drawing stage"
          data-context="canvas"
          tabindex="0"
          ondragover={event => { if (!canvasResize) stageDragOver(event); }}
          ondrop={event => { if (!canvasResize) void dropOnStage(event); }}
          onpointerdown={event => { if (!canvasTouch.down(event) && (!canvasResize || event.button === 1)) stageDispatch.down(event); }}
          oncopy={copyCanvasArtwork}
          oncut={event => copyCanvasArtwork(event, true)}
          onpointermove={event => { if (!canvasTouch.move(event) && (!canvasResize || canvasPanButtons)) stageDispatch.move(event); }}
          onpointerup={event => { if (!canvasTouch.finish(event) && (!canvasResize || canvasPanButtons)) stageDispatch.up(event); }}
          onblur={()=>{spaceHand=false;temporarySelectionHeld=false;if(canvasPanButtons===1)endCanvasPan();}}
          ondblclick={(e) => {
            if(canvasResize||temporaryHand||canvasPanButtons)return;
            if(!liveCurveConfig&&!sampledStageMode&&!liveInputBlocked()&&tool==='select'&&primary?.kind==='text'&&selected.length===1&&directMember(primary)){beginStageText(primary,point(e as unknown as PointerEvent));return;}
            if(pickConnectedStrokes(e))return;
            if(!liveCurveConfig&&!sampledStageMode&&!liveInputBlocked()&&tool==='select'&&primary?.kind==='symbol'&&selected.length===1&&directMember(primary)){editSymbolInContext();return;}
            if(!liveCurveConfig&&!sampledStageMode&&canTransformSelection&&ordinaryTransformHit(ordinaryTransformPoint(e),ordinaryTransformView())?.kind==='pivot'){setPivot();return;}
            if (!liveCurveConfig && !sampledStageMode && tool === 'select') {
              if (activeLayer.drawingMode === 'merge') pickConnectedPaint(e);
              else enterGroup();
            }
          }}
          onauxclick={e=>{if(e.button===1)e.preventDefault();}}
          onpointercancel={event=>{if (!canvasTouch.finish(event, true)) stageDispatch.interrupt(event,false);}}
          onpointerleave={() => {
            if (!gesture) {hover = null;selectionTransformHover=null;snapLines={};}
          }}
          onlostpointercapture={event=>{if (!canvasTouch.finish(event, true, true)) stageDispatch.interrupt(event,true);}}
          oncontextmenu={(e) => {
            const penBarrel = e.button === 2 && 'pointerType' in e && e.pointerType === 'pen';
            if (penBarrel || canvasTouch.active || canvasResize || liveCurveConfig || sampledStageMode) e.preventDefault();
            else openContext(e, 'canvas');
          }}
        ></canvas>
        {#if canvasResize}
          <CanvasResizeOverlay bounds={canvasResize.bounds} matrix={camera.matrix} {viewWidth} {viewHeight}
            limit={documentSizeLimit} change={previewCanvasResize} />
        {/if}
        {#if stageText && stageTextPreview}
          {#key stageText.shape.id}<CanvasTextEditor bind:this={stageTextEditor} shape={stageText.shape} view={camera.matrix} width={viewWidth} height={viewHeight} initialPoint={stageText.point} creating={!stageText.owner}
            preview={value=>stageTextPreview=value} apply={finishStageText} formatting={style=>stageTextStyle=style}
            selection={(start,end,content)=>{if(stageText)textSelection={owner:stageText.shape.id,start,end,content};}}
            cancel={()=>{const owner=stageText?.owner;stageText=null;stageTextPreview=null;selected=owner?[owner]:[];canvas.focus();}}
            outside={stageDispatch.down}/>{/key}
        {/if}
        {#if !liveCurveConfig && !sampledStageMode && editNodeHintsOnStage && !playing}
    {#key `${project.id}:${layerId}:${frame}:${rangeStart}:${rangeEnd}`}
      <MotionNodeHints source={activeLayer.keys.find(k => k.frame === rangeStart)?.shapes[0]} target={activeLayer.keys.find(k => k.frame === rangeEnd)?.shapes[0]} bind:value={motionNodeHints} straight={motionMatchStraightNodes} curves={motionMatchCurvedNodes} distance={motionCurveDistance} offset={motionContourStart} offsets={motionContourOffsets} reverse={motionContourReverse} directions={motionContourDirections} order={motionContourOrder} label="Stage motion" stageBox={stageOverlayBox} stageMatrix={stageOverlayMatrix} stageScale={zoom} />
    {/key}
  {/if}
  {#if !liveCurveConfig && !sampledStageMode && editMotionOnStage && !editNodeHintsOnStage && motionPath && !playing}
          {@const pathStart=activeLayer.keys.find(k=>k.frame===rangeStart)?.shapes[0]}
          {@const pathEnd=activeLayer.keys.find(k=>k.frame===rangeEnd)?.shapes[0]}
          {#if pathStart && pathEnd}
            {#key `${project.id}:${layerId}:${frame}:${rangeStart}:${rangeEnd}`}
              <MotionPathPreview groupSource={activeLayer.keys.find(k=>k.frame===rangeStart)?.shapes ?? []} groupTarget={activeLayer.keys.find(k=>k.frame===rangeEnd)?.shapes ?? []} groupRotation={motionRotation} bind:value={motionPath} start={pathStart} end={pathEnd} label="Stage motion path"
                stageBox={stageOverlayBox} stageMatrix={stageOverlayMatrix} stageScale={zoom} />
            {/key}
          {/if}
        {/if}
        <div class="stage-caption">
          {displayedCanvasSize.width} × {displayedCanvasSize.height} px <span>·</span>
          {project.fps} fps
        </div>
      </div>
      <CanvasScrollbars {pan} width={viewWidth} height={viewHeight} documentWidth={stageFootprint.width} documentHeight={stageFootprint.height} {zoom}
        blocked={navigationBlocked} change={value=>{pan=value;hover=null;}}/>
      </div>
      {@render scriptTabs('timeline')}
      <div class="script-timeline-slot" class:script-covered={panelOpen&&!panelFloating&&scriptDock==='timeline'&&panelSelected}>
      {@render scriptSurface('timeline')}
      <div id="timeline-workspace-panel" role={panelOpen&&!panelFloating&&scriptDock==='timeline'?'tabpanel':undefined}
        aria-labelledby={panelOpen&&!panelFloating&&scriptDock==='timeline'?'timeline-workspace-tab':undefined}>
      <TimelinePanel inert={pendingDrawingJobs||panelOpen&&!panelFloating&&scriptDock==='timeline'&&panelSelected} bind:canvas={timelineCanvas} bind:layerList {frame} activeLayerName={activeLayer.name} frameLabel={project.frameLabels?.find(label => label.frame === frame)?.name} frameComment={project.frameComments?.find(comment => comment.frame === frame)?.text} frameScript={project.frameScripts?.some(script => script.frame === frame)} duration={project.duration} fps={project.fps} playing={playing||!!timelineAudio} {onion} height={workspace.timelineContent} {frameStart} {layerStart}
        frameSelection={{start:futureTimelineBlock?.start??rangeStart,end:futureTimelineBlock?.end??rangeEnd,layers:timelineBlockSelected||(dragBatchFrames&&rangeEnd>rangeStart)?selectedBatchLayers.length:1}}
        {cellWidth} frameLimit={scopedSymbol?10000:100000}
        canZoom={()=>!timelineScrub.active&&!timelineDrag&&!timelineEdit.active&&!gesture&&!hierarchyDrag&&!modal&&!contextMenu&&!busy}
        changeZoom={view=>{cellWidth=view.cellWidth;frameStart=view.frameStart;}}
        layerMax={Math.max(0,expandedLayers.length-workspace.timelineRows)}
        first={()=>transportTimeline(0)} last={()=>transportTimeline(project.duration-1)} play={toggleTimelinePlayback} toggleOnion={()=>onion=!onion}
        keyframe={keyframe} removeKey={() => removeTimelineSelection('keys')} addLayer={addLayer} deleteLayer={deleteLayer} shiftLayer={shiftLayer} deleteDisabled={activeLayer.locked||project.layers.length<2||!!scopedSymbol&&layerId==='@base'}
        changeFrameStart={value=>frameStart=value} changeLayerStart={value=>layerStart=value} down={timelineClick} move={timelineMove} up={timelineUp} keys={timelineKeys}
        context={e=>openContext(e,'timeline')} layerContext={e=>openContext(e,'layer',layerId)} cancel={e=>{timelineEdit.cancel(e.pointerId);endTimelineScrub(e.pointerId);}} blur={()=>{endTimelineScrub();timelineEdit.cancel();}}
        listOver={e=>{if(hierarchyDrag)hierarchyPointerY=e.clientY;}} listLeave={e=>{if(!(e.relatedTarget instanceof Node)||!(e.currentTarget as HTMLDivElement).contains(e.relatedTarget)){hierarchyPointerY=null;hierarchyDrop=null;}}}
        rootOver={e=>{if(hierarchyDrag)e.preventDefault();}} rootDrop={e=>dropHierarchy(e)}>
        {#snippet divider()}
        {@render scriptTimelineDivider()}
        {/snippet}
        {#snippet rows()}
            {#each visibleLayers as layer}<div
                draggable={layerRename?.id!==layer.id}
                role="group"
                aria-label={layer.folderRowId
                  ? 'Folder row ' + layer.name
                  : 'Layer row ' + layer.name}
                ondragstart={(e) =>
                  beginHierarchyDrag(
                    e,
                    layer.folderRowId ? 'folder' : 'layer',
                    layer.folderRowId ?? layer.id,
                  )}
                ondragend={endHierarchyDrag}
                ondragover={e=>overHierarchyRow(e,layer)}
                ondrop={e=>dropHierarchyRow(e,layer)}
                oncontextmenu={(e) =>
                  openContext(
                    e,
                    layer.folderRowId ? 'folder' : 'layer',
                    layer.folderRowId ?? layer.id,
                  )}
                data-context={layer.folderRowId ? 'folder' : 'layer'}
                data-context-id={layer.folderRowId ?? layer.id}
                tabindex="-1"
                class="layer-row"
                class:layer-drop-above={hierarchyDrop?.marker===layer.id&&hierarchyDrop.side==='above'}
                class:layer-drop-below={hierarchyDrop?.marker===layer.id&&hierarchyDrop.side==='below'}
                class:layer-drop-inside={hierarchyDrop?.marker===layer.id&&hierarchyDrop.side==='inside'}
                class:masked-layer={!!project.layerMasks?.some(m=>m.layerIds.includes(layer.id))}
                class:mask-layer={!!project.layerMasks?.some(m=>m.maskLayerId===layer.id)}
                class:current={layer.id === layerId || layer.folderRowId === selectedFolder}
              >
                {#if layer.folderRowId}
                  <button
                    class="folder-name"
                    style:padding-left={(folderPath(project, layer.folderRowId).length - 1) * 10 +
                      'px'}
                    onclick={() => {
                      chooseFolder(layer.folderRowId!);
                      frameAnchor = frame;
                      frameAnchorLayer = layerId;
                    }}>{layer.name}</button
                  >
                  <button
                    aria-label={'Toggle folder ' + layer.name}
                    onclick={() => {
                      const id = layer.folderRowId!;
                      collapsedFolders = collapsedFolders.includes(id)
                        ? collapsedFolders.filter((f) => f !== id)
                        : [...collapsedFolders, id];
                      layerStart = 0;
                    }}>{collapsedFolders.includes(layer.folderRowId) ? '▸' : '▾'}</button
                  >
                {:else}
                  <TimelineLayerControls {layer} current={layer.id===layerId} label={layer.folderId ? folderLabel(project,layer.folderId)+' / '+layer.name : layer.name} icon={project.layerMasks?.some(m=>m.maskLayerId===layer.id)?'◩':maskOwner(layer.id)?'↳':layer.guideLayer?'⌁':'▱'} tween={tweenLayerLabel(layer)} renaming={layerRename?.id===layer.id} name={layerRename?.id===layer.id?layerRename.name:layer.name}
                  select={()=>{layerId=layer.id;selected=[];}} rename={()=>beginLayerRename(layer.id)} commit={(name,restore)=>{if(layerRename)closeLayerRename(layerRename,restore,name);}} cancel={restore=>{if(layerRename)closeLayerRename(layerRename,restore);}}
                  toggle={kind=>edit(kind==='outline'?'Toggle layer outline':kind==='visible'?'Toggle layer visibility':'Toggle layer lock',()=>{layer[kind]=!layer[kind];if(kind!=='outline')selected=[];},kind==='outline')}/>

                {/if}
              </div>{/each}
        {/snippet}
      </TimelinePanel>
      </div>
      </div>
    </section>
    {#if panelLayout.sidebarVisible && !inspectorCollapsed}<WorkspaceDivider label="Resize properties sidebar" controls="properties-sidebar" reverse={!inspectorLeft} offset={inspectorLeft?workspace.tools:0} value={workspace.inspector} min={workspace.inspectorMin} max={workspace.inspectorMax} defaultValue={DEFAULT_WORKSPACE_SIZES.inspector} context={workspaceContext} canStart={() => canResizeWorkspace('inspector')} preview={value => previewWorkspace('inspector', value)} commit={value => commitWorkspace('inspector', value)} />{/if}
    <aside id="properties-sidebar" class="inspector" aria-label="Properties" class:workspace-hidden={!panelLayout.sidebarVisible} inert={!panelLayout.sidebarVisible || pendingDrawingJobs}
      style:width={inspectorCollapsed ? `${inspectorRailWidth}px` : undefined}>
      <div class="inspector-tabs" class:inspector-rail={inspectorCollapsed}>
        {#if !inspectorCollapsed}<strong>Properties</strong>{/if}
        <button type="button" class="inspector-toggle"
          aria-label={inspectorCollapsed ? 'Expand Properties sidebar' : 'Collapse Properties sidebar'}
          title={inspectorCollapsed ? 'Expand Properties sidebar' : 'Collapse Properties sidebar'}
          aria-expanded={!inspectorCollapsed} aria-controls="properties-sidebar-body"
          onkeydown={event => {
            if ((event.key === 'Enter' || event.key === ' ') && !event.ctrlKey && !event.metaKey && !event.altKey && !event.shiftKey)
              event.stopPropagation();
          }}
          onclick={() => panelLayout = {...panelLayout, sidebarCollapsed: !inspectorCollapsed}}>
          <span aria-hidden="true">{inspectorLeft === inspectorCollapsed ? '»' : '«'}</span>
        </button>
      </div>
      <div id="properties-sidebar-body" class="inspector-body" hidden={inspectorCollapsed}>
      {#if scopedButtonStates}
        <fieldset class="button-state-properties">
          <legend>Button state frames</legend>
          <div class="property-grid">
            {#each buttonStateRoles as role}
              <label>{buttonStateLabels[role]}<input type="number" min="1" max={project.duration} step="1"
                aria-label={`Button ${buttonStateLabels[role]} frame`} value={scopedButtonStates[role] + 1}
                disabled={busy || playing || !!penDraft || !!timelineDrag}
                onchange={event => editButtonStateFrame(role, event.currentTarget)} /></label>
            {/each}
          </div>
        </fieldset>
      {/if}
      {#snippet artworkDimensions(artwork: Vector, disabled: boolean)}
        <div class="property-grid">
          {#each [['x', 'X'], ['y', 'Y'], ['width', 'W'], ['height', 'H'], ['rotation', 'Rotation']] as [field, label]}
            <label>{label}<input
              aria-label={`Shape ${label}`}
              type="number"
              step="1"
              {disabled}
              value={Math.round(artwork[field as 'x'] * 100) / 100}
              onchange={event => setShape(field as 'x', event.currentTarget.value)}
            /></label>
          {/each}
        </div>
      {/snippet}
      <PanelWorkspace layout={panelLayout} change={value=>panelLayout=value}>
      {#if selectedKeyframe && !playing && !timelineDrag}
        {@const settings = selectedKeyframe}
        {@const at = settings.key.frame}
        {@const commandsBlocked = busy || !!modal || !!penDraft || !!preview || !!stageText}
        {@const tweenBlocked = commandsBlocked || activeLayer.locked || sampledStageMode || !!liveCurveConfig || multiFrame}
        <DockPanel id="keyframe" heading="Keyframe">
          <div class="keyframe-properties" data-keyframe-properties>
            <dl>
              <dt>Frame</dt><dd>{at + 1} · {activeLayer.name}</dd>
              <dt>Contents</dt><dd>{settings.key.shapes.length ? 'Artwork' : 'Blank'}</dd>
              <dt>Tween type</dt><dd>{settings.kind === 'motion' ? 'Motion tween' : settings.kind === 'shape' ? 'Shape tween' : 'None'}</dd>
              <dt>Label</dt><dd>{settings.label ?? 'None'}</dd>
              <dt>Comment</dt><dd>{settings.comment ?? 'None'}</dd>
              <dt>Script</dt><dd>{settings.scripted ? 'Attached' : 'None'}</dd>
            </dl>
            <div class="keyframe-actions">
              <button type="button" disabled={commandsBlocked} onclick={event => openFrameAnnotation('label', at, event.currentTarget)}>Edit label…</button>
              <button type="button" disabled={commandsBlocked} onclick={event => openFrameAnnotation('comment', at, event.currentTarget)}>Edit comment…</button>
              <button type="button" disabled={commandsBlocked} onclick={() => openFrameSource(at, undefined, true)}>Open frame script</button>
              {#if !settings.kind && settings.key.shapes.length}
                <button type="button" disabled={tweenBlocked} onclick={() => convertTimelineTween('motion')}>Create motion tween</button>
                <button type="button" disabled={tweenBlocked} onclick={() => convertTimelineTween('shape')}>Create shape tween</button>
              {:else if settings.kind}
                {@const kind = settings.kind}
                {#if settings.openMotion}
                  <button type="button" disabled={tweenBlocked || !activeLayer.visible} onclick={event => openTimelineTween('motion', true, undefined, event.currentTarget)}>Edit easing…</button>
                {:else if kind === 'shape' && settings.span && !scopedSymbol && activeLayer.liveMotionSpans?.some(span =>
                  span.id === settings.span?.id && typeof span.correspondence?.nodes === 'object' && span.correspondence.nodes.shapes)}
                  {@const spanId = settings.span.id}
                  <button type="button" disabled={tweenBlocked || !activeLayer.visible} onclick={event => openTimelineTween('shape', false, spanId, event.currentTarget)}>Edit shape hints…</button>
                {/if}
                <button type="button" disabled={tweenBlocked} onclick={() => insertTimelineCell(kind === 'motion' ? 'remove-motion' : 'remove-shape', at, true)}>Remove {kind} tween</button>
              {/if}
            </div>
          </div>
        </DockPanel>
      {/if}
      {#if frameAnchor !== null && frameAnchorLayer === layerId}
        <DockPanel id="frames" heading="FRAME RANGE">
          <details>
            <summary>Layer folders</summary>
            <label
              >Folder<select
                aria-label="Selected folder"
                value={selectedFolder}
                onchange={(e) => chooseFolder(e.currentTarget.value)}
                ><option value="">New folder</option>{#each project.folders ?? [] as f}<option
                    value={f.id}>{folderLabel(project, f.id)}</option
                  >{/each}</select
              ></label
            >
            <label
              >Name<input aria-label="Folder name" bind:value={folderName} maxlength="80" /></label
            >
            <label
              >Parent<select aria-label="Folder parent" bind:value={folderParent}
                ><option value="">Root</option>{#each project.folders ?? [] as f}<option
                    value={f.id}>{folderLabel(project, f.id)}</option
                  >{/each}</select
              ></label
            >
            <button onclick={() => editFolder('create')}>Create folder</button>
            <button disabled={!selectedFolder} onclick={() => editFolder('update')}
              >Update folder</button
            >
            <button disabled={!selectedFolder} onclick={() => editFolder('remove')}
              >Remove folder, keep layers</button
            >
            <label
              >Layer folder<select
                aria-label="Active layer folder"
                value={activeLayer.folderId ?? ''}
                onchange={(e) =>
                  edit('Assign layer folder', () =>
                    assignFolder(project, layerId, e.currentTarget.value || undefined),
                  )}
                ><option value="">Root</option>{#each project.folders ?? [] as f}<option
                    value={f.id}>{folderLabel(project, f.id)}</option
                  >{/each}</select
              ></label
            >
            <button
              disabled={!selectedFolder}
              onclick={() => {
                collapsedFolders = collapsedFolders.includes(selectedFolder)
                  ? collapsedFolders.filter((id) => id !== selectedFolder)
                  : [...collapsedFolders, selectedFolder];
                layerStart = 0;
              }}
              >{collapsedFolders.includes(selectedFolder)
                ? 'Expand folder rows'
                : 'Collapse folder rows'}</button
            >
            <button disabled={!selectedFolder} onclick={() => editFolder('hide')}
              >Hide folder layers</button
            ><button disabled={!selectedFolder} onclick={() => editFolder('show')}
              >Show folder layers</button
            >
            <button disabled={!selectedFolder} onclick={() => editFolder('lock')}
              >Lock folder layers</button
            ><button disabled={!selectedFolder} onclick={() => editFolder('unlock')}
              >Unlock folder layers</button
            >
            <p class="hint">
              Sibling order changes folder rows only. Front/back changes artwork stacking for all
              descendant layers, keeping their internal order.
            </p>
            <button disabled={foregroundBusy || !selectedFolder} onclick={() => arrangeFolder('up')}
              >Move folder earlier</button
            >
            <button disabled={foregroundBusy || !selectedFolder} onclick={() => arrangeFolder('down')}
              >Move folder later</button
            >
            <button disabled={foregroundBusy || !selectedFolder} onclick={() => arrangeFolder('top')}
              >Bring folder artwork to front</button
            >
            <button disabled={foregroundBusy || !selectedFolder} onclick={() => arrangeFolder('bottom')}
              >Send folder artwork to back</button
            >

            <p class="hint">
              Folders organize layers without changing paint order. Removing a folder promotes its
              layers and children. Collapse affects timeline rows only.
            </p>
          </details>

          <details>
            <summary>Layer organization</summary>
            <button onclick={() => organizeLayer('duplicate')}>Duplicate layer</button>
            <button disabled={activeLayer.locked || !activeLayer.visible} onclick={() => organizeLayer('distribute')}>Distribute artwork to layers</button>
            <p>Separate objects and outer groups across all keys, preserving blank timing. Conflicting stack orders reject the entire change.</p>
            <button onclick={() => organizeLayer('top')}>Move layer to top</button>
            <button onclick={() => organizeLayer('bottom')}>Move layer to bottom</button>
            <button onclick={() => organizeLayer('solo')}>Show only this layer</button>
            <button onclick={() => organizeLayer('show')}>Show all layers</button>
            <button onclick={() => organizeLayer('lockOthers')}>Lock other layers</button>
            <button onclick={() => organizeLayer('unlock')}>Unlock all layers</button>
          </details>

          <label
            >Go to frame<input
              aria-label="Go to frame"
              type="number"
              min="1"
              max={project.duration}
              value={frame + 1}
              onchange={(e) => navigateFrame(Number(e.currentTarget.value) - 1)}
            /></label
          >
          <button onclick={() => navigateFrame(frame - 1)}>Previous frame</button><button
            onclick={() => navigateFrame(frame + 1)}>Next frame</button
          >
          <details>
            <summary>Onion skin settings</summary>
            <label><input type="checkbox" bind:checked={onion} />Enable onion skin</label>
            <label
              >Before<input
                aria-label="Onion frames before"
                type="number"
                min="0"
                max="12"
                bind:value={onionBefore}
              /></label
            >
            <label
              >After<input
                aria-label="Onion frames after"
                type="number"
                min="0"
                max="12"
                bind:value={onionAfter}
              /></label
            >
            <NumberSlider liveNumber label="Onion opacity" caption="Opacity %" value={onionOpacity} min={0} max={80} scope={frame} onchange={value=>onionOpacity=value}/>
            <label
              ><input type="checkbox" bind:checked={onionFade} />Fade distant onion frames</label
            >
            <label><input type="checkbox" bind:checked={onionKeys} />Onion key exposures only</label
            >
            <label
              ><input type="checkbox" bind:checked={onionActive} />Onion active layer only</label
            >
            <label
              ><input
                type="checkbox"
                aria-label="Onion outlines"
                bind:checked={onionOutline}
              />Outline onion skins</label
            >
            <label
              ><input type="checkbox" aria-label="Onion tint" bind:checked={onionTint} />Tint onion
              frames</label
            >
            <label
              >Past color<input
                type="color"
                aria-label="Onion past color"
                bind:value={onionPastColor}
              /></label
            >
            <label
              >Future color<input
                type="color"
                aria-label="Onion future color"
                bind:value={onionFutureColor}
              /></label
            >
            <p class="hint">
              Editor-only ghosts; hidden during playback and excluded from exports. In key exposure
              mode, counts refer to distinct exposure boundaries. Live tween tracks are excluded until live onion sampling is qualified.
            </p>
          </details>

          <button disabled={foregroundBusy || activeLayer.locked} onclick={() => copyTimeline()}
            >Copy frames</button
          >
          <button disabled={foregroundBusy || activeLayer.locked} onclick={() => copyTimeline(true)}
            >Cut frames</button
          >
          <button
            disabled={foregroundBusy || activeLayer.locked || !hasFrameClipboard}
            onclick={pasteTimeline}>Insert copied frames</button
          >
          <label><input type="checkbox" bind:checked={dragFrames} />Drag selected frames</label>
          <label
            ><input type="checkbox" bind:checked={dragAcrossLayers} />Drag active range between
            layers</label
          >
          {#if timelineDrag?.cross}<p>
              Drop layer: {project.layers.find((l) => l.id === timelineDrag?.target)?.name ??
                'No valid layer'}
            </p>{/if}
          {#if timelineDrag}<p>
              Move to frames {timelineDrag.at + 1}–{timelineDrag.at +
                timelineDrag.end -
                timelineDrag.start +
                1}
            </p>{/if}

          <label
            ><input
              type="checkbox"
              aria-label="Move multiple frames"
              bind:checked={multiFrame}
              onchange={() => {
                crossLayerMode=false;crossLayerPolicy++;
                if (gesture) cancelGesture();
                tool = 'select';
                selected = [];
              }}
            />Move multiple frames</label
          >
          {#if multiFrame && !crossLayerMode}
            <label
              ><input
                type="checkbox"
                aria-label="Multi-frame transform handles"
                bind:checked={multiHandles}
                onchange={() => {
                  if (gesture) cancelGesture();
                  if (multiHandles && !project.multiFramePivot) centerMultiPivot();
                }}
              />Show multi-frame transform handles</label
            >
            <button onclick={centerMultiPivot}>Center multi-frame pivot</button>
            <p>
              Corner handles scale; Shift keeps proportions, Alt scales around the shared pivot. The
              raised top handle rotates. Edge midpoints skew along their edge; Alt uses the shared
              pivot. Shift snaps rotation and skew to 15 degrees. Cyan outlines preview changes;
              Drag the crosshair to move the shared pivot; Shift constrains its axis. Pivot movement
              is session-only. Escape cancels.
            </p>
            <label
              ><input
                type="checkbox"
                aria-label="Pick multi-frame objects"
                bind:checked={multiPick}
                onchange={() => {
                  if (gesture) cancelGesture();
                  multiSelection = multiPick ? [] : null;
                }}
              />Pick objects across frames</label
            >
            <label
              >Selection gesture<select
                aria-label="Multi-frame selection gesture"
                bind:value={multiPickForm}
                onchange={() => {
                  if (gesture) cancelGesture();
                }}
              >
                <option value="point">Point / move</option><option value="box">Marquee</option
                ><option value="lasso">Freehand lasso</option>
              </select></label
            >
            <p>
              Marquee/lasso encloses transformed object boxes. Shift adds, Alt subtracts, Shift+Alt
              intersects. Escape cancels. Switch to Point / move to drag picks.
            </p>
            <button disabled={foregroundBusy} onclick={deleteMultipleFrames}
              >Delete multi-frame artwork</button
            >
            <p>
              Picking uses the topmost layer and latest key at the pointer. Groups stay together.
              Shift-click adds/removes groups. Scope changes and undo clear picks.
            </p>
            <button
              onclick={() => {
                if (!gesture) multiSelection = null;
              }}>Select all multi-frame objects</button
            >
            <button
              onclick={() => {
                if (!gesture) multiSelection = [];
              }}>Clear multi-frame selection</button
            >
            <p>
              {multiSelection === null ? 'All objects' : `${multiSelection.length} picked members`}
            </p>
            {#if sampledTrajectorySelection?.revision===historyTick}<output aria-label="Updated trajectory selection">Trajectory · {sampledTrajectorySelection.units} units · {sampledTrajectorySelection.tracks} tracks · {sampledTrajectorySelection.members} artwork members</output>{/if}
            {#if sampledAuthoredSelectionRevision===historyTick&&sampledAuthoredSelectionSkew}
              <output aria-label="Authored sampled selection skew">Skew · {sampledAuthoredSelectionSkew.axis.toUpperCase()} · {sampledAuthoredSelectionSkew.degrees}° · Pivot {sampledAuthoredSelectionSkew.pivot.x.toFixed(2)}, {sampledAuthoredSelectionSkew.pivot.y.toFixed(2)}</output>
            {/if}
            {#if sampledAuthoredSelectionRevision===historyTick&&sampledAuthoredSelectionScale}
              <output aria-label="Authored sampled selection scale">Scale · {(sampledAuthoredSelectionScale.x*100).toFixed(2)}%, {(sampledAuthoredSelectionScale.y*100).toFixed(2)}% · Pivot {sampledAuthoredSelectionScale.pivot.x.toFixed(2)}, {sampledAuthoredSelectionScale.pivot.y.toFixed(2)}</output>
            {/if}
            {#if sampledAuthoredSelectionRevision===historyTick&&sampledAuthoredSelectionRotation}
              <output aria-label="Authored sampled selection rotation">Rotation · {sampledAuthoredSelectionRotation.degrees}° · Pivot {sampledAuthoredSelectionRotation.pivot.x.toFixed(2)}, {sampledAuthoredSelectionRotation.pivot.y.toFixed(2)}</output>
            {/if}
            <label
              >Rotation<input
                type="number"
                aria-label="Multi-frame rotation"
                bind:value={multiAngle}
              /></label
            >
            <label
              >Scale %<input
                type="number"
                aria-label="Multi-frame scale"
                bind:value={multiScale}
              /></label
            >
            <label
              >Pivot X<input
                type="number"
                aria-label="Multi-frame pivot X"
                bind:value={multiPivotX}
              /></label
            >
            <label
              >Pivot Y<input
                type="number"
                aria-label="Multi-frame pivot Y"
                bind:value={multiPivotY}
              /></label
            >
            <button disabled={foregroundBusy} onclick={() => rememberMultiPivot()}>Remember pivot</button>
            <button
              disabled={foregroundBusy || !project.multiFramePivot}
              onclick={() => rememberMultiPivot(true)}>Forget saved pivot</button
            >
            <button disabled={foregroundBusy} onclick={transformMultipleFrames}
              >Transform multi-frame artwork</button
            >
            <p>
              Drag on the canvas to move chosen artwork in the selected range on checked layers, or
              the active layer if none are checked. Purple outlines show the scope; cyan outlines
              show picks. In point mode, Alt-click cycles overlapping objects/groups without moving
              them. Whole holds are edited, including portions outside the range. Shift constrains
              the axis; Escape cancels.
            </p>
            <label
              >X offset<input
                type="number"
                aria-label="Multi-frame X offset"
                bind:value={multiX}
              /></label
            >
            <label
              >Y offset<input
                type="number"
                aria-label="Multi-frame Y offset"
                bind:value={multiY}
              /></label
            >
            <button disabled={foregroundBusy} onclick={() => moveMultipleFrames(multiX, multiY)}
              >Move multi-frame artwork</button
            >
            {#if multiFrame && !crossLayerMode}
              <label>Anchor number<input type="number" min="1" step="1" aria-label="Multi-frame anchor number" bind:value={rangeAnchorNumber} /></label>
              <button disabled={foregroundBusy || multiSelection?.length === 0} onclick={movePickedRangeAnchors}
                title="Apply the X and Y offsets to this anchor on each selected path">Move multi-frame anchors</button>
            {/if}
          {/if}
          <p>Frames {rangeStart + 1}–{rangeEnd + 1} · {rangeEnd - rangeStart + 1} selected</p>
          <p class="hint">
            Shift-click timeline cells to select a range. Removing frames shifts later keys on the
            active layer and can shorten the timeline when the selection reaches the end.
          </p>
          <button
            disabled={foregroundBusy || activeLayer.locked}
            onclick={() => timelineRangeEdit('duplicate')}>Duplicate frame range</button
          >
          <button disabled={foregroundBusy || activeLayer.locked} onclick={() => timelineRangeEdit('keys')}>Key every frame in range</button>
          <p>Copies held artwork into explicit keys. Nested playback is not baked; new keys use the same instance playback settings.</p>
          <button disabled={foregroundBusy || activeLayer.locked} onclick={() => timelineRangeEdit('reverse')}
            >Reverse frame range</button
          >
          <button disabled={foregroundBusy || activeLayer.locked} onclick={() => timelineRangeEdit('remove')}
            >Remove layer frames</button
          >
          <fieldset disabled={foregroundBusy || activeLayer.locked}>
            <legend>Motion in-betweens</legend>
            <MotionEasing bind:value={motionEase} label="Motion easing" />
            <MotionRotationControls bind:value={motionRotation} label="Motion rotation" />
            <label><input type="checkbox" aria-label="Motion reverse contour matching" bind:checked={motionContourReverse} />Reverse end node matching</label>
    <label>End contour start offset <input type="number" min="0" step="1" aria-label="Motion contour start offset" bind:value={motionContourStart} /></label>
    <label>End contour order (optional) <input aria-label="Motion contour order" bind:value={motionContourOrder} placeholder="1, 0" /></label>
    <small>List every end contour index once, starting at zero, in source matching order. Blank keeps authored order. Per-contour offsets apply after this ordering.</small>
    <label>Per-contour directions (optional) <input aria-label="Motion per-contour directions" bind:value={motionContourDirections} placeholder="forward, reverse" /></label>
    <small>List forward or reverse for each contour in source matching order, after end contour ordering. Blank uses the shared reversal; an explicit list overrides it. Requires node interpolation.</small>
    <label>Per-contour offsets (optional) <input aria-label="Motion per-contour offsets" bind:value={motionContourOffsets} placeholder="0, 2" /></label>
    <small>Comma-separated offsets override the shared offset in contour order. Supply one per contour of every selected path.</small>
    <small>With node interpolation, pair the first node with this end-contour node offset (wraps per contour). Reversal pairs nodes backward from the offset and swaps handles. Open Bezier paths allow reversal at offset zero only. Closed contours with repeated closing anchors are unsupported. Endpoint keys stay unchanged.</small>
    <label><input type="checkbox" aria-label="Motion validate curve self contacts" bind:checked={motionCurveSelfContacts} />Reject self-contact within each Bezier segment (requires nodes)</label>
    <small>Checks all curve positions and motion progress. Stationary tangents, missing endpoint handles and unresolved cases also reject. Does not check contacts between different segments or objects.</small>
    <label><input type="checkbox" aria-label="Motion validate curve tangents" bind:checked={motionCurveTangents} />Reject stationary or reversing Bezier tangents (requires nodes)</label>
    <p>Checks all motion progress and curve positions. Missing endpoint handles, near-zero tangents, reversing joins and unresolved cases reject. Does not prevent crossings.</p>
    <label><input type="checkbox" aria-label="Motion validate contour contacts" bind:checked={motionContourContacts} />Reject contour contacts (straight or Bezier)</label>
    <small>Checks contacts throughout node interpolation, plus segment and closed-area collapse. Straight contours include adjacent retracing and contacts between contours. Bezier curves allow shared endpoints but reject other segment contacts. Self-contact within one cubic requires the separate self-contact option. Use the tangent guard separately for stationary or reversing joins. Separate objects are excluded. Bounded work rejects unresolved or over-budget input.</small>
    <label><input type="checkbox" aria-label="Motion validate contour edges" bind:checked={motionContourEdges} />Reject segment collapse and closed area collapse</label>
    <small>Requires node interpolation. Checks straight and cubic segments throughout the tween, including open paths. Crossings, cusps and contour contacts are not checked.</small>
    <label><input type="checkbox" aria-label="Motion validate contour areas" bind:checked={motionContourAreas} />Reject closed contour area collapse (requires node interpolation)</label>
    <small>Checks polygon and closed Bezier contour areas throughout the tween. Rejects signed-area collapse or reversal; does not detect every edge crossing or hole contact. Other shape kinds are unchanged.</small>
    <label><input type="checkbox" aria-label="Edit motion path on stage" bind:checked={editMotionOnStage} disabled={!motionPath} />Edit motion path on stage</label>
    <small>While enabled, the stage edits path handles instead of artwork. Arrow keys move handles; Escape cancels a drag. Generate motion to write keys.</small>
    <MotionPathControls groupSource={activeLayer.keys.find(k=>k.frame===rangeStart)?.shapes ?? []} groupTarget={activeLayer.keys.find(k=>k.frame===rangeEnd)?.shapes ?? []} groupRotation={motionRotation} guides={project.layers.filter(l=>l.visible).flatMap(l=>keyAt(l,frame).shapes)} bind:value={motionPath} label="Motion path" start={activeLayer.keys.find(k => k.frame === rangeStart)?.shapes[0]} end={activeLayer.keys.find(k => k.frame === rangeEnd)?.shapes[0]} />
            <label><input type="checkbox" aria-label="Motion interpolate scale and skew" bind:checked={motionAffine} />Interpolate scale and skew</label>
            <label><input type="checkbox" aria-label="Motion opacity weighted gradients" bind:checked={motionGradientPremultiplied} />Weight gradient colors by stop opacity (requires paint interpolation)</label>
    <small>Transparent stops contribute less color, including when matching offsets. Uses encoded RGB; fully transparent pairs keep ordinary hidden colors. Solid colors and object opacity keep their existing interpolation.</small>
    <label><input type="checkbox" aria-label="Motion interpolate paint colors" bind:checked={motionPaint} />Interpolate paint colors</label>
            <small>Paint interpolation blends RGB fill/stroke colors and colors/opacity of matching gradient stops. Gradient geometry stays fixed unless its interpolation is enabled.</small>
            <label><input type="checkbox" aria-label="Motion interpolate gradient geometry" bind:checked={motionGradientGeometry} />Interpolate gradient geometry</label>
            <small>Blends gradient endpoints and corresponding stop offsets. Kind must match; stop count/order must match unless stop matching is enabled. Gradient basis stays fixed unless enabled separately. Coincident endpoints use the existing renderer behavior.</small>
            <label><input type="checkbox" aria-label="Motion match gradient stops" bind:checked={motionGradientStops} />Match gradient stops</label>
            {#if motionGradientStops}<label><input type="checkbox" aria-label="Motion match stop groups in order" bind:checked={motionGradientStopOrder} />Match stop groups in order (requires gradient geometry)</label>{/if}
    <label>Gradient group pairs (optional) <input aria-label="Motion gradient group pairs" bind:value={motionGradientPairs} placeholder="0:0, 0:1, 1:2" /></label>
    <small>With ordered stop matching, pair zero-based source:end groups. Cover every group in order; repeat one side to split or merge groups. Blank pairs equal group counts in order. Enter auto to minimize opacity-weighted color differences plus a small offset-movement cost. Automatic matching is a heuristic; explicit pairs override it.</small>
            <small>Requires paint color interpolation. By default, samples combined fixed offsets. Ordered matching pairs equal counts of distinct stop groups and moves their offsets with gradient geometry. Hard-edge copies repeat to match group sizes. The 32-stop limit applies; original endpoint keys stay exact.</small>
            <label><input type="checkbox" aria-label="Motion interpolate gradient basis" bind:checked={motionGradientBasis} />Interpolate gradient basis</label>
            <small>Blends gradient scale/skew and shortest rotation. Singular bases and reflection changes reject. Gradient endpoints and colors use their separate options.</small>
            <label><input type="checkbox" aria-label="Motion interpolate stroke width" bind:checked={motionStrokeWidth} />Interpolate stroke width</label>
            <label><input type="checkbox" aria-label="Motion interpolate primitive geometry" bind:checked={motionPrimitives} />Interpolate rectangle and ellipse geometry</label>
            <small>Blends width/height and rectangle corner radius. Paint coordinates stay fixed unless separately enabled; contour-backed shapes are unchanged.</small>
            <label><input type="checkbox" aria-label="Motion interpolate curve nodes" bind:checked={motionNodes} />Interpolate matching curve nodes</label>
    <label><input type="checkbox" aria-label="Motion match straight nodes" bind:checked={motionMatchStraightNodes} />Match straight contour nodes</label>
    <label><input type="checkbox" aria-label="Motion match curved nodes" bind:checked={motionMatchCurvedNodes} />Match curved Bezier nodes</label>
    <label><input type="checkbox" aria-label="Motion curved node distance" bind:checked={motionCurveDistance} />Match curved nodes by distance</label>
    <small>Requires curved matching. Uses bounded approximate arc lengths to place subdivisions; exact authored curves remain. Zero-length or unresolved segments reject.</small>
    <small>Choose one matching mode. Curved mode subdivides each original segment at corresponding parameter intervals, preserving its curve. By default, segments receive equal correspondence intervals; enable distance matching to use approximate arc lengths. Interior node pairs also apply. Requires node interpolation; no pressure metadata or topology repair.</small>
    <label><input type="checkbox" aria-label="Edit node hints on stage" bind:checked={editNodeHintsOnStage} />Edit node hints on stage</label>
    <small>Stage picking shows the first artwork at its authored endpoint pose. Choose Source or Target to select anchors; shared hints change only when added. Stage hint mode takes priority over motion-path editing. Disable it to edit artwork.</small>
    <label>Interior node pairs<input aria-label="Motion node hints" bind:value={motionNodeHints} placeholder="1:2, 3:4" /></label>
    <MotionNodeHints source={activeLayer.keys.find(k => k.frame === rangeStart)?.shapes[0]} target={activeLayer.keys.find(k => k.frame === rangeEnd)?.shapes[0]} bind:value={motionNodeHints} straight={motionMatchStraightNodes} curves={motionMatchCurvedNodes} distance={motionCurveDistance} offset={motionContourStart} offsets={motionContourOffsets} reverse={motionContourReverse} directions={motionContourDirections} order={motionContourOrder} label="Motion" />
    <small>Optional zero-based source:target interior anchors in increasing order. Separate contours with semicolons; endpoints are implicit. Hints apply after contour order/start/direction matching.</small>
    <small>Straight matching requires node interpolation and straight Bezier or polygon anchors without handles. Inserts points at both contours' proportional edge distances, retaining corners. Contour count and order must match; authored endpoint keys stay exact.</small>
            <small>Without node matching, Bezier anchors/handles and polygon contours match by order with equal counts and handle presence. Inspect generated fills: crossings and collapsing contours are not repaired.</small>
            <button onclick={() => generateMotion()}>Generate motion in-betweens</button>
            <p>Creates editable keys between matching endpoint artwork. Position, chosen rotation and opacity, with optional scale and skew; intermediate keys reject. Graphic symbol playback continues through generated keys; the end key may have its own playback mode/start frame and stays unchanged. Interiors retain the source playback mode. The exact end key may switch between movie and graphic playback; entering movie playback starts its independent clock. Movie offset-only changes preserve elapsed time. Movie descendants retain independent clocks beneath movie and graphic roots. Button descendants are supported behind a movie boundary, including nested movies under graphic roots. Direct buttons and buttons reached only through graphics reject. Moving poses cancel stale presses while state movies continue. Generated keys are not linked to later endpoint edits.</p>
          </fieldset>
          <fieldset disabled={foregroundBusy || activeLayer.locked}>
            <legend>Remembered basic motion</legend>
            <label><input type="checkbox" bind:checked={autoRefreshRemembered} />Automatically refresh remembered endpoints this session</label>
            <small>After an endpoint edit, refresh affected saved spans in the same undo step. Conflicts keep your edit and all existing interiors; refresh manually after resolving them. This session preference is not saved.</small>
            <p>Creates editable position, shortest-rotation and opacity keys in the selected range, with the optional properties below. These separate controls do not use the motion settings above. After editing an endpoint, refresh manually or enable automatic refresh for this session. Edited interior keys are protected; detach keeps all keys.</p>
            <label><input type="checkbox" aria-label="Saved endpoint refresh" bind:checked={rememberedLive} />Automatically refresh this saved range</label>
<button onclick={() => rememberedMotion('live')}>Apply saved endpoint refresh</button>
<MotionEasing bind:value={rememberedEase} label="Remembered motion easing" />
<label><input type="checkbox" aria-label="Independent remembered opacity easing" bind:checked={rememberedOpacityEnabled}/>Use separate opacity easing for new remembered recipes</label>
{#if rememberedOpacityEnabled}<MotionEasing bind:value={rememberedOpacityEase} label="Remembered opacity easing" />{/if}
<label><input type="checkbox" aria-label="Independent remembered paint easing" bind:checked={rememberedPaintEnabled}/>Use separate paint easing for new remembered recipes</label>
{#if rememberedPaintEnabled}<MotionEasing bind:value={rememberedPaintEase} label="Remembered paint easing" />{/if}
<small>Separate paint easing requires Remember paint colors. It affects fill/stroke and gradient stop colors/opacity; geometry, stop positions and object opacity keep their own easing. This preference only creates new recipes.</small>
<details>
  <summary>Remembered color keys</summary>
  <label>Remembered color property<select bind:value={colorKeyProperty} onchange={()=>existingPaintRevision++}><option value="fill">Solid fill</option><option value="stroke">Stroke</option><option value="gradient">Gradient stop</option></select></label>
  {#if colorKeyProperty==='gradient'}
    <label>Matched gradient stop<input type="number" min="1" max="32" bind:value={gradientKeyStop} oninput={()=>existingPaintRevision++}/></label>
  {/if}
  {#each rememberedColorKeys ?? [] as key}
    <button onclick={()=>{colorKeyFrame=rangeStart+key.offset+1;colorKeyValue=key.color;existingPaintRevision++}}>Frame {rangeStart+key.offset+1} · {colorKeyProperty} {key.color}</button>
  {/each}
  <label>Remembered color key frame<input type="number" min={rangeStart+2} max={rangeEnd} bind:value={colorKeyFrame} oninput={()=>existingPaintRevision++}/></label>
  <label>Remembered key color<input type="color" bind:value={colorKeyValue} oninput={()=>existingPaintRevision++}/></label>
  <button disabled={foregroundBusy} onclick={()=>editRememberedPaint(false,true)}>Set remembered color key</button>
  <button disabled={foregroundBusy} onclick={()=>editRememberedPaint(true,true)}>Remove remembered color key</button>
  {#if rememberedColorSpan && rememberedColorKeys}
    {@const property=colorKeyProperty==='gradient'?gradientKeyStop-1:colorKeyProperty}
    {#key rememberedColorSpan}
      {#key property}
        <RememberedPositionTiming span={rememberedColorSpan} axis={property} disabled={foregroundBusy}
          onchange={()=>existingPaintRevision++} onapply={(frame,ease)=>editRememberedPaint(false,false,{property,frame,ease})}/>
      {/key}
    {/key}
  {/if}
</details>
<p aria-label="Saved remembered paint easing">{savedPaintSummary}</p>
<MotionEasing bind:value={()=>existingPaintEase,(value)=>{existingPaintRevision++;existingPaintEase=value;}} label="Existing paint easing" />
<button onclick={()=>editRememberedPaint()}>Apply paint easing to remembered motion</button>
<button onclick={()=>editRememberedPaint(true)}>Remove remembered paint override</button>
<small>Apply/Remove edits only the saved paint channel. Saved paint interpolation is required; creation preferences stay separate.</small>
<p aria-label="Saved remembered opacity easing">{savedOpacitySummary}</p>
<MotionEasing bind:value={()=>existingOpacityEase,(value)=>{existingOpacityRevision++;existingOpacityEase=value;}} label="Existing opacity easing" />
<details>
  <summary>Remembered position keys</summary>
  <label>Remembered position axis<select bind:value={positionKeyAxis} onchange={()=>existingOpacityRevision++}><option value="x">X</option><option value="y">Y</option></select></label>
  {#each project.layers.find(l=>l.id===layerId)?.motionSpans?.find(s=>s.start===rangeStart && s.end===rangeEnd)?.[positionKeyAxis==='x'?'xKeys':'yKeys'] ?? [] as key}
    <button onclick={()=>{positionKeyFrame=rangeStart+key.offset+1;positionKeyValue=key.value;existingOpacityRevision++}}>Frame {rangeStart+key.offset+1} · {positionKeyAxis.toUpperCase()} {key.value}</button>
  {/each}
  <label>Remembered position key frame<input type="number" min={rangeStart+2} max={rangeEnd} bind:value={positionKeyFrame} oninput={()=>existingOpacityRevision++}/></label>
  <label>Document coordinate<input type="number" step="any" bind:value={positionKeyValue} oninput={()=>existingOpacityRevision++}/></label>
  <button disabled={foregroundBusy} onclick={()=>editRememberedChannel(false,'position')}>Set remembered position key</button>
  <button disabled={foregroundBusy} onclick={()=>editRememberedChannel(true,'position')}>Remove remembered position key</button>
  {#if rememberedColorSpan?.[positionKeyAxis==='x'?'xKeys':'yKeys']}
    {#key rememberedColorSpan}
    {#key positionKeyAxis}
      <RememberedPositionTiming span={rememberedColorSpan} axis={positionKeyAxis} disabled={foregroundBusy}
        onchange={()=>existingOpacityRevision++} onapply={(frame,ease)=>editRememberedChannel(false,'timing',{property:positionKeyAxis,frame,ease})}/>
    {/key}
    {/key}
  {/if}
</details>
<details>
  <summary>Remembered scale keys</summary>
  <label>Remembered scale axis<select bind:value={scaleKeyAxis} onchange={()=>existingOpacityRevision++}><option value="x">X</option><option value="y">Y</option></select></label>
  {#each project.layers.find(l=>l.id===layerId)?.motionSpans?.find(s=>s.start===rangeStart && s.end===rangeEnd)?.[scaleKeyAxis==='x'?'scaleXKeys':'scaleYKeys'] ?? [] as key}
    <button onclick={()=>{scaleKeyFrame=rangeStart+key.offset+1;scaleKeyValue=key.value;existingOpacityRevision++}}>Frame {rangeStart+key.offset+1} · {scaleKeyAxis.toUpperCase()} {key.value}</button>
  {/each}
  <label>Remembered scale key frame<input type="number" min={rangeStart+2} max={rangeEnd} bind:value={scaleKeyFrame} oninput={()=>existingOpacityRevision++}/></label>
  <label>Scale factor<input type="number" step="any" bind:value={scaleKeyValue} oninput={()=>existingOpacityRevision++}/></label>
  <button disabled={foregroundBusy} onclick={()=>editRememberedChannel(false,'scale')}>Set remembered scale key</button>
  <button disabled={foregroundBusy} onclick={()=>editRememberedChannel(true,'scale')}>Remove remembered scale key</button>
  {#if rememberedColorSpan?.[scaleKeyAxis==='x'?'scaleXKeys':'scaleYKeys']}
    {@const axis=scaleKeyAxis==='x'?'sx':'sy'}
    {#key rememberedColorSpan}{#key axis}
      <RememberedPositionTiming span={rememberedColorSpan} {axis} disabled={foregroundBusy}
        onchange={()=>existingOpacityRevision++} onapply={(frame,ease)=>editRememberedChannel(false,'timing',{property:axis,frame,ease})}/>
    {/key}{/key}
  {/if}
</details>
<details>
  <summary>Remembered rotation and shear keys</summary>
  <label>Remembered transform property<select bind:value={transformProperty} onchange={()=>existingOpacityRevision++}><option value="rotation">Rotation</option><option value="shear">Shear</option></select></label>
  {#each project.layers.find(l=>l.id===layerId)?.motionSpans?.find(s=>s.start===rangeStart && s.end===rangeEnd)?.[transformProperty==='rotation'?'rotationKeys':'shearKeys'] ?? [] as key}
    <button onclick={()=>{transformKeyFrame=rangeStart+key.offset+1;transformKeyValue=key.value;existingOpacityRevision++}}>Frame {rangeStart+key.offset+1} · {transformProperty} {key.value}</button>
  {/each}
  <label>Remembered transform key frame<input type="number" min={rangeStart+2} max={rangeEnd} bind:value={transformKeyFrame} oninput={()=>existingOpacityRevision++}/></label>
  <label>{transformProperty==='rotation'?'Rotation (degrees)':'Shear factor'}<input type="number" step="any" bind:value={transformKeyValue} oninput={()=>existingOpacityRevision++}/></label>
  <button disabled={foregroundBusy} onclick={()=>editRememberedChannel(false,'transform')}>Set remembered transform key</button>
  <button disabled={foregroundBusy} onclick={()=>editRememberedChannel(true,'transform')}>Remove remembered transform key</button>
  {#if rememberedColorSpan?.[transformProperty==='rotation'?'rotationKeys':'shearKeys']}
    {#key rememberedColorSpan}{#key transformProperty}
      <RememberedPositionTiming span={rememberedColorSpan} axis={transformProperty} disabled={foregroundBusy}
        onchange={()=>existingOpacityRevision++} onapply={(frame,ease)=>editRememberedChannel(false,'timing',{property:transformProperty,frame,ease})}/>
    {/key}{/key}
  {/if}
</details>
<details>
  <summary>Remembered opacity keys</summary>
  {#each project.layers.find(l=>l.id===layerId)?.motionSpans?.find(s=>s.start===rangeStart && s.end===rangeEnd)?.opacityKeys ?? [] as key}
    <button onclick={()=>{opacityKeyFrame=rangeStart+key.offset+1;opacityKeyPercent=key.value*100;existingOpacityRevision++}}>Frame {rangeStart+key.offset+1} · {key.value*100}%</button>
  {/each}
  <label>Remembered opacity key frame<input type="number" min={rangeStart+2} max={rangeEnd} bind:value={opacityKeyFrame} oninput={()=>existingOpacityRevision++}/></label>
  <label>Remembered key opacity (%)<input type="number" step="any" min="0" max="100" bind:value={opacityKeyPercent} oninput={()=>existingOpacityRevision++}/></label>
  <button disabled={foregroundBusy} onclick={()=>editRememberedChannel(false,'opacity')}>Set remembered opacity key</button>
  <button disabled={foregroundBusy} onclick={()=>editRememberedChannel(true,'opacity')}>Remove remembered opacity key</button>
  {#if rememberedColorSpan?.opacityKeys}
    {#key rememberedColorSpan}
      <RememberedPositionTiming span={rememberedColorSpan} axis="opacity" disabled={foregroundBusy}
        onchange={()=>existingOpacityRevision++} onapply={(frame,ease)=>editRememberedChannel(false,'timing',{property:'opacity',frame,ease})}/>
    {/key}
  {/if}
</details>
<button disabled={foregroundBusy||rememberedBatch&&!selectedBatchLayers.length} onclick={()=>editRememberedChannel()}>Apply opacity easing to remembered motion</button>
<button disabled={foregroundBusy||rememberedBatch&&!selectedBatchLayers.length} onclick={()=>editRememberedChannel(true)}>Remove remembered opacity override</button>
<small>Apply changes the selected saved opacity curves. Remove makes opacity inherit each recipe's global easing. New-recipe preferences above do not edit saved curves.</small>
            <label><input type="checkbox" aria-label="Remember current contour correspondence" bind:checked={rememberedCorrespondence} />Capture current contour alignment, node hints and resampling</label>
<label><input type="checkbox" aria-label="Remember current rotation and groups" bind:checked={rememberedRotation} />Remember current rotation and groups</label>
<label><input type="checkbox" aria-label="Remember current motion path" bind:checked={rememberedPath} />Remember current motion path</label>
<label><input type="checkbox" aria-label="Remembered motion saved pivots" bind:checked={rememberedOptions.pivots}/>Interpolate saved pivots</label>
<label><input type="checkbox" aria-label="Remembered motion default pivots" bind:checked={rememberedOptions.defaultPivots}/>Resolve missing pivots from authoring-box defaults (requires pivot interpolation)</label>
<label><input type="checkbox" aria-label="Remembered motion scale and skew" bind:checked={rememberedOptions.affine} />Remember scale and skew</label>
<label><input type="checkbox" aria-label="Remembered motion paint colors" bind:checked={rememberedOptions.paint} />Remember paint colors</label>
<label><input type="checkbox" aria-label="Remembered motion matching nodes" bind:checked={rememberedOptions.nodes} />Remember matching nodes</label>
<label><input type="checkbox" aria-label="Remembered motion primitive geometry" bind:checked={rememberedOptions.primitives} />Remember primitive geometry</label>
<label><input type="checkbox" aria-label="Remembered motion stroke color" bind:checked={rememberedOptions.strokeColor}/>Animate stroke color with geometry timing</label>
<label><input type="checkbox" aria-label="Remembered motion stroke width" bind:checked={rememberedOptions.strokeWidth} />Remember stroke width</label>
<label><input type="checkbox" aria-label="Remembered motion gradient geometry" bind:checked={rememberedOptions.gradientGeometry} />Remember gradient geometry</label>
<label><input type="checkbox" aria-label="Remembered motion gradient basis" bind:checked={rememberedOptions.gradientBasis} />Remember gradient basis</label>
<label><input type="checkbox" aria-label="Remembered motion reject area collapse" bind:checked={rememberedOptions.contourAreas} />reject area collapse</label>
<label><input type="checkbox" aria-label="Remembered motion reject segment collapse" bind:checked={rememberedOptions.contourEdges} />reject segment collapse</label>
<label><input type="checkbox" aria-label="Remembered motion reject segment contacts" bind:checked={rememberedOptions.contourContacts} />reject segment contacts</label>
<label><input type="checkbox" aria-label="Remembered motion reject stationary or reversing tangents" bind:checked={rememberedOptions.curveTangents} />reject stationary or reversing tangents</label>
<label><input type="checkbox" aria-label="Remembered motion reject single-curve self contacts" bind:checked={rememberedOptions.curveSelfContacts} />reject single-curve self contacts</label>
<label><input type="checkbox" aria-label="Remembered motion resample gradient stops" bind:checked={rememberedOptions.gradientStops} />Resample gradient stops (requires paint)</label>
<label><input type="checkbox" aria-label="Remembered motion ordered gradient stops" bind:checked={rememberedGradientOrder} />Match stop groups in order (requires gradient geometry)</label>
<label>Gradient group pairs <input aria-label="Remembered motion gradient group pairs" bind:value={rememberedGradientPairs} placeholder="0:0, 1:1 or auto" /></label>
<label><input type="checkbox" aria-label="Remembered motion opacity-weighted gradient colors" bind:checked={rememberedOptions.gradientPremultiplied} />Opacity-weighted gradient colors (requires paint)</label>
<small>Saved guards require matching nodes. They reject unsafe or unresolved interpolation using the existing bounded checks; they do not certify full topology.</small>
<small>These options apply to new recipes. Refresh and retime use saved options. Nodes require matching topology; paths, group motion, matching hints, custom easing and topology guards are not stored by these controls.</small>
<label><input type="checkbox" bind:checked={rememberedBatch} />Remembered motion on checked layers</label>
            <button disabled={rememberedBatch && !selectedBatchLayers.length} onclick={() => rememberedMotion('create')}>Create remembered motion</button>
            <button disabled={rememberedBatch && !selectedBatchLayers.length} onclick={() => rememberedMotion('refresh')}>Refresh remembered motion</button>
<button disabled={rememberedBatch && !selectedBatchLayers.length} onclick={() => rememberedMotion('ease')}>Apply easing to remembered motion</button>
<button disabled={rememberedBatch && !selectedBatchLayers.length} title="Use the current rotation direction and extra turns. Keep each track’s saved group and pivot settings." onclick={()=>rememberedMotion('spin')}>Apply direction and turns to remembered motion</button>
<button disabled={!activeSavedPath} onclick={()=>{if(activeSavedPath)motionPath=clone(activeSavedPath)}}>Load active track’s saved path</button>
<button disabled={!motionPath || (rememberedBatch && !selectedBatchLayers.length)} onclick={()=>rememberedMotion('path')}>Apply path to remembered motion</button>
<button disabled={rememberedBatch && !selectedBatchLayers.length} onclick={()=>rememberedMotion('clearPath')}>Remove path from remembered motion</button>
            <button disabled={foregroundBusy || (rememberedBatch && !selectedBatchLayers.length)} onclick={()=>openRememberedPreview()}>Preview remembered motion…</button>
            <button disabled={rememberedBatch && !selectedBatchLayers.length} onclick={() => rememberedMotion('detach')}>Detach remembered motion</button>
            <label><input type="checkbox" bind:checked={rememberedRipple} />Shift following keys and remembered spans</label>
<label>New span or chain frame count<input type="number" min="3" step="1" aria-label="Remembered motion frame count" bind:value={rememberedLength} /></label>
            <button onclick={() => rememberedMotion('retime')}>Retime remembered motion</button>
<label>Per-span frame counts<input aria-label="Remembered motion per-span frame counts" bind:value={rememberedSpanLengths} placeholder="5, 9" /></label>
<small>Optional counts override the total above, in span order. Shared endpoints count once. Leave blank for proportional retiming.</small>
<label>Destination track<select aria-label="Remembered motion destination track" bind:value={rememberedDestinationLayer}><option value="">Same track(s)</option>{#each project.layers as target (target.id)}<option value={target.id}>{target.name}</option>{/each}</select></label>
<label>Move span or connected chain to frame<input type="number" min="1" step="1" aria-label="Remembered motion destination frame" bind:value={rememberedDestination} /></label>
<button onclick={() => rememberedMotion('move')}>Move remembered motion</button>
<button onclick={() => rememberedMotion('exchange')}>Exchange remembered motion</button>
<small>Exchange requires equal-length complete remembered chains. Same track(s) can exchange checked tracks together; all must validate before any change. A cross-track exchange requires one source track. On the same track, ranges must not overlap or share endpoints. Across tracks, both must be visible, unlocked and use the same drawing mode. Conflicting identities and edited interiors reject the whole exchange.</small>
<label>Promote interior frame<input type="number" min="1" step="1" aria-label="Remembered motion split frame" bind:value={rememberedSplit} /></label>
<label><input type="checkbox" aria-label="Preserve simple motion when splitting" bind:checked={preserveRememberedSplit} />Preserve simple trajectory when splitting (including supported paths)</label>
<button onclick={() => rememberedMotion('split')}>Split and regenerate remembered motion</button>
<button title="Use the current endpoint poses, then split without changing the refreshed motion. All generated keys must be unedited." onclick={()=>rememberedMotion('promote')}>Refresh and promote pose in remembered motion</button>
<label>Preserved cut frames<input aria-label="Remembered motion cut frames" bind:value={rememberedCuts} placeholder="5, 9, 13" /></label>
<button disabled={rememberedBatch && !selectedBatchLayers.length} onclick={() => rememberedMotion('subdivide')}>Subdivide remembered motion</button>
<small>Enter increasing document frame numbers, separated by commas. Each section needs at least three frames including its shared endpoints. All cuts preserve supported trajectories and apply together; unsupported or numerically unresolved cuts reject the whole operation.</small>
<button onclick={() => rememberedMotion('reverse')}>Reverse remembered motion</button>
<small>Reverse an isolated complete chain of unchanged recipes and its exact keys, deriving easing and frozen path controls. Outside holds remain. Groups support uniform or independent-axis scaling/shear; custom/saved pivots support paths and custom pivots need a shared transformed offset. Node matching reverses explicit hint pairs. Tangent rotation can reverse on single cubics and straight waypoint paths with equal-time or distance timing. At a waypoint corner, the outgoing segment controls rotation. Reversal rejects a corner frame if its pose would change. Refresh the span if its stored keys no longer regenerate exactly. Reversal checks every generated pose.</small>
<small>Preserve mode keeps all existing keys and derives easing for each half. Requires unchanged position/rotation/opacity motion, optionally with exactly reconstructable fill/stroke/gradient colors (including opacity-weighted blending and fixed-offset, ordered or explicit moving-stop matching) and stop opacity, primitive dimensions/corner radius, stroke width, matching contour nodes/handles, gradient endpoints/stop positions, and individual artwork/gradient scale and skew, with Linear, Ease in, Ease out, midpoint Ease in-out, or custom cubic easing with representable subdivided controls. Numerically unresolved subdivisions and changed rounded paint colors reject. Supported paths: a parameter-timed cubic, a single or waypoint distance-timed cubic route whose rebuilt distance tables reconstruct every pose, distance-timed straight waypoints, or equal-time straight/curved waypoints at existing boundaries or exactly resolved uniform subdivisions (up to 32 parts per segment and 256 total). Path leaders and ungrouped artwork must share endpoint displacement. Directed extra turns support individual affine bases and require shared turn counts per half. Explicit gradient pairs are remapped through distinct split groups; automatic matching freezes shared resolved pairs for both halves. Rigid groups support leader-pivot rotation/translation and uniform positive scaling with supported paths. Independent-axis scaling/rotation derives right-half shear in the split basis. Saved or custom pivots support pathless, parameter-cubic or equal-time waypoint group motion; pivot paths require shared leader correction; custom pivots must share one transformed offset across groups. Contour order/start/direction stays on the right half only. Symbol playback phases must reconstruct exactly. Straight, parameter-based or distance-based curve matching is retained on both halves when node partitions reconstruct exactly. Explicit hints remap through shared expanded anchor indices. Single tangent cubics and straight waypoint routes can split at nonzero headings when both halves reproduce the stored rotation. At corner cuts the promoted key keeps the outgoing heading. Equal-time curved waypoint tangent routes also support nonzero headings at existing or exactly representable uniform subdivision boundaries; distance-timed curved tangent routes can split at nonzero headings when both rebuilt tables reproduce every pose. Distance pivot paths require exactly zero leader correction and full reconstruction.</small>
<small>With preserve mode off, promotes this key to a shared endpoint and reapplies saved easing, path, rotation and correspondence separately to each half. This can change the trajectory and repeat extra turns. Only the split key may have edits; each half needs at least three frames.</small>
            <small>Moves the target key and regenerates interiors. By default, other keys stay fixed and collisions reject. With shifting enabled, following keys and saved spans move by the duration change; edited following interiors reject. Timeline duration stays fixed, so overflow rejects.</small>
            <p>Refresh and detach use the exact selected range on every chosen layer. Refresh uses each saved easing. Recipes are saved with the project; automatic refresh is off by default.</p>
            {#each activeLayer.motionSpans ?? [] as span (span.id)}
              <button onclick={() => { frameAnchor = span.start; frameAnchorLayer = layerId; frame = span.end; playing = false; selected = []; }}>Select remembered frames {span.start + 1}–{span.end + 1}</button>
              <small>{typeof span.ease === 'string' ? span.ease : 'Custom cubic'}{span.autoRefresh ? ' · automatic' : ''}: {JSON.stringify(activeLayer.keys.filter(k => k.frame > span.start && k.frame < span.end)) === span.baseline ? 'Generated keys unchanged' : 'Generated keys changed — detach to preserve edits'}</small>
            {/each}
          </fieldset>
          <label
            >Retimed range length<input
              aria-label="Retimed range length"
              type="number"
              min="1"
              max="100000"
              bind:value={retimeLength}
            /></label
          >
          <button disabled={foregroundBusy || activeLayer.locked} onclick={() => retimeRange()}
            >Retime frame range</button
          >
          <p class="hint">
            Scales exposure lengths and shifts following keys on the edited tracks. Compression
            leaves a blank tail and rejects collapsed keys. Other tracks keep their timing.
          </p>
          <details>
            <summary>Multi-layer frame edits</summary>
            <p>{selectedBatchLayers.length} layers selected for batch edits</p>
            <button onclick={() => selectBatchLayers(project.layers.map((l) => l.id))}
              >Select all timeline layers</button
            >
            <button
              disabled={!selectedFolder}
              onclick={() =>
                selectBatchLayers(folderMembers(project, selectedFolder).map((l) => l.id))}
              >Select folder timeline layers</button
            >
            <button onclick={() => selectBatchLayers([])}>Clear timeline layer selection</button>
            {#each project.layers as layer (layer.id)}
              <label
                ><input
                  type="checkbox"
                  checked={selectedBatchLayers.includes(layer.id)}
                  onchange={(e) =>
                    selectBatchLayers(
                      e.currentTarget.checked
                        ? [...selectedBatchLayers, layer.id]
                        : selectedBatchLayers.filter((id) => id !== layer.id),
                    )}
                />
                Batch layer {layer.name}{layer.locked ? ' (locked)' : ''}</label
              >
            {/each}
            <p class="hint">
              Uses the frame range above. Locked layers reject the whole batch. Remove closes the
              gap on selected layers. Clear keeps frame positions. Clipboard and dragging use the
              active layer.
            </p>
            <button
              disabled={foregroundBusy || !selectedBatchLayers.length}
              onclick={() => batchRangeEdit('duplicate')}
              >Duplicate frames on selected layers</button
            >
            <button
              disabled={foregroundBusy || !selectedBatchLayers.length}
              onclick={() => batchRangeEdit('reverse')}>Reverse frames on selected layers</button
            >
            <button disabled={foregroundBusy || !selectedBatchLayers.length} onclick={() => batchRangeEdit('keys')}>Key every frame on selected layers</button>
            <button disabled={foregroundBusy || !selectedBatchLayers.length} onclick={() => generateMotion(true)}>Generate motion on selected layers</button>
            <button disabled={foregroundBusy || !selectedBatchLayers.length} onclick={() => retimeRange(true)}
              >Retime frames on selected layers</button
            >
            <button
              disabled={foregroundBusy || !selectedBatchLayers.length}
              onclick={() => batchRangeEdit('remove')}>Remove frames on selected layers</button
            >
            <button
              disabled={foregroundBusy || !selectedBatchLayers.length}
              onclick={() => batchRangeEdit('clear')}>Clear frames on selected layers</button
            >
            <button disabled={foregroundBusy || !selectedBatchLayers.length} onclick={() => copyBatch()}
              >Copy selected layer frames</button
            >
            <button disabled={foregroundBusy || !selectedBatchLayers.length} onclick={() => copyBatch(true)}
              >Cut selected layer frames</button
            >
            <label
              ><input type="checkbox" bind:checked={dragBatchFrames} />Drag selected layer ranges
              together</label
            >
            {#if timelineDrag && dragBatchFrames}<p>
                {timelineDrag.layers.length} layers in drag
              </p>{/if}
            <label
              >Batch destination frame<input
                aria-label="Batch destination frame"
                type="number"
                min="1"
                max="100000"
                bind:value={batchDestination}
              /></label
            >
            <button
              disabled={foregroundBusy || !batchClipboard || batchClipboard.projectId !== project.id}
              onclick={pasteBatch}>Insert multi-layer clipboard</button
            >
            <button disabled={foregroundBusy || !selectedBatchLayers.length} onclick={moveBatch}
              >Move selected layer frames</button
            >
            <p class="hint">
              Batch clipboard inserts on its original layers. Moves require blank destinations or
              overlap with the source range. Each batch is one undo step.
            </p>
          </details>
          <details>
            <summary>Transfer frames between layers</summary>
            <p>Source: {activeLayer.name} · frames {rangeStart + 1}–{rangeEnd + 1}</p>
            <label
              >Destination layer<select
                aria-label="Frame transfer destination layer"
                bind:value={transferTarget}
              >
                <option value="">Choose a layer</option>
                {#each project.layers.filter((l) => l.id !== layerId) as layer (layer.id)}<option
                    value={layer.id}>{layer.name}{layer.locked ? ' (locked)' : ''}</option
                  >{/each}
              </select></label
            >
            <label
              >Destination frame<input
                aria-label="Frame transfer destination frame"
                type="number"
                min="1"
                max="100000"
                bind:value={batchDestination}
              /></label
            >
            <p class="hint">
              Copies or moves the active layer range onto blank frames in a layer with the same
              drawing mode. Existing timing is retained.
            </p>
            <button disabled={foregroundBusy || !transferTarget} onclick={() => transferRange('copy')}
              >Copy range to layer</button
            >
            <button disabled={foregroundBusy || !transferTarget} onclick={() => transferRange('copy-with-opacity')}>Copy range with opacity animation</button>
            <button disabled={foregroundBusy || !transferTarget} onclick={() => transferRange('move')}
              >Move range to layer</button
            >
            <button disabled={foregroundBusy || !transferTarget} onclick={() => transferRange('move-with-opacity')}>Move range with opacity animation</button>
          </details>
          <details>
            <summary>Map multiple frame tracks</summary>
            <p>
              Choose source tracks in Multi-layer frame edits, then assign a unique destination to
              each.
            </p>
            {#each selectedBatchLayers as sourceId (sourceId)}
              {@const source = project.layers.find((l) => l.id === sourceId)}
              <label
                >{source?.name ?? 'Missing source'} →
                <select
                  aria-label={`Destination for ${source?.name ?? sourceId}`}
                  value={mappingProject === project.id ? (trackDestinations[sourceId] ?? '') : ''}
                  onchange={(e) => mapTrack(sourceId, e.currentTarget.value)}
                >
                  <option value="">Choose destination</option>
                  {#each project.layers.filter((l) => l.id !== sourceId) as target (target.id)}<option
                      value={target.id}>{target.name}{target.locked ? ' (locked)' : ''}</option
                    >{/each}
                </select>
              </label>
            {/each}
            <label
              >Destination frame<input
                aria-label="Mapped tracks destination frame"
                type="number"
                min="1"
                max="100000"
                bind:value={batchDestination}
              /></label
            >
            <p class="hint">
              Destinations must be distinct, blank, unlocked and use matching drawing modes. The
              whole transfer is one undo step. Swap instead permutes the selected tracks at the
              source range, exchanging occupied artwork without changing duration.
            </p>
            <button
              disabled={foregroundBusy || !selectedBatchLayers.length}
              onclick={() => transferTracks('copy')}>Copy mapped frame tracks</button
            >
            <button
              disabled={foregroundBusy || !selectedBatchLayers.length}
              onclick={() => transferTracks('copy-with-opacity')}>Copy mapped tracks with opacity animation</button>
            <button
              disabled={foregroundBusy || !selectedBatchLayers.length}
              onclick={() => transferTracks('move')}>Move mapped frame tracks</button
            >
            <button disabled={foregroundBusy || !selectedBatchLayers.length} onclick={() => transferTracks('move-with-opacity')}>Move mapped tracks with opacity animation</button>
            <button
              disabled={foregroundBusy || selectedBatchLayers.length < 2}
              onclick={() => transferTracks('swap')}>Swap mapped frame tracks</button
            >
          </details>
          <button onclick={() => goToKey(-1)}>Previous keyframe</button>
          <button onclick={() => goToKey(1)}>Next keyframe</button>
        </DockPanel>
      {/if}

      {#if independentCurveResult}<output aria-label="Updated independent route">Independent route {independentCurveResult.groupId} / {independentCurveResult.role} · {independentCurveResult.members} artwork members</output>{/if}
      {#if liveCurveConfig}<DockPanel id="live" heading="TWEEN CONTROLS">{#key liveCurveConfig.id}{#if liveCurveConfig.mode==='groupWaypointTangent'}<LiveGroupWaypointTangentEditor {...liveCurveConfig} {canvas} view={()=>({origin:{...origin},zoom,width:viewWidth,height:viewHeight})} close={()=>liveCurveConfig=undefined} connect={hooks=>{liveCurveHooks=hooks;liveCurvePaintRevision++;}} invalidate={()=>{liveCurvePaintRevision++;}} />{:else if liveCurveConfig.mode==='waypointTangent'}<LiveWaypointTangentEditor {...liveCurveConfig} {canvas} view={()=>({origin:{...origin},zoom,width:viewWidth,height:viewHeight})} close={()=>liveCurveConfig=undefined} connect={hooks=>{liveCurveHooks=hooks;liveCurvePaintRevision++;}} invalidate={()=>{liveCurvePaintRevision++;}} />{:else if liveCurveConfig.mode==='treeWaypoint'}<LiveMovieTreeWaypointEditor {...liveCurveConfig} {canvas} view={()=>({origin:{...origin},zoom,width:viewWidth,height:viewHeight})} close={()=>liveCurveConfig=undefined} connect={hooks=>{liveCurveHooks=hooks;liveCurvePaintRevision++;}} invalidate={()=>{liveCurvePaintRevision++;}} />{:else if liveCurveConfig.mode==='groupWaypoint'}<LiveGroupWaypointEditor {...liveCurveConfig} {canvas} view={()=>({origin:{...origin},zoom,width:viewWidth,height:viewHeight})} close={()=>liveCurveConfig=undefined} connect={hooks=>{liveCurveHooks=hooks;liveCurvePaintRevision++;}} invalidate={()=>{liveCurvePaintRevision++;}} />{:else if liveCurveConfig.mode==='waypoint'}<LiveWaypointEditor {...liveCurveConfig} {canvas} view={()=>({origin:{...origin},zoom,width:viewWidth,height:viewHeight})} close={()=>liveCurveConfig=undefined} connect={hooks=>{liveCurveHooks=hooks;liveCurvePaintRevision++;}} invalidate={()=>{liveCurvePaintRevision++;}} />{:else if liveCurveConfig.mode==='tree'}<LiveMovieTreeCubicEditor {...liveCurveConfig} {canvas} view={()=>({origin:{...origin},zoom,width:viewWidth,height:viewHeight})} close={()=>liveCurveConfig=undefined} connect={hooks=>{liveCurveHooks=hooks;liveCurvePaintRevision++;}} invalidate={()=>{liveCurvePaintRevision++;}} />{:else if liveCurveConfig.mode==='independentGroup'}<LiveGroupCubicEditor {...liveCurveConfig} independent={true} {canvas} view={()=>({origin:{...origin},zoom,width:viewWidth,height:viewHeight})} close={()=>liveCurveConfig=undefined} connect={hooks=>{liveCurveHooks=hooks;liveCurvePaintRevision++;}} invalidate={()=>{liveCurvePaintRevision++;}} />{:else if liveCurveConfig.mode==='group'}<LiveGroupCubicEditor {...liveCurveConfig} {canvas} view={()=>({origin:{...origin},zoom,width:viewWidth,height:viewHeight})} close={()=>liveCurveConfig=undefined} connect={hooks=>{liveCurveHooks=hooks;liveCurvePaintRevision++;}} invalidate={()=>{liveCurvePaintRevision++;}} />{:else}<LiveCubicEditor {...liveCurveConfig} {canvas} view={()=>({origin:{...origin},zoom,width:viewWidth,height:viewHeight})} close={()=>liveCurveConfig=undefined} connect={hooks=>{liveCurveHooks=hooks;liveCurvePaintRevision++;}} invalidate={()=>{liveCurvePaintRevision++;}} />{/if}{/key}</DockPanel>{/if}
      <div inert={liveInputBlocked()||!!liveCurveConfig}>
      {#if bonePair.length}
        {#key [layerId, frame, ...selected].join(':')}
          <TwoBoneControls pair={bonePair} disabled={busy || activeLayer.locked || !activeLayer.visible || playing}
            apply={editBonePair} />
        {/key}
      {/if}
      {#if canTransformSelection && selectionBounds}
        <DockPanel id="transform" heading="TRANSFORM" blocked={liveInputBlocked()||!!liveCurveConfig}>
          <p class="hint">
            Bounds {Math.round(selectionBounds.right - selectionBounds.left)} × {Math.round(
              selectionBounds.bottom - selectionBounds.top,
            )}. Drag outside a corner to rotate and between handles to skew. Shift uses the View angle increment or scales proportionally. Alt switches the transform origin.
          </p>
          <label>Mode<select aria-label="Selection transform mode" value={selectionTransformMode} onchange={e=>chooseSelectionTransformMode(e.currentTarget.value as TransformMode)}><option value="free">Free transform</option><option value="rotate-skew">Rotate and skew</option></select></label>
          <div class="property-grid">
            <label
              >Scale X %<input
                aria-label="Transform scale X"
                type="number"
                bind:value={transformX}
              /></label
            >
            <label
              >Scale Y %<input
                aria-label="Transform scale Y"
                type="number"
                bind:value={transformY}
              /></label
            >
            <label
              >Rotate °<input
                aria-label="Transform rotation"
                type="number"
                bind:value={transformAngle}
              /></label
            >
            <label
              >Skew X °<input
                aria-label="Transform skew X"
                type="number"
                min="-85"
                max="85"
                bind:value={skewX}
              /></label
            >
            <label
              >Skew Y °<input
                aria-label="Transform skew Y"
                type="number"
                min="-85"
                max="85"
                bind:value={skewY}
              /></label
            >
          </div>
          <button disabled={activeLayer.locked} onclick={applyTransform}>Apply transform</button>
          <button
            disabled={activeLayer.locked}
            onclick={() =>
              transformSelection(around(selectionPivot, -1, 0, 0, 1), 'Flip horizontal')}
            >Flip horizontal</button
          >
          <button
            disabled={activeLayer.locked}
            onclick={() => transformSelection(around(selectionPivot, 1, 0, 0, -1), 'Flip vertical')}
            >Flip vertical</button
          >
          <details>
            <summary>Transform pivot</summary>
            <div class="property-grid">
              <label
                >X<input
                  aria-label="Pivot X"
                  type="number"
                  value={Math.round(selectionPivot.x * 100) / 100}
                  disabled={activeLayer.locked}
                  onchange={(e) =>
                    setPivot({ x: Number(e.currentTarget.value), y: selectionPivot.y })}
                /></label
              >
              <label
                >Y<input
                  aria-label="Pivot Y"
                  type="number"
                  value={Math.round(selectionPivot.y * 100) / 100}
                  disabled={activeLayer.locked}
                  onchange={(e) =>
                    setPivot({ x: selectionPivot.x, y: Number(e.currentTarget.value) })}
                /></label
              >
            </div>
            <button disabled={activeLayer.locked} onclick={() => setPivot()}
              >Reset pivot to center</button
            >
          </details>
        </DockPanel>
      {/if}
      {#if groupedSelection}<DockPanel id="group" heading="GROUP SELECTION" blocked={liveInputBlocked()||!!liveCurveConfig}>
        {#if blurGroup}
          <TintControls label="Group" tint={blurGroup.members[0].groupBlur?.tint} disabled={activeLayer.locked} scope={inspectorPropertyScope} onchange={patch=>{
            const target=blurGroup;
            if(!target||activeLayer.locked)return;
            edit('Change group tint',()=>{
              for(const member of target.members){
                const effect=member.groupBlur??{group:target.group,radius:0};
                if(patch)member.groupBlur={...effect,tint:{color:'#ffffff',amount:0,...effect.tint,...patch}};
                else if(effect.radius||effect.blendMode)delete effect.tint;
                else delete member.groupBlur;
              }
            },true);
          }}/>
          <label class="property-line">Blend<select aria-label="Group blend mode" value={blurGroup.members[0].groupBlur?.blendMode??'normal'} disabled={activeLayer.locked} onchange={e=>{
            const target=blurGroup, mode=e.currentTarget.value;
            if(!target || activeLayer.locked || (mode!=='normal' && !isBlendMode(mode)))return;
            edit('Change group blend mode',()=>{
              for(const member of target.members){
                const radius=member.groupBlur?.radius??0;
                if(mode!=='normal')member.groupBlur={...member.groupBlur,group:target.group,radius,blendMode:mode};
                else if(member.groupBlur && (radius||member.groupBlur.tint))delete member.groupBlur.blendMode;
                else delete member.groupBlur;
              }
            },true);
          }}><option value="normal">Normal</option>{#each blendModes as [value, label] (value)}<option {value}>{label}</option>{/each}</select></label>
          <NumberSlider label="Group blur radius" caption="Group blur (px)" min={0} max={32}
            value={blurGroup.members[0].groupBlur?.radius??0} disabled={activeLayer.locked} scope={inspectorPropertyScope}
            onchange={value=>{
              const target=blurGroup;
              if(!target || activeLayer.locked || !Number.isInteger(value) || value<0 || value>32)return;
              edit('Change group blur',()=>{
                for(const member of target.members){
                  if(value || member.groupBlur?.blendMode || member.groupBlur?.tint)member.groupBlur={...member.groupBlur,group:target.group,radius:value};
                  else delete member.groupBlur;
                }
              },true);
            }}/>
        {/if}
          <p>{selected.length} vectors selected. Drag or use arrow keys to move together.</p>
          <button onclick={enterGroup} disabled={activeLayer.locked}>Edit group</button>
          <button onclick={() => groupSelection(true)} disabled={activeLayer.locked}>Ungroup</button
          >
          <p class="hint">
            Double-click to edit members. Escape exits one level. Selection handles transform the
            whole group; the crosshair controls its pivot.
          </p>
        </DockPanel>{/if}
      {#if selected.length && activeLayer.drawingMode !== 'merge'}
        <DockPanel id="hierarchy" heading="GROUP HIERARCHY" blocked={liveInputBlocked()||!!liveCurveConfig}>
          <label class="property-line hierarchy-field">Destination group
            <select aria-label="Destination group" bind:value={groupDestination}
              disabled={activeLayer.locked || foregroundBusy || playing || !!penDraft}>
              {#each groupDestinations as destination}
                <option value={destination.value}>{destination.label}</option>
              {/each}
            </select>
          </label>
          <label class="property-line hierarchy-field">Stack placement
            <select aria-label="Group stack placement" bind:value={groupPlacement}
              disabled={activeLayer.locked || foregroundBusy || playing || !!penDraft}>
              <option value="append">Above all destination children</option>
              <option value="before">Below anchor unit</option>
              <option value="after">Above anchor unit</option>
            </select>
          </label>
          {#if groupPlacement !== 'append'}
            <label class="property-line hierarchy-field">Anchor artwork
              <select aria-label="Group placement anchor" bind:value={groupAnchor}
                disabled={activeLayer.locked || foregroundBusy || playing || !!penDraft}>
                <option value="">Choose destination artwork</option>
                {#each groupAnchors as item (item.id)}
                  <option value={item.id}>{item.kind} · {item.id}</option>
                {/each}
              </select>
            </label>
          {/if}
          <button onclick={moveSelectionToGroup}
            disabled={activeLayer.locked || foregroundBusy || playing || !!penDraft ||
              (groupPlacement === 'append' ? groupDestination === JSON.stringify(groupScope) : !groupAnchor)}>
            Move selection to group
          </button>
          <p class="hint">Moves complete selected units. Anchors place them around a whole sibling unit, never inside it. Artwork stays in place.</p>
          <HierarchyPlacement entries={hierarchyEntries} disabled={hierarchyBlocked} dragging={!!objectHierarchyDrag}
            onstart={startHierarchyDrag} onend={cancelHierarchyDrag} onover={overHierarchyDrag}
            ondrop={dropHierarchyDrag} onplace={placeHierarchySelection} />

        </DockPanel>
      {/if}
      {#if canAuthorOpacity && primary}
        <DockPanel id="opacity" heading="OPACITY CHANNEL" blocked={liveInputBlocked()||!!liveCurveConfig}>
        {#key project}
          {#key JSON.stringify([historyTick, layerId, primary.id, frame, groupScope])}
            <OpacityChannel {frame} duration={project.duration} opacity={primary.opacity ?? 1}
              binding={selectedOpacityChannels.length === 1 ? selectedOpacityChannels[0] : undefined}
              onapply={applyOpacityChannel} />
          {/key}
        {/key}
        </DockPanel>
      {/if}
      {#if onMotionJunction && selected.length && activeLayer.drawingMode !== 'merge'}
        <DockPanel id="junction" heading="SHARED MOTION ENDPOINT" blocked={liveInputBlocked()||!!liveCurveConfig}>
        <section aria-label="Shared motion endpoint">
          <label>Move X<input type="number" step="any" aria-label="Shared endpoint X offset" bind:value={junctionDx}/></label>
          <label>Move Y<input type="number" step="any" aria-label="Shared endpoint Y offset" bind:value={junctionDy}/></label>
          <button disabled={foregroundBusy||playing||activeLayer.locked||!!penDraft||(!junctionDx&&!junctionDy)} onclick={()=>editJunction()}>Move endpoint and refresh both spans</button>
          <label>Rotate degrees<input type="number" step="any" aria-label="Shared endpoint rotation" bind:value={junctionAngle}/></label>
          <button disabled={foregroundBusy||playing||activeLayer.locked||!!penDraft||!junctionAngle} onclick={()=>editJunction('rotate')}>Rotate endpoint and refresh both spans</button>
          <label>Scale X %<input type="number" step="any" aria-label="Shared endpoint X scale" bind:value={junctionScaleX}/></label>
          <label>Scale Y %<input type="number" step="any" aria-label="Shared endpoint Y scale" bind:value={junctionScaleY}/></label>
          <button disabled={foregroundBusy||playing||activeLayer.locked||!!penDraft||!Number.isFinite(junctionScaleX)||!Number.isFinite(junctionScaleY)||!junctionScaleX||!junctionScaleY||(junctionScaleX===100&&junctionScaleY===100)} onclick={()=>editJunction('scale')}>Scale endpoint and refresh both spans</button>
          <label>Skew axis<select aria-label="Shared endpoint skew axis" bind:value={junctionSkewAxis}><option value="x">Document X</option><option value="y">Document Y</option></select></label>
          <label>Skew degrees<input type="number" step="any" aria-label="Shared endpoint skew angle" bind:value={junctionSkewAngle}/></label>
          <button disabled={foregroundBusy||playing||activeLayer.locked||!!penDraft||!Number.isFinite(junctionSkewAngle)||!junctionSkewAngle||junctionSkewAngle%180===0} onclick={()=>editJunction('skew')}>Skew endpoint and refresh both spans</button>
          <small>Scaling and skew require compatible saved affine interpolation on both spans; recipe settings remain unchanged.</small>
          <small>Uses the common saved selection pivot or the combined authoring-box center. Both spans must remain valid.</small>
        </section>
        </DockPanel>
      {/if}
      <div class="inspector-title">
        <span class="object-icon">{primary ? '◇' : '▣'}</span>
        <div>
          <strong
            >{primary
              ? selected.length > 1
                ? `${selected.length} objects`
                : primary.kind
              : 'Document'}</strong
          ><small>{primary ? 'Editable vector · object drawing' : 'Splash Animator project'}</small>
        </div>
      </div>
      {#if tool === 'eyedropper'}<DockPanel id="eyedropper" heading="Eyedropper" blocked={liveInputBlocked()||!!liveCurveConfig}>
          <label
            >Source<select aria-label="Eyedropper source" bind:value={eyedropperSource}
              ><option value="stored">Stored fill or stroke</option><option value="object">Whole object style</option><option value="rendered"
                >Rendered artwork</option
              ></select
            ></label
          >
          <label title="Stay on the Eyedropper after sampling stored paint"><input type="checkbox" bind:checked={keepEyedropper} disabled={eyedropperSource !== 'stored'} />Keep sampling</label>
          <p class="hint">
            Rendered artwork samples the visible composite into Drawing fill, including gradients,
            opacity and the stage background. Alt-click temporarily samples rendered artwork.
            Stored paint copies the fill or the stroke you click.
          </p>
        </DockPanel>{/if}
      {#if tool === 'brush'}<DockPanel id="brush" heading="BRUSH · NEW STROKES" blocked={liveInputBlocked()||!!liveCurveConfig}>
          <label><input type="checkbox" bind:checked={brushObjects} />Separate brush objects</label>
          <BrushContactOpacity available={brushObjects && (brushPaintMode === 'normal' || brushPaintMode === 'behind')}
            alongAvailable={brushObjects && (brushPaintMode === 'normal' || brushPaintMode === 'behind') && !tiltNib && !twistNib}
            bind:along={() => strokeOpacityEnabled, enabled => { if (enabled || strokeOpacityEnabled) pressureOpacity = enabled ? 'continuous' : 'off'; }}
            bind:enabled={() => contactOpacityEnabled, enabled => { if (enabled || contactOpacityEnabled) pressureOpacity = enabled ? 'initial' : 'off'; }}
            bind:minimum={contactOpacityMinimum} bind:response={contactOpacityResponse} />
          <p class="hint">
            Default: merged fill shapes. Overlapping paint joins existing fills; use Subselection
            (A) to edit outline points. Separate objects retain pressure samples and object
            transforms.
          </p>
          <label
            >Stabilizer distance<input
              aria-label="Brush stabilizer distance"
              type="number"
              min="0"
              max="100"
              bind:value={stabilization}
            /></label
          >
          <label
            >Simplify %<input
              aria-label="Brush finish simplify"
              type="number"
              min="0"
              max="200"
              bind:value={brushSmoothing}
            /></label
          >
          <label><input aria-label="Brush optimize in Properties" type="checkbox" bind:checked={brushOptimize}/>Optimize</label>
          <label title="Keep the same brush width in canvas pixels at every zoom. Zooming in makes the brush appear larger."><input aria-label="Brush lock size to canvas in Properties" type="checkbox" checked={!brushScreenSize} onchange={e=>brushScreenSize=!e.currentTarget.checked}/>Lock size to canvas</label>
          <p class="hint">
            Distance is in stage units. The stroke trails the pointer and reaches the release
            position. Simplify preserves endpoints and pen metadata. Zero disables either filter.
          </p>

          <label
            >Twist rotates nib<input
              aria-label="Twist rotates nib"
              type="checkbox"
              bind:checked={twistNib}
            /></label
          >
          <label
            >Response<input
              aria-label="New brush pressure response"
              type="number"
              min="0.25"
              max="4"
              step="0.25"
              bind:value={brushResponse}
            /></label
          >
          <p class="hint">
            Response 1 is linear. Lower values make light pressure wider; higher values need firmer
            pressure. Raw samples are retained.
          </p>

          <label class="property-line"
            >Paint mode<select aria-label="Brush paint mode" bind:value={brushPaintMode}
              ><option value="normal">Normal</option><option value="behind">Behind artwork</option
              ><option value="fills">Fills and empty space</option><option value="selection"
                >Selected fills</option
              ><option value="inside">Inside starting fill</option></select
            ></label
          >
          <p class="hint">
            Constrained modes preserve outlines and create editable filled contours when released.
            Selected fills needs a selection. Inside stays in the starting fill, or avoids existing
            fills when started in empty space.
          </p>
          <label class="property-line"
            >Size<input
              aria-label="Brush size"
              type="number"
              min="1"
              max="200"
              bind:value={brushSize}
            /></label
          >
          <label class="property-line"
            >Keep brush size on screen<input
              aria-label="Keep brush size on screen"
              type="checkbox"
              bind:checked={brushScreenSize}
            /></label
          >
          <p class="hint">
            {brushScreenSize
              ? 'Size is measured in screen pixels; zoom in for finer document strokes.'
              : 'Size is measured in document pixels and grows on screen when zoomed in.'} Use [ and ]
            to change size. Document width is limited to 200 pixels.
          </p>
          <p class="hint">
            Current width: {Number(brushDocumentSize.toFixed(2))} document px · {Number(
              (brushDocumentSize * zoom).toFixed(2),
            )} screen px
          </p>
          <label class="property-line"
            >Pressure controls size<input
              aria-label="Pressure controls size"
              type="checkbox"
              bind:checked={pressureSize}
            /></label
          >
          <label class="property-line"
            >Minimum size<select aria-label="Minimum brush size" bind:value={minimumSize}
              ><option value={0.05}>5%</option><option value={0.1}>10%</option><option value={0.25}
                >25%</option
              ><option value={0.5}>50%</option></select
            ></label
          >
          <label class="property-line"
            >Tilt controls nib<input
              aria-label="Tilt controls nib"
              type="checkbox"
              bind:checked={tiltNib}
            /></label
          >
          <label class="property-line"
            >Nib<select aria-label="Brush nib" bind:value={nibAspect}
              ><option value={1}>Round</option><option value={0.3}>Calligraphy</option></select
            ></label
          >
          <label class="property-line"
            >Nib angle<input
              aria-label="Nib angle"
              type="number"
              min="-180"
              max="180"
              bind:value={nibAngle}
            /></label
          >
          <p class="hint">
            Pressure changes stroke width. Mouse uses full width. Pen eraser temporarily erases;
            barrel-button tap samples paint.
          </p>
        </DockPanel>{/if}
      {#if tool === 'subselect'}<DockPanel id="anchors" heading="ANCHORS" blocked={liveInputBlocked()||!!liveCurveConfig}>
          <p class="hint">
            Drag a selection box to select vertices across editable artwork in this layer. Shift adds, Alt
            subtracts, Shift+Alt intersects. Shift-click anchors to add or remove them. Drag a
            selected anchor to move the set. Arrow keys nudge; Shift nudges ten pixels. Delete
            removes selected anchors when enough remain.
          </p>
          <p>{anchorCount} anchors selected</p>
          <button
            disabled={activeLayer.locked || primary?.kind !== 'bezier'}
            onclick={() => setBezierClosed(!primary?.closed)}
            >{primary?.closed ? 'Open Bezier path' : 'Close Bezier path'}</button
          >
          <button
            disabled={activeLayer.locked ||
              activeLayer.drawingMode === 'merge' ||
              primary?.kind !== 'bezier' ||
              (nodeIndices.length !== 1 || anchorCount !== 1) ||
              (!primary.closed &&
                (nodeIndices[0] === 0 || nodeIndices[0] === (primary.nodes?.length ?? 0) - 1)) ||
              (!!primary.closed && (primary.nodes?.length ?? 0) >= 100000)}
            onclick={splitSelectedBezier}>Split path at anchor</button
          >

          <button
            disabled={activeLayer.locked ||
              activeLayer.drawingMode === 'merge' ||
              primary?.kind !== 'bezier' ||
              primary.closed ||
              (nodeIndices.length !== 1 || anchorCount !== 1) ||
              (nodeIndices[0] !== 0 && nodeIndices[0] !== (primary.nodes?.length ?? 0) - 1)}
            onclick={continueSelectedPath}>Continue from endpoint</button
          >
          <label class="property-line"
            >Segment position %<input
              aria-label="Anchor insertion position"
              type="number"
              min="1"
              max="99"
              bind:value={insertionPercent}
            /></label
          >
          <button
            disabled={activeLayer.locked ||
              !editableAnchorCurves ||
              (nodeIndices.length !== 1 || anchorCount !== 1) ||
              !Number.isFinite(insertionPercent) ||
              insertionPercent <= 0 ||
              insertionPercent >= 100 ||
              (!primary?.contours &&
                !primary?.closed &&
                nodeIndices[0] === (primary?.nodes?.length ?? 0) - 1) ||
              (primary?.contours?.reduce((n, ring) => n + ring.length, 0) ??
                primary?.nodes?.length ??
                0) >= 100000}
            onclick={insertSelectedAnchor}>Insert anchor after selection</button
          >
          <button
            disabled={activeLayer.locked || !editableAnchorCurves || (nodeIndices.length !== 1 || anchorCount !== 1)}
            onclick={dissolveSelectedAnchor}>{boundedAnchorDissolve ? 'Dissolve anchor' : 'Dissolve redundant anchor'}</button
          >
          <p class="hint">
            {boundedAnchorDissolve
              ? `Dissolve removes a smooth anchor with up to ${STROKE_DISSOLVE_ERROR} document pixels of curve deviation.`
              : 'Dissolve joins compatible split curves. Delete can reshape them.'}
          </p>
          <p class="hint">
            Alt-click a selected curve with Subselection to insert an anchor. Existing anchors and
            handles take priority.
          </p>

          <button
            disabled={activeLayer.locked || !editableAnchorCurves || !nodeIndices.length}
            onclick={() => convertSelectedAnchors('smooth')}>Smooth selected anchors</button
          >
          <button
            disabled={activeLayer.locked || !editableAnchorCurves || !nodeIndices.length}
            onclick={() => convertSelectedAnchors('corner')}>Corner selected anchors</button
          >
        </DockPanel>{/if}
      {#if tool === 'lasso'}<DockPanel id="lasso" heading="LASSO" blocked={liveInputBlocked()||!!liveCurveConfig}>
          {#if activeLayer.drawingMode === 'merge'}
            <label><input type="checkbox" bind:checked={partialPaint} />Partial paint region</label>
            {#if partialPaint}
              <label
                ><input type="checkbox" bind:checked={dragPaintRegion} />Drag paint region</label
              >
              <p class="hint">
                Drag inside the region to preview its outline; paint commits on release. Escape
                cancels.
              </p>
              <p class="hint">
                Choose Replace, Add, Subtract or Intersect to combine paint regions. Copy, cut or
                delete portions of vector fills and strokes; text stays intact. Cut strokes become
                fill outlines. Escape clears the region.
              </p>
              <label class="property-line"
                >Move X<input
                  aria-label="Paint region move X"
                  type="number"
                  min="-100000"
                  max="100000"
                  bind:value={regionMoveX}
                /></label
              >
              <label class="property-line"
                >Move Y<input
                  aria-label="Paint region move Y"
                  type="number"
                  min="-100000"
                  max="100000"
                  bind:value={regionMoveY}
                /></label
              >
              <button
                disabled={!paintRegion.length}
                onclick={() => regionClipboard('move', { x: regionMoveX, y: regionMoveY })}
                >Move paint region</button
              >
              <p class="hint">
                Arrow keys move paint one stage unit; Shift moves ten. The region follows the paint.
                {shortcutLabel('pasteInPlace') ? 'Paste in place uses '+shortcutLabel('pasteInPlace')+'.' : 'Use Edit → Paste in place.'}
              </p>
              <button disabled={!paintRegion.length} onclick={() => regionClipboard('copy')}
                >Copy paint region</button
              >
              <button disabled={!paintRegion.length} onclick={() => regionClipboard('cut')}
                >Cut paint region</button
              >
              <button disabled={!paintRegion.length} onclick={() => regionClipboard('delete')}
                >Delete paint region</button
              >
            {/if}
          {/if}
          <label class="property-line"
            >Mode<select
              aria-label="Lasso mode"
              bind:value={lassoMode}
              onchange={() => {
                polygonLasso = [];
              }}
            >
              <option value="freehand">Freehand</option><option value="polygon">Polygon</option>
            </select></label
          >
          <label class="property-line"
            >Selection<select aria-label="Lasso selection mode" bind:value={selectionMode}>
              <option value="replace">Replace</option><option value="add">Add</option><option
                value="subtract">Subtract</option
              ><option value="intersect">Intersect</option>
            </select></label
          >
          {#if lassoMode === 'polygon'}
            <button disabled={polygonLasso.length < 3} onclick={finishPolygonLasso}
              >Finish lasso</button
            >
            <button
              disabled={!polygonLasso.length}
              onclick={() => {
                polygonLasso = [];
              }}>Cancel lasso</button
            >
          {/if}
          <p class="hint">
            Polygon: click vertices, then Enter or the first vertex to finish. Backspace removes the
            last vertex; Escape cancels. Contains whole transformed boxes, expanding groups. At the
            first point: Shift adds, Alt subtracts, Shift+Alt intersects.
          </p>
        </DockPanel>{/if}
      {#if tool === 'pen'}<DockPanel id="pen" heading="BÉZIER PEN" blocked={liveInputBlocked()||!!liveCurveConfig}>
          <p class="hint">
            Click an anchor; drag to pull its tangent handles. Alt-drag creates a corner. Click the
            first anchor to close. Enter finishes an open path; Escape cancels. To extend an
            existing open object path, select its endpoint with Subselection and choose Continue
            from endpoint.
          </p>
          <button disabled={!penDraft} onclick={() => finishPen()}>Finish path</button><button
            disabled={!penDraft || (penDraft.nodes?.length ?? 0) < 3}
            onclick={() => finishPen(true)}>Close path</button
          >
        </DockPanel>{/if}
      {#if tool === 'bucket'}<DockPanel id="bucket" heading="PAINT BUCKET" blocked={liveInputBlocked()||!!liveCurveConfig}>
          <label class="property-line"
            >Close gaps up to<input
              aria-label="Bucket gap tolerance"
              type="number"
              min="0"
              max="40"
              bind:value={bucketGap}
            /></label
          >
          <p class="hint">
            Stage units. Zero requires closed outlines. Nearby open endpoints can be bridged for the
            fill without changing strokes. Uses this layer and group.
          </p>
        </DockPanel>{/if}
      {#if tool === 'eraser'}<DockPanel id="eraser" heading="ERASER" blocked={liveInputBlocked()||!!liveCurveConfig}>
          <label class="property-line"
            >Diameter<input
              aria-label="Eraser diameter"
              type="number"
              min="2"
              max="200"
              bind:value={eraserSize}
            /></label
          ><label class="property-line"
            >Mode<select aria-label="Eraser mode" bind:value={eraserMode}
              ><option value="all">All vector paint</option><option value="fills">Fills only</option
              ><option value="strokes">Stroke segments</option><option value="inside"
                >Inside starting fill</option
              ><option value="objects">Whole objects</option></select
            ></label
          >
          <label class="property-line"
            >Selected only<input
              aria-label="Erase selected only"
              type="checkbox"
              bind:checked={eraserSelectedOnly}
            /></label
          >
          <p class="hint">
            Vector modes cut fill and stroke outlines. Cuts commit when you release the pointer.
            Inside starting fill affects only the fill under the initial contact, leaving outlines
            intact. Selected only protects unselected artwork; select objects first. Enter a group
            to erase its members. Text is handled by Whole objects.
          </p>
        </DockPanel>{/if}
      {#if tool === 'rounded'}<DockPanel id="rounded" heading="ROUNDED RECTANGLE" blocked={liveInputBlocked()||!!liveCurveConfig}>
          <label class="property-line"
            >Corner radius<input
              aria-label="Corner radius"
              type="number"
              min="0"
              max="1000"
              bind:value={cornerRadius}
            /></label
          >
        </DockPanel>{/if}
      {#if tool === 'star'}<DockPanel id="star" heading="POLYSTAR" blocked={liveInputBlocked()||!!liveCurveConfig}>
          <label class="property-line"
            >Points<input
              aria-label="Star points"
              type="number"
              min="3"
              max="32"
              bind:value={starSides}
            /></label
          ><label class="property-line"
            >Inner radius<select aria-label="Star inner radius" bind:value={starRatio}
              ><option value={0.25}>25%</option><option value={0.45}>45%</option><option value={0.7}
                >70%</option
              ><option value={1}>Polygon</option></select
            ></label
          >
        </DockPanel>{/if}
      {#if tool === 'path'}<DockPanel id="pencil" heading="PENCIL" blocked={liveInputBlocked()||!!liveCurveConfig}>
          <label class="property-line"
            >Mode<select aria-label="Pencil mode in Properties" bind:value={pencilMode}
              ><option value="ink">Off (Ink)</option><option value="smooth">Simplify</option><option
                value="straight">Straight line</option
              ></select
            ></label
          >
          <label class="property-line">Simplify %<input aria-label="Pencil finish simplify" type="number" min="0" max="200" step="1" disabled={pencilMode!=='smooth'} bind:value={pencilSmoothing}/></label>
          <label><input aria-label="Pencil optimize in Properties" type="checkbox" bind:checked={pencilOptimize}/>Optimize</label>
        </DockPanel>{/if}
      {#if selectedUnitCount > 0}
        <DockPanel id="align" heading="ALIGN AND DISTRIBUTE" blocked={liveInputBlocked() || !!liveCurveConfig}>
          <label class="property-line"
            >Align to stage<input
              type="checkbox"
              aria-label="Align to stage"
              bind:checked={alignToStage}
            /></label
          >
          <div class="property-grid">
            {#each ['left', 'center', 'right', 'top', 'middle', 'bottom'] as alignment}
              <button
                aria-label={`Align ${alignment}`}
                disabled={activeLayer.locked || (!alignToStage && selectedUnitCount < 2)}
                onclick={() => alignSelection(alignment as Alignment)}>{alignment}</button
              >
            {/each}
            <button
              aria-label="Distribute horizontal centers"
              disabled={activeLayer.locked || selectedUnitCount < 3}
              onclick={() => distributeSelection('x')}>Space X</button
            >
            <button
              aria-label="Distribute vertical centers"
              disabled={activeLayer.locked || selectedUnitCount < 3}
              onclick={() => distributeSelection('y')}>Space Y</button
            >
            {#each ['x', 'y'] as axis}
              <button
                aria-label={`Distribute ${axis === 'x' ? 'horizontal' : 'vertical'} gaps`}
                disabled={activeLayer.locked || selectedUnitCount < 3}
                onclick={() => distributeSelection(axis as 'x' | 'y', true)}
                >Gaps {axis.toUpperCase()}</button
              >
            {/each}
          </div>
          <p class="hint">
            Uses transformed authoring bounds, excluding stroke width. Space distributes unit
            centers; groups move together. Gaps keeps the first and last units fixed and moves
            groups together; negative gaps overlap.
          </p>
        </DockPanel>
      {/if}
      {#if primary?.kind === 'symbol' && selected.length === 1}
        {@const instance = primary}
        {@const definition = project.symbols?.find(item => item.id === instance.symbolId)}
        {@const mode = instance.symbolPlayback?.mode ?? 'loop'}
        {@const firstFrame = instance.symbolPlayback?.firstFrame ?? 0}
        {@const disabled = !canEditSymbolInstance(instance)}
        <DockPanel id="symbol-instance" heading="SYMBOL INSTANCE" blocked={liveInputBlocked() || !!liveCurveConfig}>
          {#key instance}
            <label class="property-line">Symbol<select
              aria-label="Swap symbol"
              value={instance.symbolId}
              disabled={disabled}
              onchange={event => swapSymbolInstance(instance, event.currentTarget.value)}
            >
              {#each project.symbols ?? [] as item (item.id)}
                <option value={item.id}>{item.name}</option>
              {/each}
            </select></label>
            <label class="property-line">Instance name<input
              aria-label="Symbol instance name"
              maxlength="200"
              value={instance.instanceName ?? ''}
              {disabled}
              onchange={event => {
                renameSymbolInstance(instance, event.currentTarget.value);
                event.currentTarget.value = instance.instanceName ?? '';
              }}
            /></label>
            <label class="property-line">Type<select
              aria-label="Symbol instance type"
              value={definition?.buttonStates ? 'button' : mode === 'movie' ? 'movie' : 'graphic'}
              disabled={disabled || !!definition?.buttonStates}
              onchange={event => setSymbolPlayback(instance, event.currentTarget.value === 'movie' ? 'movie' : 'loop', firstFrame)}
            >
              {#if definition?.buttonStates}<option value="button">Button</option>{:else}
                <option value="graphic">Graphic</option>
                <option value="movie">Movie clip</option>
              {/if}
            </select></label>
            {#if !definition?.buttonStates}
              {#if mode !== 'movie'}
                <label class="property-line">Playback<select
                  aria-label="Symbol playback"
                  value={mode}
                  {disabled}
                  onchange={event => setSymbolPlayback(instance, event.currentTarget.value as 'loop' | 'once' | 'single', firstFrame)}
                >
                  <option value="loop">Loop</option>
                  <option value="once">Play once</option>
                  <option value="single">Single frame</option>
                </select></label>
              {/if}
              <label class="property-line">First frame<input
                aria-label="Symbol first frame"
                type="number"
                min="1"
                max="10000"
                value={firstFrame + 1}
                {disabled}
                onchange={event => {
                  setSymbolPlayback(instance, mode, event.currentTarget.valueAsNumber - 1);
                  event.currentTarget.value = String((instance.symbolPlayback?.firstFrame ?? 0) + 1);
                }}
              /></label>
            {/if}
            {@render artworkDimensions(instance, disabled)}
            <button disabled={disabled || !directMember(instance)} onclick={editSymbolInContext}>Edit symbol in stage context</button>
            <button disabled={disabled || !!groupScope.length} onclick={() =>
              editSymbolInstance(instance, 'Make symbol instance unique', () =>
                makeSymbolUnique(project, layerId, frame, instance.id)
              )}>Make instance unique</button>
            <button disabled={disabled || !!groupScope.length} onclick={breakSelectedSymbol}>Break apart symbol</button>
          {/key}
        </DockPanel>
        <DockPanel id="effects" heading="EFFECTS" blocked={liveInputBlocked() || !!liveCurveConfig}>
          {#key instance}
            <SymbolEffectsPanel {instance} button={!!definition?.buttonStates} {disabled} scope={inspectorPropertyScope}
              onchange={(patch,label) => {
                if (gesture || !canEditSymbolInstance(instance)) return;
                edit(label, () => applySymbolEffectPatch(instance, patch), true, true);
              }}/>
          {/key}
        </DockPanel>
      {/if}
      {#if primary}
        {#if primary.kind !== 'symbol' || selected.length !== 1}<DockPanel id="position" heading="POSITION AND SIZE" blocked={liveInputBlocked()||!!liveCurveConfig}>
          {@render artworkDimensions(primary, activeLayer.locked)}
          <p class="hint">
            Use Selection handles to transform. These fields describe the local geometry and
            additional rotation; Transform shows the resulting stage bounds.
          </p>
        </DockPanel>{/if}
        {#if primary.kind !== 'symbol'}<DockPanel id="paint" heading="FILL AND STROKE" blocked={liveInputBlocked()||!!liveCurveConfig}>
          <label class="property-line"
            >Fill type<select
              aria-label="Fill type"
              value={primary.bitmap ? 'bitmap' : (primary.gradient?.kind ?? 'solid')}
              onchange={(e) => setGradient(e.currentTarget.value)}
              >{#if primary.bitmap}<option value="bitmap" disabled>Bitmap</option>{/if}<option
                value="solid">Solid</option
              ><option value="linear">Linear gradient</option><option value="radial"
                >Radial gradient</option
              ></select
            ></label
          >
          {#if primary.gradient}{#each primary.gradient.stops as stop, index}<label
                class="property-line"
                >Stop {index + 1}<input
                  type="color"
                  aria-label={`Gradient color ${index + 1}`}
                  value={stop.color}
                  onchange={(e) => gradientStop(index, e.currentTarget.value)}
                /></label
              ><label class="property-line"
                >Position %<input
                  aria-label={`Gradient position ${index + 1}`}
                  type="number"
                  min="0"
                  max="100"
                  step="0.1"
                  value={stop.offset * 100}
                  disabled={activeLayer.locked}
                  onchange={(e) => gradientPosition(index, e.currentTarget.valueAsNumber)}
                /></label
              >
              <NumberSlider emptyValue={NaN} label={`Gradient opacity ${index+1}`} caption="Opacity %" value={(stop.opacity??1)*100} min={0} max={100} disabled={activeLayer.locked} scope={inspectorPropertyScope} onchange={value=>gradientOpacity(index,value)}/>
              <button
                aria-label={`Remove gradient stop ${index + 1}`}
                disabled={activeLayer.locked || primary.gradient.stops.length <= 2}
                onclick={() =>
                  primary?.gradient &&
                  setStyle({ gradient: removeGradientStop(primary.gradient, index) })}
                >Remove stop {index + 1}</button
              >
            {/each}<button
              disabled={activeLayer.locked || primary.gradient.stops.length >= 32}
              onclick={() =>
                primary?.gradient && setStyle({ gradient: addGradientStop(primary.gradient) })}
              >Add gradient stop</button
            >
            <details>
              <summary>Gradient transform</summary>
              <label class="property-line"
                >Move X<input
                  aria-label="Gradient move X"
                  type="number"
                  bind:value={gradientMoveX}
                /></label
              >
              <label class="property-line"
                >Move Y<input
                  aria-label="Gradient move Y"
                  type="number"
                  bind:value={gradientMoveY}
                /></label
              >
              <label class="property-line"
                >Rotate degrees<input
                  aria-label="Gradient rotation"
                  type="number"
                  bind:value={gradientRotation}
                /></label
              >
              <label class="property-line"
                >Scale %<input
                  aria-label="Gradient scale"
                  type="number"
                  min="0.01"
                  max="10000"
                  bind:value={gradientScale}
                /></label
              >
              <button
                disabled={activeLayer.locked ||
                  ![gradientMoveX, gradientMoveY, gradientRotation, gradientScale].every(
                    Number.isFinite,
                  ) ||
                  gradientScale <= 0 ||
                  gradientScale > 10000}
                onclick={applyGradientTransform}>Apply gradient transform</button
              >
              <label class="property-line"
                >Height %<input
                  aria-label="Gradient aspect"
                  type="number"
                  min="1"
                  max="10000"
                  bind:value={gradientAspect}
                /></label
              >
              <label class="property-line"
                >Skew degrees<input
                  aria-label="Gradient skew"
                  type="number"
                  min="-80"
                  max="80"
                  bind:value={gradientSkew}
                /></label
              >
              <button disabled={activeLayer.locked} onclick={applyGradientShape}
                >Apply gradient shape</button
              >

              <button
                disabled={activeLayer.locked}
                onclick={() =>
                  primary?.gradient &&
                  setStyle({ gradient: { ...clone(primary.gradient), transform: [1, 0, 0, 1] } })}
                >Reset gradient axes</button
              >
              <p class="hint">
                Drag colored dots to move stops; drag the purple diamond to change ellipse height
                and skew. Alt bypasses snapping; Escape cancels.
              </p>
              <p class="hint">
                Local units. Rotation and uniform scaling use the gradient start/center as pivot.
                Shape geometry stays fixed. Height and skew set an independent paint basis around
                the start/center.
              </p>
            </details>

            <button onclick={() => chooseTool('gradient')}>Transform gradient (F)</button>{/if}
          <label class="property-line"
            >Fill<input
              type="color"
              aria-label="Selected fill"
              value={primary.fill}
              onchange={(e) => setShape('fill', e.currentTarget.value)}
            /></label
          ><label class="property-line"
            >Stroke<input
              type="color"
              aria-label="Selected stroke"
              value={primary.stroke}
              onchange={(e) => setShape('stroke', e.currentTarget.value)}
            /></label
          ><label class="property-line"
            >Stroke width<input
              aria-label="Stroke width"
              type="number"
              min="0"
              max="200"
              value={primary.strokeWidth}
              onchange={(e) => setShape('strokeWidth', e.currentTarget.value)}
            /></label
          >
          <label class="property-line"
            >Fill enabled<input
              aria-label="Fill enabled"
              type="checkbox"
              checked={primary.fillEnabled !== false}
              onchange={(e) => setStyle({ fillEnabled: e.currentTarget.checked })}
            /></label
          >
          <NumberSlider label="Object opacity" caption="Opacity" value={(primary.opacity??1)*100} min={0} max={100} disabled={activeLayer.locked} scope={inspectorPropertyScope} onchange={value=>setStyle({opacity:Math.max(0,Math.min(1,value/100))})}/>
          {#if shapes.filter(s=>selected.includes(s.id)).every(s=>(activeLayer.drawingMode==='object'||s.blurRadius||s.blendMode||s.tint)&&s.kind!=='text'&&s.kind!=='symbol'&&!s.brush?.opacityProfile)}
            <TintControls label="Drawing" tint={primary.tint} disabled={activeLayer.locked} scope={inspectorPropertyScope} onchange={patch=>{
              if(activeLayer.locked)return;
              const ids=new Set(selected);
              edit('Change drawing tint',()=>{
                for(const member of shapes)if(ids.has(member.id)){
                  if(patch)member.tint={color:'#ffffff',amount:0,...member.tint,...patch};
                  else delete member.tint;
                }
              },true);
            }}/>
            <label class="property-line">Blend<select aria-label="Drawing blend mode" value={primary.blendMode??'normal'} disabled={activeLayer.locked} onchange={e=>{
              const mode=e.currentTarget.value;
              if(activeLayer.locked||(mode!=='normal'&&!isBlendMode(mode)))return;
              const ids=new Set(selected);
              edit('Change drawing blend mode',()=>{
                for(const shape of shapes)if(ids.has(shape.id)){
                  if(mode==='normal')delete shape.blendMode;
                  else shape.blendMode=mode;
                }
              },true);
            }}><option value="normal">Normal</option>{#each blendModes as [value, label] (value)}<option {value}>{label}</option>{/each}</select></label>
            <NumberSlider label="Blur radius" caption="Blur (px)" value={primary.blurRadius??0} min={0} max={32} disabled={activeLayer.locked} scope={inspectorPropertyScope} onchange={value=>{
              if(!Number.isInteger(value)||value<0||value>32||activeLayer.locked)return;
              const ids=new Set(selected);
              edit('Change drawing blur',()=>{
                for(const s of shapes)if(ids.has(s.id)){if(value)s.blurRadius=value;else delete s.blurRadius;}
              },true);
            }}/>
          {/if}
          <NumberSlider label="Paint brightness" caption="Paint brightness" value={(primary.paintBrightness??0)*100} min={-100} max={100} disabled={activeLayer.locked} scope={inspectorPropertyScope} onchange={value=>{
            if (!Number.isFinite(value) || Math.abs(value)>100 || activeLayer.locked) return;
            const ids=new Set(selected);
            edit('Change paint brightness',()=>{
              for (const shape of shapes) if (ids.has(shape.id) && shape.kind!=='symbol') {
                if (value) shape.paintBrightness=value/100;
                else delete shape.paintBrightness;
              }
            },true);
          }}/>
          <label class="property-line"
            >Cap<select
              aria-label="Stroke cap"
              value={primary.strokeCap ?? 'round'}
              onchange={(e) =>
                setStyle({ strokeCap: e.currentTarget.value as Vector['strokeCap'] })}
              ><option>round</option><option>butt</option><option>square</option></select
            ></label
          >
          <label class="property-line"
            >Join<select
              aria-label="Stroke join"
              value={primary.strokeJoin ?? 'round'}
              onchange={(e) =>
                setStyle({ strokeJoin: e.currentTarget.value as Vector['strokeJoin'] })}
              ><option>round</option><option>bevel</option><option>miter</option></select
            ></label
          >
          {#if primary.kind === 'brush'}<label
              >Response<input
                aria-label="Selected pressure response"
                type="number"
                min="0.25"
                max="4"
                step="0.25"
                value={primary.brush?.response ?? 1}
                disabled={activeLayer.locked}
                onchange={(e) => setPressureResponse(e.currentTarget.valueAsNumber)}
              /></label
            >
            <div class="button-row">
              <button disabled={activeLayer.locked} onclick={() => setPressureResponse(0.5)}
                >Soft response</button
              ><button disabled={activeLayer.locked} onclick={() => setPressureResponse(1)}
                >Linear response</button
              ><button disabled={activeLayer.locked} onclick={() => setPressureResponse(2)}
                >Firm response</button
              >
            </div>
            <label class="property-line"
              >Stroke pressure<input
                aria-label="Selected stroke pressure"
                type="checkbox"
                checked={primary.brush?.pressure}
                onchange={(e) =>
                  setStyle({ brush: { ...primary!.brush!, pressure: e.currentTarget.checked } })}
              /></label
            >{/if}
          {#if primary.cornerRadius !== undefined}<label class="property-line"
              >Radius<input
                aria-label="Selected corner radius"
                type="number"
                min="0"
                value={primary.cornerRadius}
                onchange={(e) =>
                  setStyle({ cornerRadius: Math.max(0, Number(e.currentTarget.value) || 0) })}
              /></label
            >{/if}
        </DockPanel>
        {/if}
        {#if primary.kind === 'brush' && primary.points.length}<DockPanel id="pressure" heading="PRESSURE PROFILE" blocked={liveInputBlocked()||!!liveCurveConfig}>
            {#if selected.length === 1 && activeLayer.drawingMode !== 'merge'}
              {@const opacityProfile = primary.brush?.opacityProfile}
              <label><input type="checkbox" aria-label="Pressure varies opacity along stroke"
                disabled={activeLayer.locked} checked={!!opacityProfile}
                onchange={e=>setBrushOpacityProfile(e.currentTarget.checked)} />Pressure varies opacity along stroke</label>
              {#if opacityProfile}
                <label>Minimum opacity %<input type="number" min="0" max="100" step="1"
                  aria-label="Selected stroke minimum opacity" value={opacityProfile.minimum*100}
                  disabled={activeLayer.locked}
                  onchange={e=>setBrushOpacityProfile(true,e.currentTarget.valueAsNumber/100,opacityProfile.response)} /></label>
                <label>Opacity response<input type="number" min="0.25" max="4" step="0.25"
                  aria-label="Selected stroke opacity response" value={opacityProfile.response}
                  disabled={activeLayer.locked}
                  onchange={e=>setBrushOpacityProfile(true,opacityProfile.minimum,e.currentTarget.valueAsNumber)} /></label>
              {/if}
            {/if}

            <label
              >Smoothing %<input
                aria-label="Selected brush smoothing"
                type="number"
                min="0"
                max="100"
                bind:value={selectedSmoothing}
              /></label
            >
            <button
              disabled={activeLayer.locked}
              onclick={() =>
                edit('Smooth brush samples', () => {
                  primary!.points = smoothBrushSamples(
                    primary!.points,
                    Math.max(0, Math.min(1, (Number(selectedSmoothing) || 0) / 100)),
                  );
                  normalizeVector(primary!);
                })}>Smooth selected brush</button
            >

            <label
              >Nib aspect<input
                aria-label="Selected nib aspect"
                type="number"
                min="0.1"
                max="1"
                step="0.1"
                value={primary.brush?.aspect ?? 1}
                disabled={activeLayer.locked}
                onchange={(e) => setNib('aspect', e.currentTarget.valueAsNumber)}
              /></label
            >
            <label
              >Nib angle<input
                aria-label="Selected nib angle"
                type="number"
                value={primary.brush?.angle ?? 0}
                disabled={activeLayer.locked}
                onchange={(e) => setNib('angle', e.currentTarget.valueAsNumber)}
              /></label
            >
            <label
              >Tilt shapes nib<input
                aria-label="Selected nib tilt"
                type="checkbox"
                checked={primary.brush?.tilt ?? false}
                disabled={activeLayer.locked}
                onchange={(e) =>
                  setStyle({ brush: { ...primary!.brush!, tilt: e.currentTarget.checked } })}
              /></label
            >
            <label
              >Twist rotates nib<input
                aria-label="Selected nib twist"
                type="checkbox"
                checked={primary.brush?.twist ?? false}
                disabled={activeLayer.locked}
                onchange={(e) =>
                  setStyle({ brush: { ...primary!.brush!, twist: e.currentTarget.checked } })}
              /></label
            >
            <button
              disabled={activeLayer.locked}
              onclick={() =>
                setStyle({
                  brush: { ...primary!.brush!, aspect: 1, angle: 0, tilt: false, twist: false },
                })}>Reset nib</button
            >

            <label class="property-line"
              >Sample<input
                aria-label="Pressure sample"
                type="number"
                min="1"
                max={primary.points.length}
                bind:value={pressureSample}
              /></label
            >
            <label class="property-line"
              >Pressure %<input
                aria-label="Sample pressure"
                type="number"
                min="0"
                max="100"
                value={(primary.points[pressureIndex()].pressure ?? 1) * 100}
                disabled={activeLayer.locked}
                onchange={(e) => editPressure(e.currentTarget.valueAsNumber)}
              /></label
            >
            <label class="property-line"
              >Start %<input
                aria-label="Profile start pressure"
                type="number"
                min="0"
                max="100"
                bind:value={profileStart}
              /></label
            >
            <label class="property-line"
              >Middle %<input
                aria-label="Profile middle pressure"
                type="number"
                min="0"
                max="100"
                bind:value={profileMiddle}
              /></label
            >
            <label class="property-line"
              >End %<input
                aria-label="Profile end pressure"
                type="number"
                min="0"
                max="100"
                bind:value={profileEnd}
              /></label
            >
            <button disabled={activeLayer.locked} onclick={() => editPressure()}
              >Apply pressure profile</button
            >
            <button
              disabled={activeLayer.locked}
              onclick={() => {
                tool = 'subselect';
                status = 'Drag the selected pressure sample handle';
              }}>Edit width on canvas</button
            >
            <button
              disabled={activeLayer.locked}
              onclick={() => editBrushPressure('Reverse pressure profile', reversePressure)}
              >Reverse pressure profile</button
            >
            <button
              disabled={activeLayer.locked}
              onclick={() => editBrushPressure('Uniform pressure', source => applyPressureProfile(source, 1, 1, 1))}
              >Uniform pressure</button
            >
            <p class="hint">
              In Subselection, drag the purple handle to edit the chosen sample's width. Dragging
              follows the nib direction, clamps to the minimum/full brush width, and supports Escape
              and undo. Applies along stroke length and enables pressure width. Zero uses the
              brush's minimum width. Clipped and merged polygon paint has no editable pressure
              samples.
            </p>
          </DockPanel>{/if}
        {#if primary.text}<DockPanel id="text" heading={primary.text.input ? 'INPUT TEXT' : primary.text.dynamicBinding ? 'DYNAMIC TEXT' : 'STATIC TEXT'} blocked={liveInputBlocked()||!!liveCurveConfig}>
            {#key primary.id}
              <DynamicTextBinding value={primary.text.dynamicBinding} input={primary.text.input}
                disabled={!!stageText || activeLayer.locked} change={setTextBinding} />
            {/key}

            <label class="property-line"
              >Wrap width<input
                aria-label="Text wrap width"
                type="number"
                min="0"
                max="100000"
                value={primary.text.wrapWidth ?? 0}
                onchange={(e) => setText({ wrapWidth: e.currentTarget.valueAsNumber })}
              /></label
            >
            <p class="hint">
              Zero expands the field as you type. Drag its blue text handles to wrap and reflow; Selection transform handles scale the whole object.
            </p>
            <label class="property-line"
              >Line spacing %<input
                aria-label="Text line spacing"
                type="number"
                min="50"
                max="500"
                value={(primary.text.lineHeight ?? 1.2) * 100}
                onchange={(e) => setText({ lineHeight: e.currentTarget.valueAsNumber / 100 })}
              /></label
            >
            <label class="property-line"
              >Letter spacing<input
                aria-label="Text letter spacing"
                type="number"
                min="-20"
                max="200"
                step="0.5"
                value={stageText ? stageTextStyle.letterSpacing : (primary.text.letterSpacing ?? 0)}
                onchange={(e) => setText({ letterSpacing: e.currentTarget.valueAsNumber })}
              /></label
            >
            <label class="property-line"
              >Word spacing<input
                aria-label="Text word spacing"
                type="number"
                min="-20"
                max="200"
                step="0.5"
                value={stageText ? stageTextStyle.wordSpacing : (primary.text.wordSpacing ?? 0)}
                onchange={(e) => setText({ wordSpacing: e.currentTarget.valueAsNumber })}
              /></label
            >
            <label class="property-line"
              >Direction<select
                aria-label="Text direction"
                value={primary.text.direction ?? 'ltr'}
                onchange={(e) => setText({ direction: e.currentTarget.value as 'ltr' | 'rtl' })}
                ><option value="ltr">Left to right</option><option value="rtl">Right to left</option
                ></select
              ></label
            >
            <label class="property-line"
              >Kerning<select
                aria-label="Text kerning"
                value={stageText ? stageTextStyle.kerning : (primary.text.kerning ?? 'auto')}
                onchange={(e) =>
                  setText({ kerning: e.currentTarget.value as 'auto' | 'normal' | 'none' })}
                ><option value="auto">Automatic</option><option value="normal">Normal</option
                ><option value="none">None</option></select
              ></label
            >
            <TextFontControls font={textCharacterStyle?.font} disabled={activeLayer.locked}
              embedded={project.assets.flatMap(a => a.font?.dataUrl ? [a.font.family] : [])}
              change={font=>setText({font})} />
            <button disabled={!!stageText || activeLayer.locked || selected.length !== 1}
              onclick={outlineSelectedText}>Convert text to outlines</button>
            <p class="hint">
              Use an installed family, a project font or a comma-separated fallback list.
            </p>
            <textarea
              aria-label="Text content"
              bind:this={textEditor}
              onselect={(e) => captureTextSelection(e.currentTarget)}
              onkeyup={(e) => captureTextSelection(e.currentTarget)}
              onpointerup={(e) => captureTextSelection(e.currentTarget)}
              value={primary.text.content}
              onchange={(e) => {setText({ content: e.currentTarget.value.slice(0, 10000) });if(stageText)stageTextEditor?.finish();}}
            ></textarea>
            <details>
              <summary>Selected text formatting</summary>
              <p class="hint">
                Ranges without a color override inherit the object fill, including gradients and
                bitmaps.
              </p>
              <button disabled={!hasTextRange} onclick={() => formatSelection({ bold: true })}
                >Bold selection</button
              >
              <button disabled={!hasTextRange} onclick={() => formatSelection({ bold: false })}
                >Unbold selection</button
              >
              <button disabled={!hasTextRange} onclick={() => formatSelection({ italic: true })}
                >Italic selection</button
              >
              <button disabled={!hasTextRange} onclick={() => formatSelection({ italic: false })}
                >Upright selection</button
              >
              <label
                >Range letter spacing<input
                  aria-label="Range letter spacing"
                  type="number"
                  min="-100"
                  max="100"
                  bind:value={rangeTracking}
                /></label
              >
              <button
                disabled={!hasTextRange}
                onclick={() => formatSelection({ letterSpacing: rangeTracking })}
                >Apply range letter spacing</button
              >
              <label
                >Range word spacing<input
                  aria-label="Range word spacing"
                  type="number"
                  min="-1000"
                  max="1000"
                  bind:value={rangeWordSpacing}
                /></label
              >
              <button
                disabled={!hasTextRange}
                onclick={() => formatSelection({ wordSpacing: rangeWordSpacing })}
                >Apply range word spacing</button
              >
              <label
                >Range kerning<select aria-label="Range kerning" bind:value={rangeKerning}
                  ><option value="auto">Auto</option><option value="normal">Normal</option><option
                    value="none">None</option
                  ></select
                ></label
              >
              <button
                disabled={!hasTextRange}
                onclick={() => formatSelection({ kerning: rangeKerning })}
                >Apply range kerning</button
              >
              <button
                disabled={!hasTextRange}
                onclick={() =>
                  formatSelection({
                    letterSpacing: undefined,
                    wordSpacing: undefined,
                    kerning: undefined,
                  })}>Inherit range spacing</button
              >
              <button disabled={!hasTextRange} onclick={() => formatSelection({ color: undefined })}
                >Inherit range paint</button
              >
              <label>Range font<input aria-label="Range font" bind:value={rangeFont} /></label>
              <button disabled={!hasTextRange} onclick={() => formatSelection({ font: rangeFont })}
                >Apply range font</button
              >
              <label
                >Range size<input
                  aria-label="Range size"
                  type="number"
                  min="1"
                  max="1000"
                  bind:value={rangeSize}
                /></label
              >
              <button disabled={!hasTextRange} onclick={() => formatSelection({ size: rangeSize })}
                >Apply range size</button
              >
              <label
                >Range color<input
                  aria-label="Range color"
                  type="color"
                  bind:value={rangeColor}
                /></label
              >
              <button
                disabled={!hasTextRange}
                onclick={() => formatSelection({ color: rangeColor })}>Apply range color</button
              >
              <button
                disabled={!hasTextRange}
                onclick={() =>
                  formatSelection({
                    bold: undefined,
                    italic: undefined,
                    font: undefined,
                    size: undefined,
                    color: undefined,
                    letterSpacing: undefined,
                    wordSpacing: undefined,
                    kerning: undefined,
                  })}>Clear selected formatting</button
              >
              <button disabled={!primary.text.runs?.length} onclick={() => setText({ runs: [] })}
                >Clear all range formatting</button
              >
            </details>
            <div class="button-row" aria-label="Selected text actions">
              <button
                disabled={!hasTextRange || activeLayer.locked}
                onclick={() => applyTextRange('uppercase')}>Uppercase selection</button
              >
              <button
                disabled={!hasTextRange || activeLayer.locked}
                onclick={() => applyTextRange('lowercase')}>Lowercase selection</button
              >
              <button
                disabled={!hasTextRange || activeLayer.locked}
                onclick={() => applyTextRange('duplicate')}>Duplicate selected text</button
              >
              <button
                disabled={!hasTextRange || activeLayer.locked}
                onclick={() => applyTextRange('delete')}>Delete selected text</button
              >
            </div>
            <p class="hint">
              Select characters on the canvas or in Content to format a range. While editing on the canvas, font controls apply to the selected characters; object paint applies to the whole field.
            </p>
            <label class="property-line"
              >Size<input
                aria-label="Text size" placeholder="Mixed"
                type="number"
                min="1"
                max="1000"
                value={textCharacterStyle?.size}
                onchange={(e) =>
                  setText({
                    size: Math.max(1, Math.min(1000, Number(e.currentTarget.value) || 32)),
                  })}
              /></label
            ><label class="property-line"
              >Bold<input
                aria-label="Text bold"
                type="checkbox"
                checked={textCharacterStyle?.bold ?? false} indeterminate={!!stageText && textCharacterStyle?.bold === undefined}
                onchange={(e) => setText({ bold: e.currentTarget.checked })}
              /></label
            ><label class="property-line"
              >Italic<input
                aria-label="Text italic"
                type="checkbox"
                checked={textCharacterStyle?.italic ?? false} indeterminate={!!stageText && textCharacterStyle?.italic === undefined}
                onchange={(e) => setText({ italic: e.currentTarget.checked })}
              /></label
            ><label class="property-line">Text color<input aria-label="Text color" type="color" value={stageText ? (stageTextStyle.color ?? '#000000') : (typeof primary.fill==='string' ? primary.fill : '#000000')} title={stageText && stageTextStyle.color===undefined ? 'Mixed colors' : 'Character color'} onchange={e=>setTextColor(e.currentTarget.value)} /></label
            ><label class="property-line"
              >Align<select
                aria-label="Text alignment"
                value={primary.text.align}
                onchange={(e) =>
                  setText({ align: e.currentTarget.value as 'left' | 'center' | 'right' })}
                ><option>left</option><option>center</option><option>right</option></select
              ></label
            >
          </DockPanel>{/if}
        {#if primary.bitmap}<DockPanel id="bitmap" heading="BITMAP PAINT" blocked={liveInputBlocked()||!!liveCurveConfig}>
          {#if traceableBitmap()}<button onclick={openBitmapTrace}>Trace bitmap…</button>{/if}


            <p class="hint">Bitmap fill. Solid/gradient controls replace this paint.</p>
            <label
              ><input
                aria-label="Repeat bitmap fill"
                type="checkbox"
                checked={primary.bitmap.repeat ?? false}
                onchange={(e) =>
                  setStyle({ bitmap: { ...primary!.bitmap!, repeat: e.currentTarget.checked } })}
              />Repeat bitmap fill</label
            >
            <button
              onclick={() => {
                const a = project.assets.find((a) => a.id === primary!.bitmap!.assetId)?.bitmap;
                if (a)
                  setStyle({
                    bitmap: {
                      ...primary!.bitmap!,
                      x: 0,
                      y: 0,
                      width: a.width,
                      height: a.height,
                      transform: undefined,
                    },
                  });
              }}>Reset bitmap to native size</button
            >

            <details>
              <summary>Bitmap paint transform</summary>
              <button onclick={() => chooseTool('gradient')}>Transform bitmap on canvas (F)</button>
              <p class="hint">
                Drag O to move paint. Drag X/Y to scale, rotate or skew its axes. Alt bypasses
                snapping; Escape cancels.
              </p>
              <label class="property-line"
                >Move X<input
                  aria-label="Bitmap paint move X"
                  type="number"
                  bind:value={bitmapMoveX}
                /></label
              >
              <label class="property-line"
                >Move Y<input
                  aria-label="Bitmap paint move Y"
                  type="number"
                  bind:value={bitmapMoveY}
                /></label
              >
              <label class="property-line"
                >Rotation<input
                  aria-label="Bitmap paint rotation"
                  type="number"
                  bind:value={bitmapRotation}
                /></label
              >
              <label class="property-line"
                >Scale X %<input
                  aria-label="Bitmap paint scale X"
                  type="number"
                  bind:value={bitmapScaleX}
                /></label
              >
              <label class="property-line"
                >Scale Y %<input
                  aria-label="Bitmap paint scale Y"
                  type="number"
                  bind:value={bitmapScaleY}
                /></label
              >
              <label class="property-line"
                >Skew X<input
                  aria-label="Bitmap paint skew X"
                  type="number"
                  min="-80"
                  max="80"
                  bind:value={bitmapSkewX}
                /></label
              >
              <label class="property-line"
                >Skew Y<input
                  aria-label="Bitmap paint skew Y"
                  type="number"
                  min="-80"
                  max="80"
                  bind:value={bitmapSkewY}
                /></label
              >
              <button onclick={() => editBitmapTransform()}>Apply bitmap paint transform</button>
              <button onclick={() => editBitmapTransform(true)}>Reset bitmap paint basis</button>
              <button onclick={() => editBitmapTransform(false, true)}>Fit bitmap to shape</button>
              <p class="hint">
                Transforms paint around its local origin. Geometry stays fixed. Negative scales flip
                the paint. Each Apply composes with the existing transform.
              </p>
            </details>
          </DockPanel>{/if}
        {#if primary.kind !== 'text' && primary.kind !== 'brush' && primary.kind !== 'symbol'}<DockPanel id="path" heading="EDITABLE PATH" blocked={liveInputBlocked()||!!liveCurveConfig}>

            {#if primary.contours}
              <label class="property-line"
                >Fit tolerance<input
                  aria-label="Contour fit tolerance"
                  type="number"
                  min="0.001"
                  max="2"
                  step="0.05"
                  bind:value={fitTolerance}
                  onchange={cancelContourFit}
                /></label
              >
              <button
                disabled={activeLayer.locked || foregroundBusy || fitPending || !fitEligible}
                onclick={previewContourFit}>Preview fitted contours</button
              >
              {#if fitPending || fitCandidate}
                {#if fitCandidate}<p class="hint">
                    {fitCandidate.fits.reduce((n, f) => n + f.sourceAnchors, 0)} → {fitCandidate.fits.reduce(
                      (n, f) => n + f.fittedAnchors,
                      0,
                    )} anchors
                  </p>{/if}
                {#if fitCandidate}
                  <label
                    ><input type="checkbox" bind:checked={showFitJoins} /> Show fitted join issues</label
                  >
                  <p class="hint" data-testid="fit-join-quality">
                    Largest non-corner tangent change: {Math.max(
                      ...fitCandidate.fits.map((f) => f.joins.maxDegrees),
                    ).toFixed(2)}°. {fitCandidate.fits.reduce(
                      (n, f) => n + f.joins.discontinuities,
                      0,
                    )} joins exceed 1°.
                    {#if fitCandidate.fits.some((f) => f.joins.degenerate)}
                      {fitCandidate.fits.reduce((n, f) => n + f.joins.degenerate, 0)} joins have undefined
                      tangents.
                    {/if}
                    {#if fitCandidate.fits.some((f) => f.joins.issues.length)}
                      Inspect marked joins before applying.
                    {:else}
                      No tangent breaks above 1° detected.
                    {/if}
                  </p>
                {/if}
                <button disabled={!fitCandidate} onclick={applyContourFit}
                  >Apply fitted contours</button
                >
                <button onclick={cancelContourFit}>Cancel contour fit</button>
              {/if}
              <p class="hint">
                Fits straight fill outlines in stage units. Preview before applying. Further merge
                painting may flatten curves again.
              </p>
            {/if}

            {#if primary.kind === 'path' && !primary.closed && !primary.contours}
              <label class="property-line"
                >Tolerance<input
                  aria-label="Path simplification tolerance"
                  type="number"
                  min="0.01"
                  max="100"
                  step="0.1"
                  bind:value={simplifyTolerance}
                /></label
              >
              <button disabled={activeLayer.locked} onclick={simplifySelection}
                >Simplify path</button
              >
              <p class="hint">
                Removes redundant pencil points within the tolerance in stage units. Keeps
                endpoints; does not simplify closed paths or brushes.
              </p>
            {/if}
            <button
              disabled={activeLayer.locked ||
                activeLayer.drawingMode === 'merge' ||
                !primary.strokeWidth}
              onclick={convertStroke}>Convert stroke to fill</button
            >
            {#if primary.kind !== 'bezier' && !primary.contours}<button onclick={convertPath}
                >Convert to editable path</button
              >{/if}{#if primary.nodes || primary.kind === 'path'}<button
                onclick={() => smoothSelection()}>Smooth</button
              ><button onclick={() => smoothSelection(true)}>Straighten</button
              >{/if}{#if primary.kind === 'bezier'}<label class="property-line"
                >Closed<input
                  aria-label="Closed path"
                  type="checkbox"
                  checked={primary.closed}
                  onchange={(e) => setStyle({ closed: e.currentTarget.checked })}
                /></label
              >
              <p class="hint">
                Subselection (A): drag nodes or tangent handles. Opposite handles keep their length.
                Alt-drag moves one handle independently.
              </p>{/if}
          </DockPanel>{/if}
      {:else}<DockPanel id="document" heading="DOCUMENT SETTINGS" blocked={liveInputBlocked()||!!liveCurveConfig}>
          <div class="property-grid">
            {#each [['width', 'Width'], ['height', 'Height'], ['fps', 'FPS'], ['duration', 'Frames']] as [field, label]}<label
                >{label}<input
                  aria-label={label}
                  type="number"
                  min="1"
                  disabled={!!canvasResize || !!scopedSymbol && field !== 'duration'}
                  value={field === 'width' || field === 'height' ? displayedCanvasSize[field] : project[field as 'duration']}
                  onchange={(e) => {
                    documentNumber(field as 'width', e.currentTarget.value);
                    e.currentTarget.value = String(project[field as 'width']);
                  }}
                /></label
              >{/each}
          </div>
          {#if !scopedSymbol}
            {#if canvasResize}
              <div class="button-row">
                <button type="button" class="primary-button" bind:this={acceptCanvasSizeButton}
                  onclick={() => finishCanvasResize(true)}>Accept</button>
                <button type="button" onclick={() => finishCanvasResize(false)}>Cancel</button>
              </div>
            {:else}
              <button type="button" bind:this={resizeCanvasButton} disabled={canvasResizeBlocked()}
                onclick={beginCanvasResize}>Resize canvas</button>
            {/if}
          {/if}
          <label class="property-line"
            >Stage color<input
              type="color"
              aria-label="Stage color"
              value={project.background}
              onchange={(e) =>
                edit('Change stage color', () => (project.background = e.currentTarget.value))}
            /></label
          >
        </DockPanel>{/if}
      <DockPanel id="layer" heading="LAYER" blocked={liveInputBlocked()||!!liveCurveConfig}>

        <input
          class="full-input"
          aria-label="Layer name"
          value={activeLayer.name}
          onchange={(e) =>
            edit('Rename layer', () => (activeLayer.name = e.currentTarget.value.slice(0, 80)))}
        />
        <p class="hint">
          {activeLayer.locked ? 'Locked' : 'Editable'} · {shapes.length} object{shapes.length === 1
            ? ''
            : 's'} at frame {frame + 1}
        </p>
      </DockPanel>
      <DockPanel id="color" heading="COLOR">
        <ColorPanel targets={colorTargets()} {projectColors}
          scope={JSON.stringify([project.id, scopedSymbol?.session.id, layerId, frame, selected, historyTick])} />
      </DockPanel>
      <DockPanel id="defaults" heading="DRAWING DEFAULTS" blocked={liveInputBlocked()||!!liveCurveConfig}>

        <label class="property-line"
          >Pencil / stroke width<input
            aria-label="Drawing stroke width"
            type="number"
            min="0"
            max="200"
            bind:value={() => drawingStrokeWidth, setDrawingStrokeWidth}
          /></label
        >
        <p class="hint">
          Object mode preserves independent vectors. Experimental merge mode uses editable fill
          regions and stroke spans. Static symbols share library artwork; nested timelines are
          pending.
        </p>
      </DockPanel>
      <DockPanel id="library" heading="LIBRARY" blocked={liveInputBlocked()||!!liveCurveConfig}>

        <div role="group" aria-label="Library browser" class="library-browser" class:library-dragging={libraryDragging}
          ondragover={e=>{if(e.dataTransfer?.types.includes('Files')){e.preventDefault();e.stopPropagation();e.dataTransfer.dropEffect=libraryImportBlocked()?'none':'copy';libraryDragging=true;}}}
          ondragleave={e=>{if(!e.currentTarget.contains(e.relatedTarget as Node))libraryDragging=false;}}
          ondrop={e=>{if(e.dataTransfer?.files.length){e.preventDefault();e.stopPropagation();libraryDragging=false;void importBitmap([...e.dataTransfer.files]);}}}>
          <LibraryHeader bind:search={librarySearch} bind:kind={libraryKind} bind:sort={librarySort} bind:descending={libraryDescending} bind:name={symbolName}
            blocked={libraryImportBlocked(false)} audioAvailable={audioImportAvailable&&!!projectFolder&&license.savingAllowed}
            create={kind=>newLibrarySymbol(kind)} folder={name=>{newLibraryFolderName=name;addLibraryFolder();}}
            files={files=>void importBitmap(files)} audio={()=>openAudioImport(undefined,document.querySelector<HTMLElement>('summary[aria-label="New library item"]')??undefined)} convert={createSymbol} canConvert={!!selected.length&&!activeLayer.locked&&activeLayer.drawingMode!=='merge'&&!groupScope.length}/>
          <label>Folder<select aria-label="Library folder" bind:value={libraryFolder}><option value="">Library root</option>{#each libraryFolders as folder}<option value={folder.id}>{folder.path}</option>{/each}</select></label>
          <p class="hint">{librarySearch.trim() ? 'Searching all folders' : libraryFolder ? libraryFolders.find((f) => f.id === libraryFolder)?.path : 'Library root'} · {libraryItems.length} items</p>
          {#if libraryFolder}<button ondragover={libraryFolderDragOver} ondrop={e=>dropLibrary(e,currentLibraryFolder?.parentId??'')} onclick={() => libraryFolder = currentLibraryFolder?.parentId ?? ''}>Up one library folder</button>{/if}
          {#each (project.libraryFolders ?? []).filter((f) => (f.parentId ?? '') === libraryFolder).sort((a,b) => a.name.localeCompare(b.name)) as folder (folder.id)}
            <button class="library-folder-row" aria-label={'Open library folder ' + folder.name} ondragover={libraryFolderDragOver} ondrop={e=>dropLibrary(e,folder.id)} onclick={() => libraryFolder = folder.id}><LibraryIcon kind="folder"/>{folder.name}</button>
          {/each}
          {#if currentLibraryFolder}<details class="library-folder-properties"><summary>Folder properties</summary>
            <label>Folder name<input aria-label="Library folder name" maxlength="200" value={currentLibraryFolder.name} onchange={(e) => editLibraryFolder(e.currentTarget.value, currentLibraryFolder?.parentId)}/></label>
            <label>Parent folder<select aria-label="Library folder parent" value={currentLibraryFolder.parentId ?? ''} onchange={(e) => editLibraryFolder(currentLibraryFolder!.name, e.currentTarget.value)}><option value="">Library root</option>{#each libraryFolders.filter((f) => f.id !== libraryFolder) as folder}<option value={folder.id}>{folder.path}</option>{/each}</select></label>
            <button onclick={() => { const folder = currentLibraryFolder!; edit('Remove library folder', () => {removeLibraryFolder(project, folder.id); validateProject(project);}, true); }}>Remove library folder</button><p class="hint">Removing a folder moves its items and subfolders to its parent. Artwork is kept.</p>
          </details>{/if}
          <p class="library-drop-hint">Drop images here to import</p>
        <div class="library-preview" aria-label="Library preview">
          {#if libraryPicked().length===1}
            {@const picked=libraryPicked()[0]}
            {#if picked.kind==='symbol'}<LibraryPreview symbol={picked.symbol} assets={project.assets} symbols={project.symbols}/>
            {:else if picked.kind==='bitmap'&&picked.asset.bitmap?.dataUrl}<img src={picked.asset.bitmap.dataUrl} alt={'Library preview '+picked.name}/>{/if}
            <strong>{picked.name}</strong><span>{picked.kind==='symbol'?librarySymbolType(picked.symbol):picked.kind}</span>
          {:else}<span>{librarySelection.selected.length?librarySelection.selected.length+' items selected':'Select an item to preview'}</span>{/if}
        </div>
        <div class="library-list-heading"><span></span><button onclick={()=>{libraryDescending=librarySort==='name'?!libraryDescending:false;librarySort='name';}}>Name</button><button onclick={()=>{libraryDescending=librarySort==='link'?!libraryDescending:false;librarySort='link';}}>Link name</button></div>
        <div class="library-list" role="listbox" aria-label="Library items" aria-multiselectable="true" tabindex="0" onkeydown={libraryKeys}
          ondragend={()=>{libraryDragOwner=null;}}
          oncontextmenu={e=>openLibraryContext(e)} onclick={e=>{if(e.target===e.currentTarget)librarySelection={selected:[]};}}>
        {#each libraryItems as item (item.kind + ':' + item.id)}
          {@const rowKey=libraryKey(item)}
          {#if item.kind === 'symbol'}
            {@const symbol = item.symbol}

          <div role="group" aria-label={'Symbol ' + symbol.name} data-library-item="symbol">
            <LibraryRow name={item.name} kind={librarySymbolType(symbol)} link={libraryLinkName(project,item.kind,item.id)} itemKey={rowKey}
              selected={librarySelection.selected.includes(rowKey)} active={librarySelection.focus===rowKey}
              error={error} properties={libraryProperties===rowKey} renaming={libraryRenaming===rowKey}
              pick={e=>pickLibrary(e,rowKey)} context={e=>openLibraryContext(e,rowKey)} edit={()=>editLibraryItem(rowKey)}
              rename={()=>libraryRenaming=rowKey} commitName={name=>renameLibrary(rowKey,name)} cancelRename={()=>{libraryRenaming='';restoreLibraryFocus(rowKey);}} closeProperties={()=>{libraryProperties='';restoreLibraryFocus(rowKey);}} drag={e=>dragLibrary(e,rowKey)}>

            <label>Link name<input aria-label={'Link name '+symbol.name} placeholder="e.g. characters.Hero" value={libraryLinkName(project,'symbol',symbol.id)} maxlength="200" onchange={e=>{changeLibraryLink('symbol',symbol.id,e.currentTarget.value);e.currentTarget.value=libraryLinkName(project,'symbol',symbol.id);}}/></label>
            <label>Folder<select aria-label="Symbol library folder" value={libraryItemFolder(project, 'symbol', symbol.id)} onchange={(e) => moveLibrary('symbol', symbol.id, e.currentTarget.value)}><option value="">Library root</option>{#each libraryFolders as folder}<option value={folder.id}>{folder.path}</option>{/each}</select></label>
            <label
              >Name<input
                aria-label="Symbol name"
                value={symbol.name}
                maxlength="200"
                onchange={(e) => {
                  const name = e.currentTarget.value.trim();
                  if (name)
                    edit('Rename symbol', () => {
                      symbol.name = name;
                    });
                }}
              /></label
            >
            <button
              disabled={activeLayer.locked || !activeLayer.visible || !!groupScope.length}
              onclick={() => placeSymbol(symbol.id)}>Place symbol</button
            >
            <button
              disabled={!!penDraft}
              onclick={() => {
                if (!penDraft)
                  edit(
                    'Duplicate symbol definition',
                    () => {
                      const copy = duplicateSymbol(project, symbol.id);
                      setLibraryLink(project,'symbol',copy.id,suggestLibraryLink(project,copy.name));
                      const folder = libraryItemFolder(project, 'symbol', symbol.id);
                      if (folder) moveLibraryItem(project, 'symbol', copy.id, folder);
                    },
                    true,
                  );
              }}>Duplicate symbol</button
            >
            <button disabled={!!penDraft || foregroundBusy} onclick={() => editSymbolContents(symbol.id)}
              >Edit symbol artwork</button
            >
            <button
              disabled={!!penDraft || foregroundBusy}
              onclick={() => editSymbolContents(symbol.id, true)}>Edit symbol timeline</button
            >
            <button
              disabled={!selected.length ||
                selected.some((id) => shapes.find((s) => s.id === id)?.kind === 'symbol') ||
                activeLayer.locked ||
                !activeLayer.visible ||
                activeLayer.drawingMode === 'merge' ||
                !!groupScope.length ||
                !!penDraft}
              onclick={() => {
                if (!penDraft && !groupScope.length)
                  edit(
                    'Replace shared symbol artwork',
                    () => replaceSymbolArtwork(project, symbol.id, layerId, frame, selected),
                    true,
                  );
              }}>Replace artwork from selection</button
            >
            <p class="hint">
              Replacement updates every linked instance, including other frames and locked layers,
              fitting its existing bounds. Selected source artwork stays on stage. Make an instance
              unique first to edit only its definition.
            </p>
            <button
              disabled={symbolUsed(project, symbol.id)}
              onclick={() => {
                if (!symbolUsed(project, symbol.id))
                  edit('Remove symbol', () => {
                    project.symbols = project.symbols?.filter((s) => s.id !== symbol.id);
                    if (project.libraryItems) project.libraryItems = project.libraryItems.filter((item) => item.kind !== 'symbol' || item.id !== symbol.id);
                  if(project.libraryLinks)project.libraryLinks=project.libraryLinks.filter(item=>item.kind!=='symbol'||item.id!==symbol.id);
                  });
              }}>Remove symbol</button
            >
            </LibraryRow>
          </div>
          {:else if item.kind==='bitmap'}
            {@const asset = item.asset}

          {@const bitmap = asset.bitmap!}
          <div
            data-library-item="bitmap"
            role="group"
            aria-label={'Bitmap asset ' + bitmap.name}
            tabindex="-1"
            data-context="bitmap"
            data-context-id={asset.id}
            oncontextmenu={(e) => openLibraryContext(e, libraryKey(item))}
          >
            <LibraryRow name={item.name} kind="bitmap" link={libraryLinkName(project,item.kind,item.id)} itemKey={rowKey}
              selected={librarySelection.selected.includes(rowKey)} active={librarySelection.focus===rowKey}
              error={error} properties={libraryProperties===rowKey} renaming={libraryRenaming===rowKey}
              pick={e=>pickLibrary(e,rowKey)} context={e=>openLibraryContext(e,rowKey)} edit={()=>editLibraryItem(rowKey)}
              rename={()=>libraryRenaming=rowKey} commitName={name=>renameLibrary(rowKey,name)} cancelRename={()=>{libraryRenaming='';restoreLibraryFocus(rowKey);}} closeProperties={()=>{libraryProperties='';restoreLibraryFocus(rowKey);}} drag={e=>dragLibrary(e,rowKey)}>

            <label>Link name<input aria-label={'Link name '+bitmap.name} placeholder="e.g. textures.Paper" value={libraryLinkName(project,'bitmap',asset.id)} maxlength="200" onchange={e=>{changeLibraryLink('bitmap',asset.id,e.currentTarget.value);e.currentTarget.value=libraryLinkName(project,'bitmap',asset.id);}}/></label>
            <label>Folder<select aria-label="Bitmap library folder" value={libraryItemFolder(project, 'bitmap', asset.id)} onchange={(e) => moveLibrary('bitmap', asset.id, e.currentTarget.value)}><option value="">Library root</option>{#each libraryFolders as folder}<option value={folder.id}>{folder.path}</option>{/each}</select></label>
            {#if bitmap.dataUrl}<img
                src={bitmap.dataUrl}
                alt={bitmap.name}
                width="96"
                height="72"
                style="object-fit:contain;max-width:100%"
              />{:else}<p>Missing bitmap: {bitmap.name}</p>{/if}
            <label
              >Name<input
                aria-label="Bitmap name"
                value={bitmap.name}
                maxlength="200"
                onchange={(e) => {
                  const name = e.currentTarget.value.trim();
                  if (name)
                    edit('Rename bitmap', () => {
                      asset.bitmap!.name = name;
                    });
                }}
              /></label
            >
            <p class="hint">{bitmap.width} × {bitmap.height}</p>
            <button
              disabled={!bitmap.dataUrl || activeLayer.locked || !activeLayer.visible}
              onclick={() => useBitmap(asset.id, true)}>Place bitmap on stage</button
            >
            <button
              disabled={!bitmap.dataUrl ||
                activeLayer.locked ||
                !selected.some((id) =>
                  shapes.some(
                    (s) =>
                      s.id === id &&
                      (s.closed ||
                        ['rectangle', 'ellipse', 'polygon', 'brush', 'text'].includes(s.kind)),
                  ),
                )}
              onclick={() => useBitmap(asset.id, false)}>Apply bitmap fill</button
            >
            <button
              disabled={!bitmap.dataUrl}
              onclick={() => downloadBitmap(bitmap.dataUrl!, bitmap.name)}
              >Download bitmap PNG</button
            >
            <button
              disabled={bitmapUsed(asset.id)}
              onclick={() =>
                edit('Remove bitmap asset', () => {
                  project.assets = project.assets.filter((a) => a.id !== asset.id);
                  if (project.libraryItems) project.libraryItems = project.libraryItems.filter((item) => item.kind !== 'bitmap' || item.id !== asset.id);
                  if(project.libraryLinks)project.libraryLinks=project.libraryLinks.filter(item=>item.kind!=='bitmap'||item.id!==asset.id);
                })}>Remove bitmap</button
            >
            </LibraryRow>
          </div>
          {:else}
            {@const asset=item.asset}
            <div role="group" aria-label={'Audio asset '+item.name} data-library-item="audio">
              <LibraryRow name={item.name} kind="audio" link={libraryLinkName(project,item.kind,item.id)} itemKey={rowKey}
              selected={librarySelection.selected.includes(rowKey)} active={librarySelection.focus===rowKey}
              error={error} properties={libraryProperties===rowKey} renaming={libraryRenaming===rowKey}
              pick={e=>pickLibrary(e,rowKey)} context={e=>openLibraryContext(e,rowKey)} edit={()=>editLibraryItem(rowKey)}
              rename={()=>libraryRenaming=rowKey} commitName={name=>renameLibrary(rowKey,name)} cancelRename={()=>{libraryRenaming='';restoreLibraryFocus(rowKey);}} closeProperties={()=>{libraryProperties='';restoreLibraryFocus(rowKey);}} drag={e=>dragLibrary(e,rowKey)}>

                <label>Link name<input aria-label={'Link name '+item.name} value={libraryLinkName(project,'audio',item.id)} maxlength="200" onchange={e=>{changeLibraryLink('audio',item.id,e.currentTarget.value);e.currentTarget.value=libraryLinkName(project,'audio',item.id);}}/></label>
                <label>Folder<select aria-label="Audio library folder" value={item.folder} onchange={e=>moveLibrary('audio',item.id,e.currentTarget.value)}><option value="">Library root</option>{#each libraryFolders as folder}<option value={folder.id}>{folder.path}</option>{/each}</select></label>
                <p class="hint">{asset.audio!.sampleRate} Hz · {asset.audio!.channels} channels · {(asset.audio!.frames/asset.audio!.sampleRate).toFixed(2)} s</p>
                <button disabled={libraryActionBlocked(false)} onclick={()=>edit('Place library audio on timeline',()=>setAudioClips(project,[...(project.audioClips??[]),{id:id(),assetId:asset.id,startFrame:frame,offsetSamples:0,gain:1}]),true)}>Place audio on timeline</button>
                <button onclick={openAudioClips}>Edit audio clips</button>
              </LibraryRow>
            </div>
          {/if}
        {:else}<p>No items in this view. Import a bitmap, create a symbol or choose another folder.</p>{/each}
        </div>
        <div class="library-selection-footer"><span>{librarySelection.selected.length} selected</span><button disabled={!librarySelection.selected.length||libraryImportBlocked(false)||libraryPicked().some(libraryUsed)} onclick={()=>deleteLibrary()}>Delete selected library items</button></div>
        </div>
      </DockPanel>
      </div>
      </PanelWorkspace>
      </div>
    </aside>
  </main>
  {#if dropSurface && pendingRegionMove && !modal}
    <button type="button" aria-label="Drag pending paint selection" tabindex="-1" use:watchDropSurface
      style={`position:fixed;left:${dropSurface.left}px;top:${dropSurface.top}px;width:${dropSurface.width}px;height:${dropSurface.height}px;z-index:2;background:transparent;border:0;padding:0;touch-action:none;cursor:move`}
      onpointerdown={startRegrab} onpointermove={updateRegrab}
      onpointerup={e=>{updateRegrab(e);endRegrab(e,true);}}
      onpointercancel={e=>endRegrab(e)} onlostpointercapture={e=>endRegrab(e)}></button>
  {/if}
  <footer class="statusbar">
    {#if crossLayerMode}<button aria-label="Cancel cross-layer edit" disabled={!crossLayerJob} onclick={cancelCrossLayerChange}>Cancel edit</button>{/if}
    {#if smoothArtworkJob}<button onclick={cancelArtworkSimplification}>Cancel simplification</button>{/if}
    <span class="accent-dot"></span>{#if modal!=='export'}<span class="status-message">{status}</span>{/if}
    {#if historyNotice}<span role="status" title="Undo and Redo use a 16 MiB history budget per document.">{historyNotice}</span>{/if}
    {#if liveVisibleInterior || liveActiveInterior}
      {@const message = liveStageMessage || 'Live sampled artwork is read-only.'}
      <span class="status-message" role="status" aria-label="Live stage status" title={message}>{message}</span>
    {/if}
    {#if stageOpacity.error}<span role="alert">Opacity preview unavailable: {stageOpacity.error}</span>{/if}
    {#if modal!=='export'}
    {#if videoExport&&!mp4Finalizing}<button onclick={() => videoExport?.abort()}>Cancel {videoExportLabel} export</button>{/if}
    {#if gifExport}<button onclick={()=>gifExport?.abort()}>Cancel GIF export</button>{/if}
    {#if motionBake}<button onclick={()=>motionBake?.abort()}>Cancel remembered bake</button>{/if}
    {#if pngExport}<button onclick={() => pngExport?.abort()}>Cancel PNG export</button>{/if}
    {/if}
    <div class="top-spacer"></div>
    <span>{tools.find((t) => t.id === tool)?.label}</span><span class="status-shortcut"
      >{tool === 'select' ? [shortcutLabel('tool:select'), 'Shift for multi-select'].filter(Boolean).join(' · ') : 'Shift constrains shapes'}</span
    >
  </footer>
</div>

{#if libraryMoving}
  <dialog class="library-move-dialog" aria-label="Move library items" use:showFocusedDialog={'select'}
    oncancel={event=>{event.preventDefault();dismissLibraryMove();}} onkeydown={wrapDialogTab}>
    <h3>Move {libraryMoving.keys.length} library items</h3>
    <label>Folder<select aria-label="Move selected library items to folder" bind:value={libraryMoveTarget}><option value="">Library root</option>{#each libraryFolders as folder}<option value={folder.id}>{folder.path}</option>{/each}</select></label>
    <button onclick={confirmLibraryMove}>Move items</button>
    <button onclick={dismissLibraryMove}>Cancel library move</button>
  </dialog>
{/if}

{#if modal === 'scenes'}
  <SceneManager catalog={sceneCatalog} add={addScene} change={applySceneCommand}
    close={() => void closeSceneManager()} error={sceneError} />
{/if}

{#if exportWindowOpen}
  <dialog class="dialog export-dialog" aria-label="Export" use:showExportDialog={modal==='export'}
    onkeydown={wrapDialogTab} oncancel={event=>{event.preventDefault();if(!busy)modal=null;}}>
    <button class="dialog-close" aria-label="Close dialog" disabled={busy} onclick={()=>modal=null}>×</button>
<h2>Export</h2>
        <p>{project.name} · {project.width} × {project.height} · {project.fps} fps · {project.duration} frames</p>
        <label>Format<select aria-label="Export format" disabled={busy} bind:value={exportFormat}><option value="still">Single frame</option><option value="png">PNG image / sequence / sprite sheet</option><option value="gif">Animated GIF</option><option value="html">HTML animation</option>{#if !desktop}<option value="windows-app">Windows desktop app</option><option value="android-app">Android app</option><option value="ios-app">iPhone and iPad app</option>{/if}<option value="webm">WebM video / audio</option><option value="mp4">MP4 video</option><option value="ivf">IVF video</option><option value="ffmpeg">FFmpeg input bundle</option><option value="all">All formats</option></select></label>
        {#if !['still','windows-app','android-app','ios-app'].includes(exportFormat)}
        <div class="export-range"><label>Start frame<input aria-label="Export start frame" type="number" min="1" max={project.duration} disabled={busy} bind:value={exportRangeStart}/></label><label>End frame<input aria-label="Export end frame" type="number" min="1" max={project.duration} disabled={busy} bind:value={exportRangeEnd}/></label><button disabled={busy} onclick={useExportRange}>Use frame range</button></div>
        <p>Current frame: {frame+1}. Selected range: {rangeStart+1}–{rangeEnd+1}. Range commands use this timeline selection. HTML exports the full timeline. Each format keeps its supported background, playback and size limits.</p>
        {/if}
        <div class="export-options">
{#if exportFormat==='all'||exportFormat==='still'}<fieldset><legend>Single frame</legend>
              <label>Frame <input aria-label="Single frame number" type="number" min="1" max={project.duration} disabled={busy} bind:value={stillFrame}/></label>
              <label>File type <select aria-label="Single frame file type" disabled={busy} bind:value={stillFormat}>
                {#each stillFormats as choice (choice.id)}<option value={choice.id}>{choice.label}</option>{/each}
              </select></label>
              {#if stillChoice.transparency}
                <label><input type="checkbox" disabled={busy} bind:checked={stillTransparent}/>Transparent background</label>
              {/if}
              {#if stillFormat==='eps'}<p>EPS supports solid, opaque vector paths. Transparent background leaves the page unpainted.</p>{/if}
              {#if license.savingAllowed}
                <button disabled={busy || !Number.isInteger(stillFrame) || stillFrame < 1 || stillFrame > project.duration} onclick={()=>runConfiguredExport(downloadStill)}>Export frame…</button>
              {/if}
              {#if stillExport}<button onclick={()=>stillExport?.abort()}>Cancel single-frame export</button>{/if}
</fieldset>{/if}
{#if exportFormat==='all'||exportFormat==='html'}<fieldset><legend>HTML animation</legend>
              <p>{desktop ? 'Export a web folder.' : 'Extract the exported ZIP.'} Open index.html directly or upload the complete folder to your website.</p>
              <label>Canvas size<select aria-label="HTML canvas size" disabled={busy} bind:value={htmlCanvasSizing}>
                <option value="fit">Fit window</option>
                <option value="shrink">Shrink to fit</option>
                <option value="actual">Actual size</option>
              </select></label>
              <p>{htmlCanvasSizing==='fit' ? 'Scale up or down to fit the window.' : htmlCanvasSizing==='shrink' ? 'Scale down on smaller windows only.' : 'Use the project dimensions and scroll if needed.'}</p>
              <label>Audio<select aria-label="HTML audio format" disabled={busy||!htmlAudioAssets.length} bind:value={htmlAudioFormat}>
                <option value="none">No audio</option>
                <option value="opus" disabled={!htmlOpusAvailable}>Opus (smaller file)</option>
                <option value="wav">WAV (uncompressed)</option>
              </select></label>
              {#if htmlAudioAssets.length&&!htmlAudioAutomatic}
                <div hidden={htmlAudioFormat==='none'}>
                {#each htmlAudioAssets as asset (asset.id)}
                  <label>{asset.audio?.name??asset.path}<input type="file" accept=".wav,audio/wav"
                    aria-label={`WAV for ${asset.path}`} disabled={busy||htmlAudioFormat==='none'}
                    onchange={event=>{const files={...htmlAudioFiles};const file=event.currentTarget.files?.[0];if(file)files[asset.path]=file;else delete files[asset.path];htmlAudioFiles=files;}} /></label>
                {/each}
                </div>
              {/if}
              {#if license.savingAllowed}
                <button disabled={busy||!htmlAudioReady} onclick={()=>runConfiguredExport(()=>downloadConfiguredHTML(false))}>Export HTML animation…</button>
                <button disabled={busy||preview||!htmlAudioReady} onclick={()=>runConfiguredExport(()=>downloadConfiguredHTML(true))}>Export remembered HTML animation…</button>
              {/if}
              {#if htmlAudioExport}<button onclick={()=>htmlAudioExport?.abort()}>Cancel web folder export</button>{/if}

</fieldset>{/if}
{#if !desktop&&(exportFormat==='all'||exportFormat==='windows-app')}<fieldset><legend>Windows desktop app</legend>
              <p>Build the full animation as a standalone Windows app. Requires Rust, Microsoft C++ Build Tools and WebView2. Build and signing instructions are included.</p>
              {#if license.savingAllowed}
                <button disabled={busy} onclick={()=>runConfiguredExport(()=>downloadProjectApp('windows'))}>Export Windows app build kit…</button>
              {/if}
</fieldset>{/if}
{#if !desktop&&(exportFormat==='all'||exportFormat==='android-app')}<fieldset><legend>Android app</legend>
              <p>Build the full animation as an Android app. Requires JDK 17, Gradle and the Android SDK. Build and signing instructions are included.</p>
              {#if license.savingAllowed}
                <button disabled={busy} onclick={()=>runConfiguredExport(()=>downloadProjectApp('android'))}>Export Android app build kit…</button>
              {/if}
</fieldset>{/if}
{#if !desktop&&(exportFormat==='all'||exportFormat==='ios-app')}<fieldset><legend>iPhone and iPad app</legend>
              <p>Build the full animation in Xcode on a Mac. Build and signing instructions are included.</p>
              {#if license.savingAllowed}
                <button disabled={busy} onclick={()=>runConfiguredExport(()=>downloadProjectApp('ios'))}>Export iOS app build kit…</button>
              {/if}
            </fieldset>{/if}
{#if exportFormat==='all'||['png','ffmpeg'].includes(exportFormat)}<fieldset><legend>Image settings</legend>
<label><input type="checkbox" aria-label="Use remembered PNG motion" disabled={busy || desktop} bind:checked={pngRemembered} onchange={()=>{ffmpegOptionsRevision++;pngLiveRevision++;}}/>Evaluate remembered motion for PNG output</label>
              <label><input type="checkbox" disabled={busy || desktop} bind:checked={pngSheetTrim} onchange={()=>pngLiveRevision++}/>Trim transparent sprite borders</label>
              <label><input type="checkbox" disabled={busy || desktop || pngSheetPadding===0} bind:checked={pngSheetExtrude} onchange={()=>pngLiveRevision++}/>Extend sprite edges into padding</label>
              <label>Sprite sheet padding <select aria-label="PNG sprite sheet padding" disabled={busy || desktop} bind:value={pngSheetPadding} onchange={()=>pngLiveRevision++}><option value={0}>None</option><option value={1}>1 pixel</option><option value={2}>2 pixels</option><option value={4}>4 pixels</option></select></label>
              <label>PNG resolution <select aria-label="PNG export scale" disabled={busy || (desktop && exportFormat==='png')} bind:value={pngScale} onchange={()=>{ffmpegOptionsRevision++;pngLiveRevision++;}}><option value={0.5}>Half size</option><option value={1}>Document size</option><option value={2}>2× size</option><option value={4}>4× size</option></select></label>
              <label><input type="checkbox" disabled={busy || (desktop && exportFormat==='png')} bind:checked={pngTransparent} onchange={()=>{ffmpegOptionsRevision++;pngLiveRevision++;}} />Transparent PNG background</label>

</fieldset>{/if}
{#if license.savingAllowed && (exportFormat==='all'||exportFormat==='png')}<fieldset><legend>PNG image, sequence and sprite sheet</legend>
<button disabled={busy || desktop} title="Browser PNG export at the chosen resolution; nested playback starts at frame 1, buttons use Up state" onclick={()=>runConfiguredExport(()=>downloadPNG())}>Export current frame PNG…</button>
              <button disabled={busy || desktop} title="All timeline frames at the chosen resolution in one ZIP; buttons Up; browser archive limit 512 MiB" onclick={()=>runConfiguredExport(()=>downloadPNG(true))}>Export PNG sequence ZIP…</button>
              <button disabled={busy || desktop} title="PNG sprite sheet and frame rectangles in a ZIP; bounded raster size" onclick={()=>runConfiguredExport(()=>downloadPNG(true,false,true))}>Export PNG sprite sheet ZIP…</button>
              <button disabled={busy || desktop} onclick={()=>runConfiguredExport(()=>downloadPNG(true,true,true))}>Export selected PNG sprite sheet ZIP…</button>
              <button disabled={busy || desktop} title="Export selected main timeline frames; replay earlier frames to preserve nested clocks" onclick={()=>runConfiguredExport(()=>downloadPNG(true,true))}>Export selected PNG range ZIP…</button>
              {#if pngSavePicker}
                <button disabled={busy || desktop} onclick={()=>runConfiguredExport(()=>streamPNGSequence(false,true))}>Save PNG sprite sheet ZIP to file…</button>
                <button disabled={busy || desktop} onclick={()=>runConfiguredExport(()=>streamPNGSequence(true,true))}>Save selected PNG sprite sheet ZIP to file…</button>
              {/if}
              {#if pngSavePicker}<button disabled={busy || desktop} onclick={()=>runConfiguredExport(()=>streamPNGSequence(true))}>Save selected PNG range ZIP to file…</button>{/if}
              {#if pngSavePicker}<button disabled={busy || desktop} title="Stream PNG frames to a ZIP file without retaining the whole archive; ZIP64 output; filesystem limits apply; cancellation available until file finalization" onclick={()=>runConfiguredExport(()=>streamPNGSequence())}>Save PNG sequence ZIP to file…</button>{/if}

</fieldset>{/if}
{#if exportFormat==='all'||exportFormat==='gif'}<fieldset><legend>Animated GIF</legend>
<label><input type="checkbox" aria-label="Use remembered GIF motion" disabled={busy || desktop} bind:checked={gifRemembered}/>Evaluate remembered motion for GIF output</label>
              <label><input type="checkbox" disabled={busy || desktop} bind:checked={gifLoop}/>Loop GIF forever</label>
              <label><input type="checkbox" disabled={busy || desktop} bind:checked={gifTransparent}/>Transparent GIF background (white matte edges)</label>
              <label><input type="checkbox" disabled={busy || desktop} bind:checked={gifDither}/>Dither reduced GIF colors</label>
              <label><input type="checkbox" disabled={busy || desktop} bind:checked={gifCompress}/>Compress GIF with LZW dictionary</label>
              {#if license.savingAllowed}
                <button disabled={busy || desktop} title="Document size; up to 100 fps; bounded in-memory capture; colors may be reduced" onclick={()=>runConfiguredExport(()=>downloadGIF())}>Export GIF animation…</button>
                <button disabled={busy || desktop} onclick={()=>runConfiguredExport(()=>downloadGIF(true))}>Export selected GIF range…</button>
                <button disabled={busy || desktop || !gifSavePicker} onclick={()=>runConfiguredExport(()=>saveGIF())}>Save GIF animation to file...</button>
                <button disabled={busy || desktop || !gifSavePicker} onclick={()=>runConfiguredExport(()=>saveGIF(true))}>Save selected GIF range to file...</button>
              {/if}

</fieldset>{/if}
{#if exportFormat==='all'||['webm','mp4','ivf'].includes(exportFormat)}<fieldset><legend>Video settings</legend>
<label><input type="checkbox" aria-label="Use remembered video motion" oninput={()=>mp4OptionsRevision++} onchange={()=>mp4OptionsRevision++} disabled={busy || desktop || !videoEncodingAvailable} bind:checked={videoRemembered}/>Evaluate remembered motion for video output</label>
              <label>Video target bitrate <select aria-label="Video target bitrate" oninput={()=>mp4OptionsRevision++} onchange={()=>mp4OptionsRevision++} disabled={busy || desktop || !videoEncodingAvailable} bind:value={videoBitrate}><option value={1000000}>1 Mbps</option><option value={4000000}>4 Mbps</option><option value={10000000}>10 Mbps</option><option value={20000000}>20 Mbps</option></select></label>
              <label>Video keyframe interval <input aria-label="Video keyframe interval" oninput={()=>mp4OptionsRevision++} type="number" min="1" max="300" step="1" disabled={busy || desktop || !videoEncodingAvailable} bind:value={videoKeyFrameInterval} /></label>
              <small>1 makes every frame independent. Larger intervals can reduce file size. Target bitrate is not a file-size guarantee.</small>

</fieldset>{/if}
{#if exportFormat==='all'||exportFormat==='webm'}<fieldset><legend>WebM video and project audio</legend>
              {#if license.savingAllowed}
                <button disabled={busy || desktop || !videoEncodingAvailable} title="Lossy VP8 WebM video; no audio; requires browser video encoding" onclick={()=>runConfiguredExport(()=>downloadVideo(false, 'webm'))}>Export WebM video…</button>
                <button disabled={busy || desktop || !videoEncodingAvailable} title="Selected frames as lossy VP8 WebM video; no audio" onclick={()=>runConfiguredExport(()=>downloadVideo(true, 'webm'))}>Export selected WebM range…</button>
              {/if}
              <label>WebM audio bitrate <select aria-label="WebM audio bitrate" disabled={busy||desktop||!videoAudioAvailable} bind:value={videoAudioBitrate}><option value={64000}>64 kbps</option><option value={128000}>128 kbps</option><option value={192000}>192 kbps</option><option value={256000}>256 kbps</option></select></label>
              <label>WebM audio channels <select aria-label="WebM audio channels" disabled={busy||desktop||!videoAudioAvailable} bind:value={videoAudioChannels}><option value="preserve">Matching authored channels</option><option value="mono">Convert to mono</option><option value="stereo">Convert to stereo</option></select></label>
              <small>Audio commands use referenced project WAVs, converted to 48 kHz Opus. Choose files when saved audio storage is unavailable.</small>
              {#if license.savingAllowed}
                <button disabled={busy||desktop||!videoAudioAvailable||!project.audioClips?.length} onclick={()=>openVideoAudio()}>Export WebM with project audio…</button>
                <button disabled={busy||desktop||!videoAudioAvailable||!project.audioClips?.length} onclick={()=>openVideoAudio(true)}>Export selected WebM with project audio…</button>
                <button disabled={busy||desktop||!videoAudioAvailable||!project.audioClips?.length||!gifSavePicker} onclick={()=>openVideoAudio(false,true)}>Save WebM with project audio to file…</button>
                <button disabled={busy||desktop||!videoAudioAvailable||!project.audioClips?.length||!gifSavePicker} onclick={()=>openVideoAudio(true,true)}>Save selected WebM with project audio to file…</button>
                <button disabled={busy || desktop || !videoEncodingAvailable || !gifSavePicker} onclick={()=>runConfiguredExport(()=>downloadVideo(false, 'webm', true))}>Save WebM video to file…</button>
                <button disabled={busy || desktop || !videoEncodingAvailable || !gifSavePicker} onclick={()=>runConfiguredExport(()=>downloadVideo(true, 'webm', true))}>Save selected WebM range to file…</button>
              {/if}

</fieldset>{/if}
{#if license.savingAllowed && (exportFormat==='all'||exportFormat==='mp4')}<fieldset><legend>MP4 video</legend>
<button disabled={busy||desktop||!mp4EncodingAvailable} title="Browser Baseline H.264 MP4; document background; no audio; codec support depends on the browser" onclick={()=>runConfiguredExport(()=>downloadMp4())}>Export silent MP4 video…</button>
              <button disabled={busy||desktop||!mp4EncodingAvailable} title="Selected frames as silent Baseline H.264 MP4" onclick={()=>runConfiguredExport(()=>downloadMp4(true))}>Export selected silent MP4 range…</button>
              <button disabled={busy||desktop||!mp4EncodingAvailable||!gifSavePicker} title="Save complete silent MP4 through a transactional browser file destination" onclick={()=>runConfiguredExport(()=>downloadMp4(false,true))}>Save silent MP4 video to file…</button>
              <button disabled={busy||desktop||!mp4EncodingAvailable||!gifSavePicker} title="Save selected frames as silent MP4" onclick={()=>runConfiguredExport(()=>downloadMp4(true,true))}>Save selected silent MP4 range to file…</button>

</fieldset>{/if}
{#if license.savingAllowed && (exportFormat==='all'||exportFormat==='ivf')}<fieldset><legend>IVF video</legend>
<button disabled={busy || desktop || !videoEncodingAvailable} title="Lossy VP8 video in an IVF container; no audio; requires browser video encoding" onclick={()=>runConfiguredExport(()=>downloadVideo())}>Export IVF video…</button>
              <button disabled={busy || desktop || !videoEncodingAvailable} title="Selected frames as lossy VP8 video; no audio" onclick={()=>runConfiguredExport(()=>downloadVideo(true))}>Export selected IVF range…</button>
              <button disabled={busy || desktop || !videoEncodingAvailable || !gifSavePicker} onclick={()=>runConfiguredExport(()=>downloadVideo(false, 'ivf', true))}>Save IVF video to file…</button>
              <button disabled={busy || desktop || !videoEncodingAvailable || !gifSavePicker} onclick={()=>runConfiguredExport(()=>downloadVideo(true, 'ivf', true))}>Save selected IVF range to file…</button>

</fieldset>{/if}
{#if license.savingAllowed && (exportFormat==='all'||exportFormat==='ffmpeg')}<fieldset><legend>FFmpeg input bundle</legend>
{#if desktop}
              <button disabled={busy} onclick={()=>openNativeFFmpeg('timeline')}>Encode desktop timeline…</button>
              <button disabled={busy} onclick={()=>openNativeFFmpeg('range')}>Encode selected desktop range…</button>
              <button disabled={busy} onclick={()=>openNativeFFmpeg('bundle')}>Encode extracted FFmpeg input bundle…</button>
{:else}
<button disabled={busy || desktop} onclick={()=>openFFmpeg()}>Export FFmpeg input bundle…</button>
              <button disabled={busy || desktop} onclick={()=>openFFmpeg(true)}>Export selected FFmpeg inputs…</button>
              {#if gifSavePicker}<button disabled={busy || desktop} onclick={()=>openFFmpeg(false,true)}>Save FFmpeg input bundle to file…</button>
              <button disabled={busy || desktop} onclick={()=>openFFmpeg(true,true)}>Save selected FFmpeg inputs to file…</button>{/if}
{/if}

</fieldset>{/if}
</div>
        {#if error}<p role="alert">{error}</p><button onclick={()=>error=''}>Dismiss</button>{/if}
        <p role="status">{status}</p>
        {#if pngExport}<button onclick={()=>pngExport?.abort()}>Cancel PNG export</button>{/if}
        {#if gifExport}<button onclick={()=>gifExport?.abort()}>Cancel GIF export</button>{/if}
        {#if videoExport&&!mp4Finalizing}<button onclick={()=>videoExport?.abort()}>Cancel {videoExportLabel} export</button>{/if}
        {#if !license.savingAllowed}
          <button class="register-prompt" disabled={busy}
            onclick={() => { registerFromExport = true; helpDialog = 'register'; }}>Register to export</button>
        {/if}
        <button disabled={busy} onclick={()=>modal=null}>Close export</button>

  </dialog>
{/if}
{#if modal==='ffmpegExport'&&ffmpegConfig}{#key ffmpegConfig.id}<FFmpegExport save={ffmpegConfig.save} finalizing={ffmpegFinalizing} assets={ffmpegConfig.assets} automatic={ffmpegConfig.automatic} summary={ffmpegConfig.summary} working={!!ffmpegJob} message={status} failure={ffmpegFailure} start={downloadFFmpeg} cancel={()=>ffmpegJob?.abort()} close={ffmpegCloseFor(ffmpegConfig.id)}/>{/key}
{:else if modal==='nativeFFmpeg'}<NativeFFmpegExport capture={nativeCapture} validate={()=>{license.assertOutputAllowed();nativeCapture?.validate();}} close={()=>{nativeCapture=undefined;modal=exportWindowOpen?'export':null;}}/>
{:else if modal==='videoAudioExport'&&videoAudioConfig}{#key videoAudioConfig.id}<VideoAudioExport assets={videoAudioConfig.assets} automatic={videoAudioConfig.automatic} summary={videoAudioConfig.summary} save={videoAudioConfig.save} encoding={!!videoAudioJob} cancellable={!!videoAudioJob&&videoExport===videoAudioJob} message={status} failure={videoAudioFailure} start={downloadVideoAudio} cancel={()=>{if(videoAudioJob&&videoExport===videoAudioJob)videoAudioJob.abort();}} close={videoAudioCloseFor(videoAudioConfig.id)}/>{/key}
{:else if modal==='open'||modal==='save'}
  <ProjectFileDialog kind={modal} bind:name={saveName} {folders} {desktop} copy={!!projectFolder}
    {busy} {error} save={()=>save(true)} {open} close={()=>closeProjectFileDialog()}/>
{:else if modal==='programCheck'}
  <ScriptProgramCheck config={scriptProgramSnapshot.config} sources={scriptProgramSnapshot.sources} openSource={openProgramDiagnostic} dismiss={dismissScriptDialog} />
{:else if modal==='closeDocument' && closeDocumentPrompt}
  <dialog class="dialog close-document-dialog" aria-label="Close project" aria-describedby="close-document-title"
    use:showFocusedDialog={'.cancel-close-document'} onkeydown={wrapDialogTab}
    oncancel={event=>{event.preventDefault();cancelDocumentClose();}}>
    <button class="dialog-close" aria-label="Close dialog" disabled={busy} onclick={cancelDocumentClose}>×</button>
    <h2 id="close-document-title">Save changes to {closeDocumentPrompt.name}?</h2>
    <div class="button-row">
      <button class="primary-button" disabled={busy || !license.savingAllowed} onclick={saveAndCloseDocument}>Save and close</button>
      <button disabled={busy} onclick={discardAndCloseDocument}>Discard changes</button>
      <button class="cancel-close-document" disabled={busy} onclick={cancelDocumentClose}>Cancel</button>
    </div>
  </dialog>
{:else if modal==='scriptPreview'}
  <dialog class="dialog script-preview-dialog" aria-label="Preview saved scripts" use:showFocusedDialog={'.dialog-close'}
    onkeydown={wrapDialogTab} oncancel={event=>{event.preventDefault();dismissScriptDialog();}}>
    <button class="dialog-close" aria-label="Close dialog" onclick={dismissScriptDialog}>×</button>
    <ScriptPreview artwork={scriptArtwork!} config={scriptProgramSnapshot.config} sources={scriptProgramSnapshot.sources} validate={validateSceneScriptPreview} openSource={openProgramDiagnostic} loadScriptSound={scriptAudioLoader} />
  </dialog>
{:else if modal==='frameAnnotation' && frameAnnotationSession}
  {@const kind = frameAnnotationSession.kind}
  <dialog class="dialog frame-annotation-dialog" aria-label={`Edit frame ${kind}`}
    use:showFocusedDialog={'input, textarea'} onkeydown={wrapDialogTab}
    oncancel={event=>{event.preventDefault();dismissFrameAnnotation();}}>
    <button class="dialog-close" aria-label="Close dialog" onclick={dismissFrameAnnotation}>×</button>
    <h2>Frame {frameAnnotationSession.at + 1} {kind}</h2>
    <form onsubmit={event => {event.preventDefault();commitFrameAnnotation(frameAnnotationDraft);}}>
      {#if kind === 'label'}
        <label>Label<input aria-label="Frame label name" maxlength="80" required bind:value={frameAnnotationDraft} /></label>
      {:else}
        <label>Comment<textarea aria-label="Frame comment text" rows="4" maxlength={MAX_FRAME_COMMENT_LENGTH} required bind:value={frameAnnotationDraft}></textarea></label>
      {/if}
      {#if frameAnnotationError}<p role="alert">{frameAnnotationError}</p>{/if}
      <div class="button-row">
        <button type="submit">Save frame {kind}</button>
        {#if frameAnnotationSession.original}<button type="button" onclick={() => commitFrameAnnotation(null)}>Remove frame {kind}</button>{/if}
        <button type="button" onclick={dismissFrameAnnotation}>Cancel</button>
      </div>
    </form>
  </dialog>
{:else if modal==='layerProperties' && layerProperties}
  <dialog class="dialog layer-properties-dialog" aria-label="Layer properties"
    use:showFocusedDialog={'input[aria-label="Layer properties name"]'} onkeydown={wrapDialogTab}
    oncancel={event=>{event.preventDefault();dismissLayerProperties();}}>
    <button class="dialog-close" aria-label="Close dialog" onclick={dismissLayerProperties}>×</button>
    <LayerProperties {...layerProperties} cancel={dismissLayerProperties} />
    {#if layerPropertiesError}<p role="alert">{layerPropertiesError}</p>{/if}
  </dialog>
{:else if modal==='convertSymbol' && symbolConversion}
  <dialog class="dialog symbol-conversion-dialog" aria-label="Convert selection to symbol"
    use:showFocusedDialog={'input[aria-label="Symbol name"]'} onkeydown={wrapDialogTab}
    oncancel={event=>{event.preventDefault();symbolConversion?.cancel();}}>
    <button class="dialog-close" aria-label="Close dialog" onclick={symbolConversion.cancel}>×</button>
    <ConvertSymbol {...symbolConversion} />
  </dialog>
{:else if modal==='fontImport'}
  <dialog class="dialog font-import-dialog" aria-label="Embed project font"
    use:showFocusedDialog={'input[type="file"]'} onkeydown={wrapDialogTab}
    oncancel={event=>{event.preventDefault();dismissFontImport();}}>
    <button class="dialog-close" aria-label="Close dialog" onclick={dismissFontImport}>×</button>
    <FontImport importFile={importProjectFont} />
  </dialog>
{:else if modal==='traceBitmap' && bitmapTraceDialog}
  {#key bitmapTraceDialog}
    <dialog class="dialog bitmap-trace-dialog" aria-label="Trace bitmap"
      use:showFocusedDialog={'select'} onkeydown={wrapDialogTab}
      oncancel={event=>{event.preventDefault();bitmapTraceDialog?.cancel();}}>
      <button class="dialog-close" aria-label="Close dialog" onclick={bitmapTraceDialog.cancel}>×</button>
      <BitmapTraceDialog {...bitmapTraceDialog} />
    </dialog>
  {/key}
{:else if modal==='audioClips'}
  <dialog class="dialog audio-clips-dialog" aria-label="Edit audio clips"
    use:showFocusedDialog={'[data-audio-clip-add]:not(:disabled)'} onkeydown={wrapDialogTab}
    oncancel={event=>{event.preventDefault();dismissAudioClips();}}>
    <button class="dialog-close" aria-label="Close dialog" onclick={dismissAudioClips}>×</button>
    <AudioClips snapshot={audioClipSnapshot!} apply={applyAudioClips} />
  </dialog>
{:else if modal==='audioPreview'}
  <dialog class="dialog audio-preview-dialog" aria-label="Preview audio"
    use:showFocusedDialog={'input[type="file"]'} onkeydown={wrapDialogTab}
    oncancel={event=>{event.preventDefault();dismissAudioPreview();}}>
    <button class="dialog-close" aria-label="Close dialog" onclick={dismissAudioPreview}>×</button>
    <AudioPreview presentationProject={audioPreviewConfig.presentationProject} fps={audioPreviewConfig.fps} duration={audioPreviewConfig.duration} savedProject={audioPreviewConfig.savedProject} loadSaved={audioPreviewConfig.loadSaved} followFrame={audioPreviewConfig.followFrame} releaseFrame={audioPreviewConfig.releaseFrame} />
  </dialog>
{:else if modal==='audioImport'}
  <dialog class="dialog audio-import-dialog" aria-label="Import audio"
    use:showFocusedDialog={libraryAudioFile?'[data-import-audio]':'input[type="file"]'} onkeydown={wrapDialogTab}
    oncancel={event=>{event.preventDefault();dismissAudioImport();}}>
    <button class="dialog-close" aria-label="Close dialog" onclick={dismissAudioImport}>×</button>
    <AudioImport importFile={importAudioFile} initialFile={libraryAudioFile} />
  </dialog>
{:else if modal==='maskPreview' && maskPreviewConfig}
  {#key maskPreviewConfig.id}
    <dialog class="dialog mask-preview-dialog" aria-label="Preview layer mask"
      use:showFocusedDialog={'select'} onkeydown={wrapDialogTab}
      oncancel={event=>{event.preventDefault();dismissMaskPreview();}}>
      <button class="dialog-close" aria-label="Close dialog" onclick={dismissMaskPreview}>×</button>
      <MaskPreview {...maskPreviewConfig} />
    </dialog>
  {/key}
{:else if modal==='rememberedPreview' && rememberedPreview}
  <dialog class="dialog remembered-preview-dialog" aria-label="Preview remembered motion"
    use:showFocusedDialog={'input[aria-label="Remembered preview frame"]'} onkeydown={wrapDialogTab}
    oncancel={event=>{event.preventDefault();dismissRememberedPreview();}}>
    <button class="dialog-close" aria-label="Close dialog" onclick={dismissRememberedPreview}>×</button>
    <RememberedMotionPreview {...rememberedPreview} />
  </dialog>
{:else if modal==='livePreview' && livePreviewConfig}
  {#key livePreviewConfig.id}
    <dialog class="dialog live-preview-dialog" aria-label="Preview live timeline"
      use:showFocusedDialog={'input[aria-label="Live preview frame"]'} onkeydown={wrapDialogTab}
      oncancel={event=>{event.preventDefault();dismissLivePreview();}}>
      <button class="dialog-close" aria-label="Close dialog" onclick={dismissLivePreview}>×</button>
      <LiveMotionPreview {...livePreviewConfig} />
    </dialog>
  {/key}
{:else if modal==='liveMovie' && liveMovieConfig}
  {#key liveMovieConfig.id}
    <dialog class="dialog script-preview-dialog" aria-label="Test live movie"
      use:showFocusedDialog={'[data-live-movie-clocks]'} onkeydown={wrapDialogTab}
      oncancel={event=>{event.preventDefault();liveMovieConfig?.close();}}>
      <button class="dialog-close" aria-label="Close dialog" onclick={liveMovieConfig.close}>×</button>
      <LiveTestMovie {...liveMovieConfig} />
    </dialog>
  {/key}
{:else if modal==='liveRemove' && liveRemoveConfig}
  {#key liveRemoveConfig.id}
    <dialog class="dialog script-preview-dialog" aria-label="Remove live tween"
      use:showFocusedDialog={'input:checked:not(:disabled)'} onkeydown={wrapDialogTab}
      oncancel={event=>{event.preventDefault();dismissLiveRemove();}}>
      <button class="dialog-close" aria-label="Close dialog" onclick={dismissLiveRemove}>×</button>
      <LiveMotionRemove {...liveRemoveConfig} />
    </dialog>
  {/key}
{:else if modal==='liveEdit' && liveEditConfig}
  {#key liveEditConfig.id}
    <dialog class="dialog script-preview-dialog" aria-label="Edit live tween"
      use:showFocusedDialog={{selector:'[data-live-edit-recipe]:checked:not(:disabled)',scroll:true}} onkeydown={wrapDialogTab}
      oncancel={event=>{event.preventDefault();dismissLiveEdit();}}>
      <button class="dialog-close" aria-label="Close dialog" onclick={dismissLiveEdit}>×</button>
      <LiveMotionEdit {...liveEditConfig} />
    </dialog>
  {/key}
{:else if modal==='liveCreate' && liveCreateConfig}
  {#key liveCreateConfig.id}
    <dialog class="dialog script-preview-dialog" aria-label="Create live tween"
      use:showFocusedDialog={{selector:'input[aria-label="Live tween start frame"]',scroll:true}} onkeydown={wrapDialogTab}
      oncancel={event=>{event.preventDefault();dismissLiveCreate();}}>
      <button class="dialog-close" aria-label="Close dialog" onclick={dismissLiveCreate}>×</button>
      <LiveMotionCreate {...liveCreateConfig} />
    </dialog>
  {/key}
{:else if modal==='liveSplit' && liveSplitConfig}
  {#key liveSplitConfig.id}
    <dialog class="dialog script-preview-dialog"
      aria-label={liveSplitConfig.mode==='group'?'Insert live group tween key':liveSplitConfig.mode==='graphic'?'Insert live graphic tween key':liveSplitConfig.mode==='movie'?'Insert live movie tween key':liveSplitConfig.mode==='movie-tree'?'Insert live nested movie tween key':'Insert live tween key'}
      use:showFocusedDialog={{selector:'input[aria-label$="split frame"]',scroll:true}} onkeydown={wrapDialogTab}
      oncancel={event=>{event.preventDefault();liveSplitConfig?.close();}}>
      <button class="dialog-close" aria-label="Close dialog" onclick={liveSplitConfig.close}>×</button>
      {#if liveSplitConfig.mode==='group'}<LiveGroupMotionSplit {...liveSplitConfig} prepare={liveSplitConfig.prepare!} />
      {:else if liveSplitConfig.mode==='graphic'}<LiveGraphicMotionSplit {...liveSplitConfig} prepare={liveSplitConfig.prepare!} />
      {:else if liveSplitConfig.mode==='movie-tree'}<LiveMovieTreeMotionSplit {...liveSplitConfig} prepare={liveSplitConfig.prepare!} />
      {:else if liveSplitConfig.mode==='movie'}<LiveMovieMotionSplit {...liveSplitConfig} prepare={liveSplitConfig.prepare!} />
      {:else}<LiveMotionSplit {...liveSplitConfig} />{/if}
    </dialog>
  {/key}
{:else if modal==='timelineTween' && timelineTween?.hintSource}
  <dialog class="dialog script-preview-dialog shape-hint-dialog" aria-label="Edit shape hints"
    use:showFocusedDialog={{selector:'input[aria-label="Shape tween node pairs"]',scroll:true}} onkeydown={wrapDialogTab}
    oncancel={event=>{
      event.preventDefault();
      if(!liveShapeHints?.leaveStagePicking())dismissTimelineTween();
    }}>
    <button class="dialog-close" aria-label="Close dialog" onclick={dismissTimelineTween}>×</button>
    <LiveShapeHints bind:this={liveShapeHints} stage={canvas} view={{width:viewWidth,height:viewHeight,matrix:camera.matrix,zoom}}
      source={timelineTween.hintSource} apply={timelineTween.apply} cancel={dismissTimelineTween} />
  </dialog>
{:else if modal==='timelineTween' && timelineTween}
  <dialog class="dialog script-preview-dialog"
    aria-label={timelineTween.timingOnly ? 'Edit motion tween easing' : `Convert to ${timelineTween.kind} tween`}
    use:showFocusedDialog={timelineTween.timingOnly ? 'select[aria-label="Tween easing"]' : 'input[aria-label="Tween start frame"]'} onkeydown={wrapDialogTab}
    oncancel={event=>{event.preventDefault();dismissTimelineTween();}}>
    <button class="dialog-close" aria-label="Close dialog" onclick={dismissTimelineTween}>×</button>
    <TimelineTween {...timelineTween} cancel={dismissTimelineTween} />
  </dialog>
{:else if modal === 'help'}
  <dialog class="dialog editor-help-dialog"
    aria-label="Editor help"
    use:showFocusedDialog={'.dialog-close'}
    onkeydown={wrapDialogTab}
    oncancel={event => { event.preventDefault(); closeEditorHelp(); }}>
    <button type="button" class="dialog-close" aria-label="Close dialog" onclick={closeEditorHelp}>×</button>
    <h2>Editor help</h2>
    <p>
      Draw and edit vector artwork, organize it in layers, and animate symbols with keyframes
      and tweens. Save your work as a project folder or choose File → Export to see the formats
      available in this editor.
    </p>
    <h3>Default shortcuts</h3>
    <dl>
      <dt>V / R / O / N / Y</dt>
      <dd>Selection / rectangle / oval / line / pencil</dd>
      <dt>F5 / F6 / F7</dt>
      <dd>Insert frame / keyframe / blank keyframe</dd>
      <dt>Shift + F5 / Shift + F6</dt>
      <dd>Delete selected frames / remove selected keyframes</dd>
      <dt>Enter / Ctrl or Cmd + Enter</dt>
      <dd>Play timeline / accelerated preview</dd>
      <dt>Ctrl or Cmd + Z / Shift + Z</dt>
      <dd>Undo / redo</dd>
      <dt>Ctrl or Cmd + S / O / D</dt>
      <dd>Save / open / duplicate selection</dd>
    </dl>
    <p class="hint">Change bindings in Window → Keyboard Shortcuts.</p>
    <p class="hint">
      In the browser editor, use Control → Preview saved scripts to run frame scripts.
      Timeline playback, Test Movie and ordinary exports run without frame scripts.
    </p>
  </dialog>
{/if}
{#if preview}
    <dialog
      class="preview-dialog"
      aria-label="Test movie"
      use:showFocusedDialog={'[data-close-movie]'}
      onkeydown={movieDialogKeys}
      oncancel={event=>{event.preventDefault();closePreview();}}
    >
      <div class="panel-heading">
        <strong>{previewRemembered?'REMEMBERED TEST MOVIE':'TEST MOVIE'}</strong><span>{previewEngine}</span>
        <div class="top-spacer"></div>
        {#if previewRemembered}<button disabled={previewPreparing||!!previewFailure} onclick={()=>{playing=!playing;}}>{playing?'Pause remembered movie':'Play remembered movie'}</button>{/if}
        <button data-close-movie onclick={()=>closePreview()}>Close ×</button>
      </div>
      {#if previewPreparing}<p role="status">{previewEngine === 'Waiting for project fonts' ? 'Close cancels the preview.' : 'Preparing remembered movie. Close cancels preparation.'}</p>{/if}
      {#if previewFailure}<p role="alert">{previewFailure}</p>{/if}
      {#if previewRemembered&&!testButtons.length}<p>Button activations: {testActivations}</p>{/if}
      {#if testButtons.length}<p>
          Button test: {testButtons.find((b) => b.token === testFocused)?.name ?? 'None'} · Activations:
          {testActivations}. Focus the canvas; Left/Right selects a button, Space/Enter activates.
          Movies inside button poses run independently; changing the mapped frame restarts them.
        </p>{/if}
      <canvas
        bind:this={previewCanvas}
        width={project.width}
        height={project.height}
        tabindex="0"
        role="button"
        aria-label="Test movie interaction"
        aria-disabled={previewPreparing||!!previewFailure}
        style:visibility={previewPreparing||!!previewFailure?'hidden':'visible'}
        onpointerdown={testButtonDown}
        onpointermove={testButtonMove}
        onpointerup={testButtonUp}
        onpointerleave={() => {
          testOver = null;
        }}
        onpointercancel={resetTestButtonPress}
        onlostpointercapture={(e) => {
          if (testPointer===e.pointerId&&!previewCanvas.hasPointerCapture(e.pointerId)) resetTestButtonPress();
        }}
        onblur={resetTestButtonPress}
        onkeydown={(e) => testButtonKey(e)}
        onkeyup={(e) => testButtonKey(e, true)}
      ></canvas>
    </dialog>
{/if}
